window.__TRANSKY_SCREEN_DATA__=window.__TRANSKY_SCREEN_DATA__||[];window.__TRANSKY_SCREEN_DATA__.push("月租金。苏雨晴布置小屋，将起司猫玩偶、木笔筒、日记和读物放好，谨慎分配剩余钱款。第一次拥有私人空间使她兴奋，也让她开始学习独立生活的预算。\",\"turn\":\"获得稳定住所，但首月工资已预支支付房租，日常预算仍然很紧。\"},\"c009\":{\"key\":\"c009\",\"title\":\"第一次上班（上）\",\"kind\":\"main\",\"start\":54,\"end\":57,\"summary\":\"苏雨晴初次还价失败，买下棕白格棉被，又添置洗漱用品和泡沫地垫，布置出小小的卧室。她为次日工作设好闹钟，因缺钱只能用冷水洗漱。第二天清晨，她戴帽遮住短发出门，正式读到工作地点的名字“无名面馆”。\",\"turn\":\"她带着长发愿望进入劳动生活，独立小屋也需要自己悉心打理。\"},\"c010\":{\"key\":\"c010\",\"title\":\"第一次上班（下）\",\"kind\":\"main\",\"start\":58,\"end\":61,\"summary\":\"面馆老板娘让苏雨晴称她张阿姨，老板为李叔叔，两人给她早餐并温和照顾。张阿姨劝她感激父母，使她想起无法诉说的身份冲突。第一次上班，她羞于大声报单、遭熟客玩笑，仍认真完成工作；列车上的年轻男子再次来店吃饭并鼓励她。\",\"turn\":\"夫妻的照顾与不完全理解并存；与莫空再次相遇。\"},\"c011\":{\"key\":\"c011\",\"title\":\"真正迈出那一步\",\"kind\":\"main\",\"start\":62,\"end\":65,\"summary\":\"劳累回家后，苏雨晴看到青春期变化，害怕身体朝不愿的方向发育，依网络朋友提供的信息决定持续自行用药。她回忆查阅性别转换资料的经历，盼望未来手术。当夜她处理磨伤的双脚后入睡，却很快因噩梦、心悸和胸闷醒来。\",\"turn\":\"身份追求进入持续用药阶段，同时出现身体不适。\"},\"c012\":{\"key\":\"c012\",\"title\":\"失眠\",\"kind\":\"main\",\"start\":66,\"end\":69,\"summary\":\"彻夜失眠又脚伤未愈的苏雨晴冒雨艰难上班，怀疑不适与自行用药有关。张阿姨和李叔叔让她休息、准备鸡腿炒面，她困得无法吃完便睡下。梦中她来到荒芜公园，遇见与自己相似却没有影子的小男孩，对方请求她下次带自己离开。\",\"turn\":\"第一次出现反复荒园梦，身体虚弱中也获得雇主的体谅与照顾。\"},\"c013\":{\"key\":\"c013\",\"title\":\"那朦胧的雨\",\"kind\":\"main\",\"start\":70,\"end\":73,\"summary\":\"苏雨晴睡醒后身体稍有恢复，老板夫妻主动把上班时间改为九点，并给她每周一休假。年轻写作者来店谈旅行、工作和饮食，坦言自己只是打零工与写故事的人。他的平和让她好奇；雨景又勾起她对父母是否寻找自己的复杂挂念。\",\"turn\":\"获得休息制度；莫空的生活态度引起她注意。\"},\"c014\":{\"key\":\"c014\",\"title\":\"苏雨晴的日记\",\"kind\":\"main\",\"start\":74,\"end\":77,\"summary\":\"苏雨晴借面馆的伞回家，另开一本路灯封面的日记，记下三月六日用药不适、安家和对年轻男人的印象，向未来自己发问。当晚她再梦见荒园男孩，男孩为接近梦想不断吃石头，明知痛苦仍坚持，反问她要找的东西是否找到。\",\"turn\":\"日记确立明确日期；吃石头梦境呼应她的用药选择。\"},\"c015\":{\"key\":\"c015\",\"title\":\"螺内酯的副作用\",\"kind\":\"main\",\"start\":78,\"end\":81,\"summary\":\"苏雨晴因夜间频繁起身而再次睡不好，查看药品说明书，仍因害怕身体发育而没有改变自行用药。她忘记已推迟上班，清晨读鲁迅散文，从关于人生前路的文字中获得勇气，也反复思量出走对错，最后匆忙赶到面馆。\",\"turn\":\"她仍在惶恐中坚持选择，阅读成为孤身生活里整理思绪的方法。\"},\"c016\":{\"key\":\"c016\",\"title\":\"看板娘\",\"kind\":\"main\",\"start\":82,\"end\":85,\"summary\":\"高汤佐料厂家到面馆宣传，看中苏雨晴的外貌，愿付她两百元做一天发单员，也补偿面馆。她为添置生活用品接受任务，努力克服与陌生人交流的羞怯。年轻写作者接传单时无意碰到她手指，又爽快购货，使她开始猜想对方是否关照自己。\",\"turn\":\"首次额外收入机会，也出现对莫空的朦胧在意。\"},\"c017\":{\"key\":\"c017\",\"title\":\"日常用品采购\",\"kind\":\"main\",\"start\":86,\"end\":88,\"summary\":\"发单结束后，苏雨晴领到两百元，获准提前下班，并确认次日妇女节为休息日。她到大润发挑选促销生活用品，购入电热水壶、热水瓶、粉色碎花帘和洗晒用品。虽负担不起女装，她仍被折扣国产芭比套装吸引，另买零食犒劳自己。\",\"turn\":\"额外收入换来热水与隐私用品，她也为喜欢的娃娃打破节制。\"},\"c018\":{\"key\":\"c018\",\"title\":\"身体的轻微变化\",\"kind\":\"main\",\"start\":89,\"end\":92,\"summary\":\"苏雨晴独自费力安装帘子，终于能用新水壶烧热水洗澡。照镜时，她留意身体出现细微变化，又意识到生活中的重活和家务全须自己完成。洗衣使她想起母亲照顾，虽动摇、怀念，仍决定继续独立走下去。\",\"turn\":\"独立带来自主，也意味着无人代为承担家务与病痛。\"},\"c019\":{\"key\":\"c019\",\"title\":\"上班后的第一个假日\",\"kind\":\"main\",\"start\":93,\"end\":96,\"summary\":\"第一个休息日天气晴好，苏雨晴沿尚未贯通的新路散步，在水库河堤发现宁静草地。她短暂幻想只有自己一人的城市，却也感到寂寞。常来面馆的年轻写作者恰好出现，躺在旁边欣赏风景，并向紧张的她搭话。\",\"turn\":\"无人的自由并没有消除孤单，莫空的出现提供新的交流机会。\"},\"c020\":{\"key\":\"c020\",\"title\":\"想要变成鹰的鱼\",\"kind\":\"main\",\"start\":97,\"end\":100,\"summary\":\"河堤上，年轻男子讲述四处旅居与写作理想，苏雨晴因相似的非传统选择而放下戒备。他讲了一条鱼借魔法宝石变鹰的故事：鱼遭原有与未来同类排斥，终于飞翔却带伤死亡。苏雨晴被愿望、代价和不被接纳的主题触动落泪。\",\"turn\":\"寓言建立全书核心象征，也加深二人情感共鸣。\"},\"c021\":{\"key\":\"c021\",\"title\":\"黑猫\",\"kind\":\"main\",\"start\":101,\"end\":104,\"summary\":\"写作者悄然离开，苏雨晴懊悔尚未问名字。她遇到一只善游泳、会捕鱼的矫健黑猫，尊重它不愿被摸的距离。在河堤睡梦中，她把自己代入未能飞翔的鹰；傍晚黑猫拍醒她。返回途中，她走进热闹花店，尝试承受旁人的目光。\",\"turn\":\"猫的陪伴填补独处空隙，苏对还没来得及问姓名的写作者念念不忘。\"},\"c022\":{\"key\":\"c022\",\"title\":\"勿忘我\",\"kind\":\"main\",\"start\":105,\"end\":107,\"summary\":\"苏雨晴买一枝颜色极浅的勿忘我给自己，取“不忘初心”之意，用捡来的易拉罐当花瓶。她玩芭比、用纸做衣服，又后悔冲动花钱。夜间黑猫来窗外未能进入；她梦见勿忘我花海中一朵与众不同、显得孱弱的白花。\",\"turn\":\"勿忘我成为自我认同象征，白花梦境继续铺设。\"},\"c023\":{\"key\":\"c023\",\"title\":\"女色狼？\",\"kind\":\"main\",\"start\":108,\"end\":110,\"summary\":\"次日苏雨晴边劳动边期待写作者来店。一位高挑金发熟客出现，得知她的出生性别后要求看头发，并对被剃平头表示惋惜，似乎察觉这并非她所愿。但对方随后未经允许触碰她身体，使她惊惧躲开，视其为危险人物。\",\"turn\":\"张思凡以女装首次登场，关切与越界行为并存。\"},\"c024\":{\"key\":\"c024\",\"title\":\"曲奇\",\"kind\":\"main\",\"start\":111,\"end\":114,\"summary\":\"苏雨晴下班带回报纸，因预报暴雨而用铁丝在室内晾衣，继续写日记。河堤黑猫主动从窗台入内，她小心与它握爪、喂小鱼干，并因耳朵局部棕色为它取名“曲奇”，设想替它搭窝。猫吃完却离去，使她失落地以为只是自己一厢情愿。\",\"turn\":\"她主动命名并准备照顾曲奇，却尚不明白野猫会保留来去的自由。\"},\"c025\":{\"key\":\"c025\",\"title\":\"找不到答案的梦\",\"kind\":\"main\",\"start\":115,\"end\":118,\"summary\":\"苏雨晴再入荒园梦境，尝试翻墙逃出，却回到同一入口。秋千男孩身体更虚弱，开始吃五颜六色的糖果，解释这些东西让身体疼痛却能缓解心痛。她觉得对方无比熟悉，几乎想起自己遗失的东西，醒来却再次忘记。\",\"turn\":\"梦中身体与内心痛苦的交换更加明确，身份答案仍未揭示。\"},\"c026\":{\"key\":\"c026\",\"title\":\"黑网吧\",\"kind\":\"main\",\"start\":119,\"end\":122,\"summary\":\"雨天工作空闲，苏雨晴回忆初中唯一亲近的同桌：他护着受排斥的她，也常用玩笑和小礼物亲近她。下班后，她得知老板夫妻已购房，从打工生活中获得一点踏实感。随后她按食客提示来到杂货店暗门后的黑网吧，准备寻找网络同伴。\",\"turn\":\"旧同桌关系埋下伏笔；第一次在小城市接回网络关系。\"},\"c027\":{\"key\":\"c027\",\"title\":\"论坛\",\"kind\":\"main\",\"start\":123,\"end\":126,\"summary\":\"苏雨晴登录设于台湾的封闭论坛“药娘”圈子，以清泉身份查阅资料，并回复好友月橙。月橙得知她出走后愿寄钱，她因已有工作婉拒；二人意外发现同在小城市，约定下周一中心广场见面。她随后看《乱马二分之一》，羡慕其中轻易转换的身体。\",\"turn\":\"最亲近的网友原来近在同城，第一次现实会面终于可以安排。\"},\"c028\":{\"key\":\"c028\",\"title\":\"莫空\",\"kind\":\"main\",\"start\":127,\"end\":130,\"summary\":\"面馆生意繁忙，苏雨晴跑腿买雪菜后体力不支，端面险些洒出。年轻写作者及时扶住面碗，替她化解意外。她终于鼓起勇气问姓名，得知对方本名莫空、自取名或笔名莫成，二人正式交换名字。下班时，张阿姨送她牛奶补充营养。\",\"turn\":\"她终于知道写作者叫莫空，彼此从熟面孔成为能够互称姓名的人。\"},\"c029\":{\"key\":\"c029\",\"title\":\"做客的猫\",\"kind\":\"main\",\"start\":131,\"end\":133,\"summary\":\"苏雨晴洗澡后写下与月橙见面的期待，又画起曲奇。回忆揭示她童年被大量兴趣班占满，绘画是残留下来的自我表达方式。曲奇敲窗来访，带来一只尚活着的幼鼠；她虽嫌脏而惊退，仍逐渐明白猫可能是在送礼。\",\"turn\":\"曲奇以自身方式回报，人与猫之间的关系加深。\"},\"c030\":{\"key\":\"c030\",\"title\":\"猫和老鼠\",\"kind\":\"main\",\"start\":134,\"end\":137,\"summary\":\"曲奇把幼鼠当礼物，苏雨晴拒绝又不忍看到它被吃，试图请猫放过老鼠，曲奇最终叼鼠离开。当夜她梦见公园树木半荣半枯，男孩不在，她坐上秋千后醒来。腹泻让她极度虚弱，挣扎回床却没盖好被子，为次日患病埋下原因。\",\"turn\":\"苏的怜悯给幼鼠留下生路，梦境与腹泻却继续侵扰她的夜晚。\"},\"c031\":{\"key\":\"c031\",\"title\":\"着凉\",\"kind\":\"main\",\"start\":138,\"end\":141,\"summary\":\"苏雨晴着凉、头晕且食欲不振，仍因担心丢掉难得的工作而强撑上班。莫空看出她不舒服，帮她接过面碗并劝请假。他的关怀令她感到温暖，也使她意识到自己对这个温柔男性有了超出普通熟人的好感。\",\"turn\":\"疾病暴露经济压力，莫空逐渐成为情感依靠。\"},\"c032\":{\"key\":\"c032\",\"title\":\"好想找个人来陪\",\"kind\":\"main\",\"start\":142,\"end\":145,\"summary\":\"病中熬完工作，苏雨晴获张阿姨赠感冒药，回到小屋却仍须独自洗澡处理家务。她强烈想家、渴望陪伴，一度产生轻生念头，又主动用未来可能有伴侣的希望压下。梦里公园外的城市出现末日暴乱，她逃回公园后被坠落物惊入黑暗。\",\"turn\":\"短暂自杀意念后自我制止；末日内容仅为梦境。\"},\"c033\":{\"key\":\"c033\",\"title\":\"和月橙的约定\",\"kind\":\"main\",\"start\":146,\"end\":149,\"summary\":\"次日苏雨晴退热恢复，工作也比初来时熟练。李叔叔说夫妻把她当孩子，专门做丰盛盖饭；张阿姨怀疑她原本就是女孩而以男装保护自己，她仍没有顺势隐瞒出生性别。下班后她用公用电话与月橙确定周一九点、广场首饰店松树下相见。\",\"turn\":\"雇主的照顾使生活暂时安稳，网友相见的具体时间地点也已确定。\"},\"c034\":{\"key\":\"c034\",\"title\":\"拥挤的早晨\",\"kind\":\"main\",\"start\":150,\"end\":153,\"summary\":\"三月十五日，苏雨晴兴奋早起准备首次见网友。为省钱她乘公交，在拥挤与异味中十分难受，险些错过下车。抵达中心广场外围后找不到入口，她终于鼓起勇气向环卫阿姨问路，获得帮助后前往约定地点。\",\"turn\":\"现实会面在即，她仍须克服问路与乘车带来的羞怯和紧张。\"},\"c035\":{\"key\":\"c035\",\"title\":\"碰面\",\"kind\":\"main\",\"start\":154,\"end\":157,\"summary\":\"苏雨晴提前半小时来到松树下，月橙也早到却隔树焦急等待，两人起初彼此没有认出。确认身份后，月橙揭示自己正是此前金发女装熟客，本名张思凡。苏雨晴称她思思姐，逐渐消除紧张，二人从网络挚友转为现实朋友。\",\"turn\":\"清泉＝苏雨晴、月橙＝张思凡的身份链完整回收。\"},\"c036\":{\"key\":\"c036\",\"title\":\"百流山\",\"kind\":\"main\",\"start\":158,\"end\":161,\"summary\":\"张思凡解释自己在小城市读大学、靠父母汇款生活，瞒着家里用药两年，并担心出柜遭遇苏雨晴的处境。她答应送苏雨晴合身的巫女服。二人乘车去百流山，交流身份愿望、身体和家庭难题，随后开始攀登人烟稀少的山路。\",\"turn\":\"同类关系带来理解与互助，家庭接纳仍无解。\"},\"c037\":{\"key\":\"c037\",\"title\":\"纯黑色的蝴蝶\",\"kind\":\"main\",\"start\":162,\"end\":165,\"summary\":\"登山时，苏雨晴欣赏百流山特有的纯黑蝴蝶，谈起台湾外婆家和较包容的表亲。张思凡说明自己学计算机，希望日后能居家工作，也回忆曾是长跑体训队成员。二人对身体衰弱与手术经济门槛感到沮丧，最后把登顶当作坚持梦想的考验继续前行。\",\"turn\":\"互助登山映照身份追求；张思凡的体育与学业背景补齐。\"},\"c038\":{\"key\":\"c038\",\"title\":\"山巅绝景\",\"kind\":\"main\",\"start\":166,\"end\":168,\"summary\":\"经过多次休息，苏雨晴和张思凡终于登顶，在山泉旁补水并欣赏云海。二人进入荒废小庙，对信仰与宗教商业化意见不同：无信仰的张思凡怀疑，受家族影响信佛的苏雨晴整理蒲团、虔诚祈求。她仍尊重朋友的不同看法，并教对方祈愿。\",\"turn\":\"登顶让共同坚持有了结果，苏也学习在信仰不同中尊重朋友。\"},\"c039\":{\"key\":\"c039\",\"title\":\"石铸的剑\",\"kind\":\"main\",\"start\":169,\"end\":172,\"summary\":\"小庙中两人继续讨论磨难与信仰，苏雨晴发现佛像后暗门，里面供奉刻有小篆“轮回”的石剑。外侧临崖走廊令她恐高，张思凡拥抱安慰后带她下山。她们乘车到郊区终点站，再骑电动车去张思凡住处，路途逐渐进入乡野。\",\"turn\":\"神秘石剑留下命运线索，山行结束后两人将进入更私人的生活空间。\"},\"c040\":{\"key\":\"c040\",\"title\":\"集装箱房\",\"kind\":\"main\",\"start\":173,\"end\":176,\"summary\":\"张思凡带苏雨晴到草地与树林旁的集装箱房，说明自己购箱装修、租地独居，生活清静但通勤很远。她邀请苏雨晴合住，后者因工作地点拒绝。洗漱过程中，张思凡数次玩笑与未经允许的身体接触使苏雨晴害羞不安，随后双方停止越界玩闹。\",\"turn\":\"看见另一种独立生活可能；朋友相处仍存在边界问题。\"},\"c041\":{\"key\":\"c041\",\"title\":\"巫女服\",\"kind\":\"main\",\"start\":177,\"end\":180,\"summary\":\"张思凡拿出红白巫女服及配套衣物给苏雨晴试穿，尊重她想独自换装的要求。苏雨晴喜欢衣服，却被短发勾起难过；张思凡用纯黑长假发替她扎好马尾，鼓励她一起把真发留长。她解释自己的短发来自多次染发后主动重留。\",\"turn\":\"赠衣和假发缓解被剪发的伤心，真发留长仍需时间与安全空间。\"},\"c042\":{\"key\":\"c042\",\"title\":\"野餐\",\"kind\":\"main\",\"start\":181,\"end\":184,\"summary\":\"二人穿女装到集装箱外草地野餐，合作搬火盆，吃烧烤火锅，讨论围院种花的生活。张思凡好奇苏雨晴家族，后者说家族有祖山与祠堂、众多规矩，成员关系复杂，因此不喜欢家族束缚。此处家族历史是人物讲述，不能当作已核实史实。\",\"turn\":\"田园野餐给她们片刻自在，苏也进一步说明自己与家族的疏离。\"},\"c043\":{\"key\":\"c043\",\"title\":\"张思凡的生日\",\"kind\":\"main\",\"start\":185,\"end\":188,\"summary\":\"天黑后苏雨晴准备返家，张思凡低声请求她再陪一会儿，才说今天是自己二十岁生日。平日活泼的她流露独居孤单与惧怕父母得知身份的恐惧。苏雨晴替她插二十根蜡烛、唱生日歌，共享蛋糕，并答应留宿，由张思凡次日送她上班。\",\"turn\":\"张思凡的欢脱面具下显出脆弱，陪伴成为生日礼物。\"},\"c044\":{\"key\":\"c044\",\"title\":\"同眠\",\"kind\":\"main\",\"start\":189,\"end\":192,\"summary\":\"张思凡谈自己喜欢黑夜，因为黑暗能遮掩不被理解的身份，并把她们比作不会发光的星。两人同睡，苏雨晴依偎朋友梦中唤母亲，梦见父母完全接纳自己。次晨因离工作地点远而急忙起床，张思凡送她衣物，并骑电动车赶往面馆。\",\"turn\":\"父母接纳仅为梦境；现实友情提供短暂家庭感。\"},\"c045\":{\"key\":\"c045\",\"title\":\"一个月\",\"kind\":\"main\",\"start\":193,\"end\":195,\"summary\":\"叙事跳过约一个月，苏雨晴逐渐适应工作与生活，头发变长，却反复嗜睡、醒时恍惚。她参考张思凡经验自行调整用药，医学描述仅属小说设定。暴雨休息日，曲奇浑身湿透前来避雨，竟带着此前那只幼鼠，显示猫已把它当伙伴。\",\"turn\":\"猫鼠天敌关系转为共处；生活稳定而身体负担持续。\"},\"c046\":{\"key\":\"c046\",\"title\":\"咖啡\",\"kind\":\"main\",\"start\":196,\"end\":198,\"summary\":\"苏雨晴给曲奇和灰鼠清洗，逐渐放下对老鼠的嫌恶，给它取名咖啡。猫鼠互相照顾并接受喂食。她在四月十九日日记中写下张思凡忙学业、自己想买手机，也因父母一直没有消息而落泪；曲奇主动舔她脸颊，成为情绪上的安慰。\",\"turn\":\"咖啡得名；动物伙伴缓解被家人遗忘的感觉。\"},\"c047\":{\"key\":\"c047\",\"title\":\"普通的日子\",\"kind\":\"main\",\"start\":199,\"end\":201,\"summary\":\"暴雨中苏雨晴画下阴暗城市与上方一块留白的光，夹进日记。雨停后猫鼠离开，她打扫、晾衣，用劳动把小屋维持得温馨。洗澡后她再次换上张思凡赠的巫女服，正准备欣赏时，房东老虎突然敲门，令私人身份暴露风险骤然出现。\",\"turn\":\"绘画成为情绪表达；外界敲门打断私人自由。\"},\"c048\":{\"key\":\"c048\",\"title\":\"小混混\",\"kind\":\"main\",\"start\":202,\"end\":205,\"summary\":\"老虎来收二十三元水电费，苏雨晴慌忙藏好女装，房东又嫌她头发太长。午睡时她再梦见荒园男孩被打，答应以后帮忙。晚上她外出买嵌糕，抄近路穿小巷，遇见赌牌的绿毛、白狗等混混围堵，对方无视她要求离开的请求。\",\"turn\":\"梦中受欺凌与现实围堵相接，危险尚未解除。\"},\"c049\":{\"key\":\"c049\",\"title\":\"勇敢还是胆小？\",\"kind\":\"main\",\"start\":206,\"end\":209,\"summary\":\"混混无视苏雨晴的拒绝，对她实施猥亵、强行脱衣并准备进一步性侵；她挥拳反抗却被压制。路过少年看似逃跑，实际去叫来保安，及时阻止侵害。苏雨晴脱险后向少年致谢，认识到害怕与勇敢可以并存，冷静求援同样能救人。\",\"turn\":\"已发生猥亵与羞辱；进一步侵害被保安制止，混混逃跑。\"},\"c050\":{\"key\":\"c050\",\"title\":\"曲奇，早安\",\"kind\":\"main\",\"start\":210,\"end\":213,\"summary\":\"受袭后苏雨晴做连环噩梦，梦见自己受辱，又见荒园男孩重伤并杀死多个与其长相相同的施暴者，对方向她追问是否明白。醒后曲奇与咖啡来访，跟她出门并一路到面馆，让她在创伤后的早晨感到被陪伴与守护。\",\"turn\":\"梦中杀人不是现实事件；动物陪伴开始进入工作场所。\"},\"c051\":{\"key\":\"c051\",\"title\":\"曲奇相伴的工作\",\"kind\":\"main\",\"start\":214,\"end\":217,\"summary\":\"面馆夫妻接纳曲奇与咖啡，误以为咖啡是宠物鼠。苏雨晴熟练劳动并帮忙算账，莫空以整齐西装再来，教她简单心算技巧。他解释自己为维持生活暂做推销，喜欢尝试不同工作，又问她未来是否换工作、找男友，令她害羞。\",\"turn\":\"莫空呈现谋生压力与幽默，二人话题趋向私人生活。\"},\"c052\":{\"key\":\"c052\",\"title\":\"被爱情抓住的张思凡\",\"kind\":\"main\",\"start\":218,\"end\":221,\"summary\":\"张思凡带孙昊来面馆，举止显出恋爱中的羞涩。孙昊是她在网上认识的变身小说作者，外表英俊、待人得体，却令苏雨晴感到不安。莫空借醋瓶即兴描述苏雨晴工作的样子，逗她开心；曲奇也认识莫空。孙昊对张思凡体贴中含不容拒绝的态度。\",\"turn\":\"孙昊进入关系网，与莫空形成相处方式的对照。\"},\"c053\":{\"key\":\"c053\",\"title\":\"春祭\",\"kind\":\"main\",\"start\":222,\"end\":225,\"summary\":\"春祭使面馆连续繁忙，苏雨晴常走神、记单困难，下班累得进门即陷入半梦状态跌倒，幸被曲奇唤醒。猫鼠整夜陪伴，曲奇甚至替她关灯。周一休息日她洗晒衣被后想去附近孔庙，因缺少娱乐与钱，再次希望能拥有电脑。\",\"turn\":\"劳累影响状态，曲奇的照顾由陪伴转为具体帮助。\"},\"c054\":{\"key\":\"c054\",\"title\":\"孔庙\",\"kind\":\"main\",\"start\":226,\"end\":229,\"summary\":\"苏雨晴带曲奇、咖啡沿田间小径到孔庙，遇到外表魁梧但说话温柔的陌生人。她对这种反差感到不适又觉亲切。曲奇爬上孔子像，她把猫抱下；返程遇见壮汉采映山红，对方热心分享花朵，减轻了她的陌生感。\",\"turn\":\"胡玉牛登场；苏雨晴也需面对自己的外貌成见。\"},\"c055\":{\"key\":\"c055\",\"title\":\"两只思春的“少女”\",\"kind\":\"main\",\"start\":230,\"end\":233,\"summary\":\"壮汉自报胡玉牛，指明村中红色四层楼是住处，愿在她有困难时帮忙。苏雨晴来到河堤又遇张思凡，听她谈对孙昊既喜欢又不放心：孙昊明知其身份仍表白并专程探访，但有阴沉、占有欲强的一面。苏雨晴虽不喜欢他，仍试着鼓励朋友相信爱情。\",\"turn\":\"孙昊的不安信号已出现，二人尚以缺乏安全感解释。\"},\"c056\":{\"key\":\"c056\",\"title\":\"张思凡和孙昊的情话\",\"kind\":\"main\",\"start\":234,\"end\":237,\"summary\":\"张思凡转述孙昊承诺娶她、赚钱一同移民，又担心承诺不真实。孙昊来电时，苏雨晴避开去河边，险些失足，被莫空及时拉回。她因莫空又不告而别而生气，与张思凡离开；结尾揭示莫空其实下水抓河蟹，浮出时才发现她们走了。\",\"turn\":\"离去误会来自信息差；张孙关系仍处甜蜜承诺期。\"},\"c057\":{\"key\":\"c057\",\"title\":\"《我们所见到的就是真实吗？》\",\"kind\":\"main\",\"start\":238,\"end\":241,\"summary\":\"苏雨晴拒绝去张思凡家过夜，免得次日赶工，回程见曲奇与白猫亲近。她到新华书店读爱情小说，又被《我们所见到的就是真实吗？》吸引，思考感知、虚拟程序和身体身份。她既愿自己是真人，又幻想若是程序便能改变身体。\",\"turn\":\"虚拟世界哲学读物加入真实与梦境的主题线。\"},\"c058\":{\"key\":\"c058\",\"title\":\"春梦\",\"kind\":\"main\",\"start\":242,\"end\":245,\"summary\":\"读物内容影响苏雨晴当夜梦境，引发生理反应与醒后的羞赧；该段是青春期体验，非现实亲密关系。洗漱后她精神较好，主动提早去面馆帮忙，迅速打包收款。新来的学生食客注意到她并议论外貌，她则只专注完成工作。\",\"turn\":\"苏雨晴更加主动熟练地劳动；旁人对她投射恋慕。\"},\"c059\":{\"key\":\"c059\",\"title\":\"路见不平一声吼\",\"kind\":\"main\",\"start\":246,\"end\":249,\"summary\":\"老板夫妻为儿子生日决定提前关门，给苏雨晴备好食物。她在《浙江日报》发现高度吻合自己的寻子启事，既因父母仍在找她而开心，又怕被带回限制身份选择，便带走报纸。去网吧途中，她听见混混报复当初叫保安的少年，准备求援。\",\"turn\":\"父母寻找出现证据；救人少年遭到混混报复。\"},\"c060\":{\"key\":\"c060\",\"title\":\"该出手时就出手\",\"kind\":\"main\",\"start\":250,\"end\":253,\"summary\":\"胡玉牛闯入小巷制服五名持械混混，莫空又及时挡开险些砸中苏雨晴的人。受伤少年拒绝去医院自行离开，仍未留名。胡玉牛面对莫空表现羞涩并想顺路同行，苏雨晴提醒自己不能因外形歧视别人。莫空告辞，胡玉牛让混混自叫救护车，众人分别。\",\"turn\":\"少年获救，混混受伤；胡玉牛对莫空的好感开始显露。\"},\"c061\":{\"key\":\"c061\",\"title\":\"面馆老板的儿子\",\"kind\":\"main\",\"start\":255,\"end\":258,\"summary\":\"面馆夫妻为儿子过生日后晚开门，李叔叔趁清闲教苏雨晴煮面。两人的初三儿子李天明因学校活动提前放学到店，受到父母疼爱；他将苏雨晴认作漂亮女孩，主动搭讪并拉住她的手。苏雨晴担心误会，说明自己的出生性别，父母也予以证实，李天明随即变了态度。\",\"turn\":\"雇主家庭的新成员因性别信息产生排斥，破坏她在面馆的安全感。\"},\"c062\":{\"key\":\"c062\",\"title\":\"哭了\",\"kind\":\"main\",\"start\":259,\"end\":262,\"summary\":\"李天明得知苏雨晴的出生性别后出言羞辱，拒绝向她道歉，父母制止并教育他。苏雨晴受创跑出面馆，冲向河岸时产生轻生念头，却因绊倒而停在草地上痛哭。莫空见她流泪，留下陪伴并提供创可贴和纸巾；她没有说明真正的伤害来源，只借摔倒掩饰崩溃。\",\"turn\":\"莫空以陪伴暂时接住她的绝望；伤害未由施害者修复。\"},\"c063\":{\"key\":\"c063\",\"title\":\"烤螃蟹\",\"kind\":\"main\",\"start\":263,\"end\":266,\"summary\":\"莫空下水捉到两只螃蟹，在路边生火烤熟，与苏雨晴分食。食物和陪伴让她逐渐平静，也使她想起儿时被照顾的感觉。她羞怯询问他的住处，莫空只说以后有机会带她去，并提醒将下雨。她误以为遭到回避，决定当天不回面馆，以免再遇李天明。\",\"turn\":\"烤蟹成为关系中的温柔记忆；她仍害怕他人疏远。\"},\"c064\":{\"key\":\"c064\",\"title\":\"登门道歉\",\"kind\":\"main\",\"start\":267,\"end\":269,\"summary\":\"苏雨晴刚回租屋便遇到大雨，以临摹杯子练习绘画，幻想将来靠画画生活。张阿姨上门为儿子的侮辱道歉，带来牛奶、面包、巧克力等食物和《故事会》。苏雨晴从冷淡转为接受，愿意原谅张阿姨，却仍认为李天明本人应当认错。她整理食物，在雨夜独自阅读。\",\"turn\":\"雇主主动修复关系，但李天明的道歉仍然缺席。\"},\"c065\":{\"key\":\"c065\",\"title\":\"浑身的骨头都酸痛\",\"kind\":\"main\",\"start\":270,\"end\":273,\"summary\":\"苏雨晴梦见所有人排斥自己，又进入反复出现的公园。男孩以糖果压住内心痛苦，却承受身体疼痛；她把男孩理解为儿时的自己，把糖果联想到药物。男孩说自己杀害了各种欺凌他的人，使她害怕梦境映照被压抑的怨恨。醒来后她骨骼酸痛、乏力，现实中没有发生梦里的杀戮。\",\"turn\":\"她开始主动解释反复梦境，担忧伤害会侵蚀自己的温柔。\"},\"c066\":{\"key\":\"c066\",\"title\":\"就好像什么都没有发生\",\"kind\":\"main\",\"start\":274,\"end\":277,\"summary\":\"雨天早晨苏雨晴拖着不适的身体上班，面馆夫妻像往常一样招呼她吃早餐，让冲突后的关系恢复日常。空闲时她观看张阿姨绣“家”字，想起台湾外婆教过自己刺绣。张阿姨肯定男孩也能做这门手艺，教她绣十字并送了一套花猫图案的初学材料，给予实在的接纳。\",\"turn\":\"一门共同的手艺使她重新体验无需辩解的照顾。\"},\"c067\":{\"key\":\"c067\",\"title\":\"酒吧兼职（一）\",\"kind\":\"main\",\"start\":278,\"end\":281,\"summary\":\"周日收工时，李叔叔给苏雨晴和张阿姨煮云吞面；来访的张思凡吃炸酱面，并介绍一份从深夜到清晨的酒吧临时工作。薪资、奖金和分成吸引了想买手机的苏雨晴，她虽受父母说法影响而害怕酒吧，仍答应跟去。张思凡其实也未做过这份工作，两人骑车去面试。\",\"turn\":\"经济压力促使缺乏经验的两人进入陌生且有风险的工作环境。\"},\"c068\":{\"key\":\"c068\",\"title\":\"酒吧兼职（二）\",\"kind\":\"main\",\"start\":282,\"end\":285,\"summary\":\"酒吧的万董正在查顾总账目，顺便面试苏雨晴和张思凡。张思凡谎称两人都是大学生，万董看出年龄可疑仍让安排轻松工作。顾总带她们领制服，交由王主任管理。张思凡以男性装束被派去陪女客喝酒，苏雨晴穿女服务员制服送酒，两人分开进入不同房间。\",\"turn\":\"所谓轻松工作实际包含陪酒，管理层保护承诺未落实。\"},\"c069\":{\"key\":\"c069\",\"title\":\"酒吧兼职（三）\",\"kind\":\"main\",\"start\":286,\"end\":289,\"summary\":\"苏雨晴给二十七号包厢送酒，被三名男客要求陪饮；她不懂拒绝，又担心误工，被迫喝下啤酒。客人虽顾忌店内规矩，没有进一步强迫，她却在后续送酒中不断遭劝饮而晕眩。领班又让她给十四号贵宾送三杯鸡尾酒，使已经醉得不适的她接近更危险的处境。\",\"turn\":\"缺少拒绝与求助渠道，酒精令她逐步失去自我保护能力。\"},\"c070\":{\"key\":\"c070\",\"title\":\"酒吧兼职（四）\",\"kind\":\"main\",\"start\":290,\"end\":293,\"summary\":\"十四号贵宾区的赵老板以小费为诱饵让苏雨晴喝完鸡尾酒，她失去意识后遭到性侵害。另一边张思凡受到三名女客的强迫触碰和性别羞辱，挣脱后决定离职，经过时发现苏雨晴受害。她准备冲上前阻止，莫空出现，表示由自己进入救人。\",\"turn\":\"两人遭遇侵害，张思凡与莫空开始紧急救援。\"},\"c071\":{\"key\":\"c071\",\"title\":\"酒吧兼职（五）\",\"kind\":\"main\",\"start\":294,\"end\":297,\"summary\":\"莫空打退阻拦者和赵老板，抱走失去意识的苏雨晴，与张思凡从楼梯逃离。万董的儿子阿雷听说女服务员受欺负，命令保安停止追赶，万董也认可儿子的处理。莫空领两人穿过地下停车场和大润发仓库，又冒险取回电动车，准备送苏雨晴到张思凡住处休息。\",\"turn\":\"救援成功且追赶被叫停；阿雷父子的善意与酒吧失管并存。\"},\"c072\":{\"key\":\"c072\",\"title\":\"张思凡的心里话\",\"kind\":\"main\",\"start\":298,\"end\":301,\"summary\":\"莫空送两人回集装箱屋后独自步行等夜班公交，张思凡照顾醉酒的苏雨晴，因带她做危险兼职深感内疚，决定再不去酒吧。她向睡着的苏雨晴倾诉过去：曾想以富人的报酬换取手术费用，遭受严重虐待后逃离，却未拿到承诺的钱。今晚的羞辱重触旧创，两人相拥寻求安慰。\",\"turn\":\"张思凡的旧创与互助动机揭开；莫空默默承担救援善后。\"},\"c073\":{\"key\":\"c073\",\"title\":\"宿醉\",\"kind\":\"main\",\"start\":302,\"end\":304,\"summary\":\"雨冷的周一早晨，张思凡为了照顾苏雨晴也放弃上课，同时为自己的拖延与前途发愁。苏雨晴宿醉醒来，一度以为上班迟到，听张思凡讲述莫空救人的经过后才理清零碎记忆。两人逃跑时把原来的衣服留在酒吧，张思凡找出一套黄白猫咪布偶装给她御寒，并准备煮食。\",\"turn\":\"苏雨晴确认获救经过；两人靠共同生活缓和受害后的不安。\"},\"c074\":{\"key\":\"c074\",\"title\":\"钓鱼\",\"kind\":\"main\",\"start\":305,\"end\":308,\"summary\":\"两人吃水饺看新闻，谈论独居的孤单与城乡隐私差异。张思凡交还洗衣时发现的六百元小费，苏雨晴愿借给因买渔具超支的她，被婉拒；两人都决定不再去酒吧赚钱。张思凡带苏雨晴冒雨去河边试新鱼竿，合力支好大伞、组装渔具，笨拙但愉快地开始垂钓。\",\"turn\":\"金钱与陪伴互相支持；危险兼职告一段落，暂未遭追究。\"},\"c075\":{\"key\":\"c075\",\"title\":\"悠扬的箫声\",\"kind\":\"main\",\"start\":309,\"end\":312,\"summary\":\"苏雨晴发现渔具箱里有张思凡买后弃学的洞箫，说明家族要求学习中国古乐器，吹奏《平沙落雁》，令对方安静下来。两人钓到一条草鱼，随后改玩双人GBA游戏。傍晚准备烤鱼时，信佛的苏雨晴不忍亲见杀生，张思凡也不会杀鱼，最终将鱼放回水中。\",\"turn\":\"苏的艺术才能与怜悯显现；张思凡的陪伴需求通过双份游戏物品呈现。\"},\"c076\":{\"key\":\"c076\",\"title\":\"发工资\",\"kind\":\"main\",\"start\":313,\"end\":316,\"summary\":\"2004年4月29日，面馆午后清闲，苏雨晴认真擦净桌面后伏桌睡着。通宵写作的莫空来吃面，想起初见她的火车旅程，意识到自己珍惜她却没有占有欲，也想到将来离城的不舍。晚间夫妻提前发放三百元工资，李叔叔另给五十元让她改善饮食，肯定她的工作。\",\"turn\":\"劳动获得明确认可与资金；莫空的感情仍是珍惜和关照，未确立恋爱。\"},\"c077\":{\"key\":\"c077\",\"title\":\"逛夜市\",\"kind\":\"main\",\"start\":317,\"end\":320,\"summary\":\"发薪后苏雨晴逛夜市，测得身高一百五十厘米、体重四十四公斤。她用每天两元攒下的零花钱抽奖，得到黏性蜘蛛人、竹蜻蜓和夜光珠，又套中一盒国产EVA模型；蜘蛛人后来黏在雨棚上取不下来。她为毛绒玩具把剩余硬币投入娃娃机却一无所获，保留应急整钞回家。\",\"turn\":\"她在节制预算与儿童式愿望之间摇摆，经济独立没有抹去对玩具的喜爱。\"},\"c078\":{\"key\":\"c078\",\"title\":\"预感\",\"kind\":\"main\",\"start\":321,\"end\":324,\"summary\":\"苏雨晴拼好EVA模型后失眠，感到既期待又害怕的不安；与此同时父母乘夜车赶往小城市寻找她。她早晨醒来有短暂的记忆混乱，稍后恢复；曲奇和咖啡从窗外回来，使她振奋并决定提早上班。叙述称猫鼠已有近半月未见，与前章面馆午睡画面存在连续性冲突。\",\"turn\":\"父母即将抵达；苏的预感是叙事照应，不构成超自然能力证据。\"},\"c079\":{\"key\":\"c079\",\"title\":\"找寻\",\"kind\":\"main\",\"start\":325,\"end\":328,\"summary\":\"苏雨晴早到面馆，远远认出父母正向张阿姨打听自己。即使出示户口本，张阿姨仍拒绝泄露住处，要求等孩子本人确认。苏雨晴为父母憔悴而心疼，却害怕回家失去身份选择与自由，最终忍痛回屋收拾行李，留下让父母不要再找、当她不存在的纸条，准备再次逃离。\",\"turn\":\"她放弃已建立的生活以避免被带回家；家人关心与身份压迫继续纠缠。\"},\"c080\":{\"key\":\"c080\",\"title\":\"逃离\",\"kind\":\"main\",\"start\":329,\"end\":331,\"summary\":\"苏雨晴带八百五十三元、全部可携行李和猫鼠从后门离开，乘公交去笃头村。车经过面馆时她忍住呼喊父母的冲动，在睡梦里得到家人接纳和手术成功的幸福，醒后确认只是愿望。她没有手机也不敢借电话，只能拖着重物沿乡间岔路寻找张思凡，花了一上午才到达。\",\"turn\":\"第二次出走失去工作和租屋，但保留朋友、积蓄与动物陪伴。\"},\"c081\":{\"key\":\"c081\",\"title\":\"听风吹\",\"kind\":\"main\",\"start\":332,\"end\":335,\"summary\":\"张思凡正在给集装箱房围院子，看见苏雨晴带全部行李来投奔，欣然表示可以一直住下。苏雨晴洗澡后与她吃烤肉，终于说明父母已找来、自己选择躲避；张思凡理解却没有强迫她相认。叙述补充苏从小被禁止高声说话和表达愤怒，长期压抑也塑成如今胆怯温顺的习惯。\",\"turn\":\"朋友为第二次出走提供住处；被压抑的情绪背景得到补充。\"},\"c082\":{\"key\":\"c082\",\"title\":\"院子\",\"kind\":\"main\",\"start\":336,\"end\":339,\"summary\":\"两人搭完木栅栏，讨论以后加建厨房、前院种花和后院种菜。张思凡欢迎曲奇与咖啡加入，洗澡后一起用纸箱做连通的小窝。苏雨晴接受照看花菜换三餐的约定，以劳动消除寄住的亏欠感。夜里她们谈父母不知情或不接纳的困境，各自羡慕对方又都害怕坦白后的结果。\",\"turn\":\"共同生活正式开始；互助建立在彼此认可而非单方面施舍上。\"},\"c083\":{\"key\":\"c083\",\"title\":\"煮粥\",\"kind\":\"main\",\"start\":340,\"end\":343,\"summary\":\"搬来后的第一夜苏雨晴睡得安稳，翌日早起收拾张思凡忘盖药瓶而洒出的药片，又仔细打扫整个房间。曲奇与咖啡在院子追逐，并未真的反目。无班可上的她不愿白住，照着食谱尝试煮粥，随后在院里读书等张思凡起床，希望以家务回应收留之情。\",\"turn\":\"独立劳动习惯转化为共同生活中的照顾；煮粥结果尚待揭晓。\"},\"c084\":{\"key\":\"c084\",\"title\":\"黑暗料理\",\"kind\":\"main\",\"start\":344,\"end\":347,\"summary\":\"苏雨晴因看反电饭煲刻度把白粥煮糊，张思凡安慰后改在院里做早餐，却也把油条做成炸面团、煎蛋弄焦。两人索性试炸各种果蔬，闹出不少笑话；曲奇误尝油炸柠檬后避开，苏以吐司安抚并认真收拾卫生。她希望这样平静的生活能延续，远处有人忽然招呼她。\",\"turn\":\"生活技能不足没有破坏互助，家常失败反而带来放松与温暖。\"},\"c085\":{\"key\":\"c085\",\"title\":\"又见胡玉牛\",\"kind\":\"main\",\"start\":348,\"end\":351,\"summary\":\"胡玉牛因来森林采药再次遇见苏雨晴，礼貌获准进入院子后与张思凡相识，共享午餐。张思凡刻意谈论体格，发现胡并不喜欢自己的强壮，反而羡慕她们的身材；胡想让人叫“小玉”又改口“老牛”。两人换上长裤，由胡带路进入屋后的树林，苏开始学习植物药材不止是草。\",\"turn\":\"胡玉牛加入朋友圈，其外貌与内心愿望的冲突逐渐浮现。\"},\"c086\":{\"key\":\"c086\",\"title\":\"隐藏在表相之下的灵魂\",\"kind\":\"main\",\"start\":352,\"end\":355,\"summary\":\"采药途中苏雨晴被兔子吓到，胡玉牛以荧光标记领路，耐心介绍结香与家传药方。他说明家族过去是卖武艺兼售跌打药的民间艺人，并非拥有神奇能力的武学世家，自己已不再学武。返家后张思凡判断胡内心向往女性，提醒苏不要凭外表衡量内心；此时胡尚未亲自确认。\",\"turn\":\"苏开始放下对胡举止的成见；身份判断仍须后续本人证实。\"},\"c087\":{\"key\":\"c087\",\"title\":\"步行街\",\"kind\":\"main\",\"start\":356,\"end\":358,\"summary\":\"张思凡陪苏雨晴去文澜学院旁的步行街买手机。苏因预算有限，在几款便宜机型中选中可接收电视的“NCKIA”山寨直板机；张思凡向熟识的年轻店主讲价，将五百元报价谈到三百六十元，又为她争取到八十元电话卡。苏获得第一部用自己钱买的手机，联系朋友终于方便了。\",\"turn\":\"手机解决失联与接送难题，同时消耗约一半积蓄。\"},\"c088\":{\"key\":\"c088\",\"title\":\"张思凡的大学\",\"kind\":\"main\",\"start\":359,\"end\":362,\"summary\":\"买完手机后，张思凡又冲动花五百元买水冰月手办。两人在步行街看见一位穿文澜初中校服、极为美丽的少女，羡慕之余更显外貌焦虑。为省饭钱，张思凡带苏去自己就读的蓝阳大学文学社茶话会；学校环境破旧，社团却提供书籍与食物，苏拘谨地开始参与。\",\"turn\":\"苏接触同龄人与大学生活；美貌少女此时尚未揭名。\"},\"c089\":{\"key\":\"c089\",\"title\":\"吟诗作对\",\"kind\":\"main\",\"start\":363,\"end\":366,\"summary\":\"文学社茶话会把古诗乱接成押韵笑话，连一向克制的苏雨晴也开怀大笑，重新向往中断的学业。张思凡指出一名清秀男生是校内唯一知晓其身份的好友，称对方有性别探索和偏爱跨性别者的倾向，又让苏别向孙昊告密。社员把苏当她妹妹，活动结束两人留下整理场地。\",\"turn\":\"苏体验群体欢乐但为辍学遗憾；张思凡亲密好友的名字尚未给出。\"},\"c090\":{\"key\":\"c090\",\"title\":\"园丁\",\"kind\":\"main\",\"start\":367,\"end\":370,\"summary\":\"苏雨晴照资料辛苦除草翻土，种下番薯和月季；张思凡铺鹅卵石小道，共同完善院子。劳累睡去的苏再次梦见荒废公园，梦中男孩为拒绝令人厌恶的世界而伤害自己的眼睛，使她恐惧并怀疑自己。曲奇叫醒她后，她发现张思凡因身体功能变化而发呆，开始询问对方心事。\",\"turn\":\"平静劳动与恐惧梦境并存；张思凡对身体变化的复杂情绪显露。\"},\"c091\":{\"key\":\"c091\",\"title\":\"孙昊再一次前来\",\"kind\":\"main\",\"start\":371,\"end\":374,\"summary\":\"张思凡因身体变化而担忧自己未来的性别处境，称并非简单后悔，却仍感迷茫；苏雨晴一度害怕失去“同类”，也承认难以完全理解她。孙昊打电话说要再来，张思凡欣喜约好翌日接站。苏以不打扰情侣为由留家研究刺绣，心里仍对孙昊缺乏信任。\",\"turn\":\"孙昊的到来将改变两人独居节奏；朋友间也存在无法完全共感的差异。\"},\"c092\":{\"key\":\"c092\",\"title\":\"十字绣\",\"kind\":\"main\",\"start\":375,\"end\":377,\"summary\":\"张思凡早起化妆接孙昊，准备关东煮并留早餐纸条。苏醒来再有短暂混乱，想起梦见张思凡术后后悔，但清楚那只是自己担忧的投射。她打扫浇水，不愿擅动朋友电脑，下午完成熊猫十字绣，这是第一件成品；张阿姨赠的花猫作品则因匆忙搬家留在旧屋、去向不明。\",\"turn\":\"她以家务与手艺适应独处；梦中后悔不得当作张思凡真实手术结局。\"},\"c093\":{\"key\":\"c093\",\"title\":\"小河边的莫空\",\"kind\":\"main\",\"start\":378,\"end\":381,\"summary\":\"下午三点张思凡发短信说夜里不归，苏雨晴虽然担忧孙昊是否真心，仍只能祝愿朋友幸福。她带猫鼠去乡间河边，偶遇徒步远行至此的莫空；曲奇显得与他熟悉。莫空给她原想用来戒烟的巧克力棒棒糖，边垂钓边解释过去常靠鱼充饥，准备只留够吃的鱼，其余放生。\",\"turn\":\"搬家后苏与莫空重新相遇，他的清贫与生存技能更具体。\"},\"c094\":{\"key\":\"c094\",\"title\":\"张思凡和孙昊的不可描述\",\"kind\":\"main\",\"start\":382,\"end\":385,\"summary\":\"张思凡与孙昊牵手逛市中心，买龙凤糖人、叫花鸡和绿豆汤，观看夜市卖艺。她珍惜被当作女友的体验，刻意显得淑女，又因对方的体贴而放松。两人经过共同意愿的试探，进入小旅馆准备亲密相处；孙昊说自己没有过类似经历，张思凡因此更相信这段恋情。\",\"turn\":\"恋情进入更亲密阶段；张思凡对恋人真心的信任增加。\"},\"c095\":{\"key\":\"c095\",\"title\":\"小说和历史的区别\",\"kind\":\"main\",\"start\":386,\"end\":388,\"summary\":\"苏雨晴拿来调味料，与莫空在河岸烤鲈鱼和草鱼，也分给曲奇与咖啡。她欣赏莫空冷静细致的气质，害羞地找话题。莫空借《三国演义》说明现实并不保证努力得到圆满：英雄也会败亡、梦想也会未竟。苏把这番话联想到自己的愿望，因害怕未来无法实现而悄悄流泪。\",\"turn\":\"共同晚餐加深苏的好感，现实与故事的讨论却触动其命运焦虑。\"},\"c096\":{\"key\":\"c096\",\"title\":\"胡玉牛来访\",\"kind\":\"main\",\"start\":389,\"end\":392,\"summary\":\"莫空离去、张思凡未归，苏独自看电视，思索命运与自由。她梦见一名作家在电脑上写出自己当下的动作，呈现故事内外互照，醒后仅留不安。次晨她吃小葱拌豆腐，准备日常事务时胡玉牛来访；开门受惊掉落的补佳乐药盒被胡盯住，她担心身份曝光后遭排斥。\",\"turn\":\"药盒意外使苏与胡进入身份坦白的关键时刻；元叙事仍属梦境。\"},\"c097\":{\"key\":\"c097\",\"title\":\"被发现的秘密\",\"kind\":\"main\",\"start\":393,\"end\":395,\"summary\":\"胡玉牛认出补佳乐并说出“药娘”，苏雨晴才发现他也接触过被称为“新世界之门”的台湾论坛。胡因终于遇到同类而激动，询问自身改变的可能；苏说明不能只凭药物得到理想外貌，也倾诉自己十五岁出走的代价。胡随即讲出家族只剩自己一个男丁、被父祖期待继承武艺的压力。\",\"turn\":\"秘密曝光促成同类相认；外貌与家族继承构成胡的双重困境。\"},\"c098\":{\"key\":\"c098\",\"title\":\"胡玉牛的诉说\",\"kind\":\"main\",\"start\":396,\"end\":399,\"summary\":\"胡玉牛坦白自己不愿做家主或男子汉，只想作为普通女人生活。苏因担心他受更多伤害而劝阻，胡激烈反问自己为何没有选择权，冷静道歉后仍坚持离去。另一线张思凡与孙昊亲密过夜后送其返程，归家发现苏为胡的未来痛哭，便以选择并无错误安慰她，也安慰自己。\",\"turn\":\"胡自主选择的意愿明确；苏意识到关心也可能变成替别人作决定。\"},\"c099\":{\"key\":\"c099\",\"title\":\"平淡的田园生活\",\"kind\":\"main\",\"start\":400,\"end\":403,\"summary\":\"胡玉牛离开后苏雨晴郁闷两日才缓过来，照料菜苗时想念旧租屋、父母和面馆夫妻，却不知道他们的现状。张思凡与孙昊联系更密，女装也更频繁。苏清楚积蓄终会耗尽，计划找工作；张家生活费也将缩减，两人考虑搬回城里。熟稔后的苏更敢开玩笑，并肯定张作为女性的身份。\",\"turn\":\"田园停留终需经济出路；前雇主与父母在本段的后续仍未交代。\"},\"c100\":{\"key\":\"c100\",\"title\":\"安静的田园生活\",\"kind\":\"main\",\"start\":404,\"end\":407,\"summary\":\"五月的一场暴雨把两人和猫鼠赶回屋里。她们登录论坛，苏厌恶争吵，张思凡却耐心回复新人的求助；她因热心获得“药娘导师”头衔，却自嘲不知自己前路。好友“优子”留言已决定来小城市生活，电话中说向父母借口外出工作。张思凡欢迎她入住，并提议三人共同进城求职合租。\",\"turn\":\"论坛互助延伸为现实同住，新成员即将加入。\"},\"c101\":{\"key\":\"c101\",\"title\":\"方莜莜（上）\",\"kind\":\"main\",\"start\":408,\"end\":411,\"summary\":\"雨后张思凡唱武侠歌曲，苏与她玩双人小游戏；翌晨两人骑带备用电瓶的电动车去火车站接“优子”。苏重返初到小城的地点，对父母是否已放弃寻找作出未经证实的猜想。来客自报方莜莜，身高约一米六、气质温婉，与月橙张思凡相熟，首次见到“清泉”苏雨晴也感惊讶。\",\"turn\":\"方莜莜正式登场；线上三人首次在现实相聚。\"},\"c102\":{\"key\":\"c102\",\"title\":\"方莜莜（下）\",\"kind\":\"main\",\"start\":412,\"end\":415,\"summary\":\"三人挤坐电动车返程，方莜莜先征求同意才抱住苏雨晴维持平衡，不追问她的家庭伤口，令苏感到尊重。方说明熟人众多的原城市让她疲惫，才选择异地生活。车辆连备用电瓶也耗尽，她们从笃头村总站步行，在炎热和口渴中抵达集装箱房，终于喝上冷饮休息。\",\"turn\":\"方的温和与边界感让苏迅速获得好感；三人生活开始。\"},\"c103\":{\"key\":\"c103\",\"title\":\"两个人都喝醉了\",\"kind\":\"main\",\"start\":416,\"end\":418,\"summary\":\"张思凡以烧烤招待方莜莜，两人热聊，苏因频繁走神误以为自己受到冷落，同时害怕安稳生活突然消失。她观察方温婉的举止，又想起胡玉牛的困境。张、方喝黄酒后醉倒，未饮酒的苏独自清理桌面，再费力把两人扶回房间；方中途醒来尽力自己走，三人终于休息。\",\"turn\":\"新关系引发苏对被忽略的焦虑，但她仍主动承担照顾。\"},\"c104\":{\"key\":\"c104\",\"title\":\"三人同眠\",\"kind\":\"main\",\"start\":419,\"end\":421,\"summary\":\"三人同床休息，方莜莜严重失眠，直到凌晨才睡着。平行叙事中，莫空登上小城最高写字楼，冒风雨俯瞰城市，思索观察者也终究是故事中人。苏梦见社会与家人完全接纳自己，手术、婚姻及领养孩子皆圆满实现，清醒后怅然；这些幸福明确是梦境，没有发生于现实线。\",\"turn\":\"作者旁观视角与苏的理想生活互照，现实前景依然未定。\"},\"c105\":{\"key\":\"c105\",\"title\":\"连绵的阴雨天\",\"kind\":\"main\",\"start\":422,\"end\":425,\"summary\":\"连绵阴雨里，张思凡与带着上网本的方莜莜玩《传奇》，苏雨晴感到像局外人，借GBA玩农场游戏却因电池耗尽丢失两小时进度。方察觉她的无聊，主动让出电脑并去做饭，表示既然同住就是一家人。集装箱二层厨房此时已请人装好，雨天烹饪不再受露天火盆限制。\",\"turn\":\"方主动纳入苏，缓解三人相处的不平衡，并开始承担厨房事务。\"},\"c106\":{\"key\":\"c106\",\"title\":\"方莜莜的厨艺\",\"kind\":\"main\",\"start\":426,\"end\":429,\"summary\":\"苏试玩《传奇》后仍不感兴趣，转去厨房请求方莜莜教做菜。方鼓励她练切黄瓜，容许笨拙并耐心示范，两人完成凉拌黄瓜、丝瓜汤等午餐。方的清淡口味让苏多吃了饭，却让偏好辛辣的张思凡不习惯。方愿以后负责烹饪，并透露自己比张大一岁、自行用药约三年。\",\"turn\":\"方的照料与苏的学习建立稳定协作；年龄可推为方21、张20。\"},\"c107\":{\"key\":\"c107\",\"title\":\"找工作\",\"kind\":\"main\",\"start\":430,\"end\":432,\"summary\":\"三人赴城里中介找工作，商务英语毕业的方莜莜及在读大学生张思凡选择较多；十五岁、未读完初中且身份证遗失的苏屡受限制。快餐岗位已满、酒店迎宾因身高和幼态被拒，她仍不愿由朋友供养，最终获大润发理货员职位，月薪一千五百，要求三天内报到。\",\"turn\":\"苏重新获得工作，收入高于面馆；所承诺社保随后因无身份证被改为补贴。\"},\"c108\":{\"key\":\"c108\",\"title\":\"租房子\",\"kind\":\"main\",\"start\":433,\"end\":435,\"summary\":\"张思凡获月薪两千的账本录入校对兼职，方莜莜凭资格证入小商品市场做网络维修部门组长；苏填女性资料入职，但因无身份证未办理五险一金。三人找房时遇到刚做大润发装卸工的胡玉牛，决定一起整租六间房。总租金一千五，张与方各付五百，苏与胡各付二百五十，组成四人互助家庭。\",\"turn\":\"四人合租定案；胡已找到月薪1600装卸工作，与苏成同事。\"},\"c109\":{\"key\":\"c109\",\"title\":\"安眠药\",\"kind\":\"main\",\"start\":436,\"end\":439,\"summary\":\"四人正式互相介绍、分配六把钥匙，约好翌日搬家。胡玉牛确认坚持性别转变，张思凡给予支持，也承认任何人的未来都无法保证圆满。回程三人因各自道路而低落，苏重想莫空的鱼鹰故事。夜里苏先睡着，受失眠折磨的张和方自行服用安眠药后才入睡，反映共同生活背后的身体压力。\",\"turn\":\"胡的选择被接纳，但三人都无法消除各自对前途的恐惧。\"},\"c110\":{\"key\":\"c110\",\"title\":\"搬家\",\"kind\":\"main\",\"start\":440,\"end\":443,\"summary\":\"三人收拾行李，带曲奇和咖啡告别田园小屋，步行、公交再转出租前往白兔街白兔小区。她们租住七层无电梯楼房的顶层，张思凡因物品太多而力竭，先到的胡玉牛帮忙搬上楼。六间房四人自选，方、张、苏依次住同侧相邻房间，苏选中最里面有两扇窗的一间。\",\"turn\":\"四人城市合住正式开始；郊区小屋仍在租期内，可日后回访。\"},\"c111\":{\"key\":\"c111\",\"title\":\"布置自己的新家\",\"kind\":\"main\",\"start\":444,\"end\":447,\"summary\":\"四人合力擦去房屋灰尘，苏布置独立卧室，把日记和钱分处收好、药盒放进抽屉，并摆上张思凡送的水冰月手办。屋内仅客厅有空调，众人商量买凉席或被褥等用品。午后方撑伞护住三人，胡独走在阳光下；她们到大润发采购，发现还需添置许多生活工具，预算有些吃紧。\",\"turn\":\"苏重新拥有私人房间，也融入可互助的共同客厅与厨房。\"},\"c112\":{\"key\":\"c112\",\"title\":\"梦见一场大雨\",\"kind\":\"main\",\"start\":448,\"end\":451,\"summary\":\"苏领取两件红色大润发夏季工作服，采购后在方莜莜指导下做晚餐，却不慎划伤手指。张思凡以女装出席晚饭，胡玉牛羡慕其声音与装扮；大家愿教他练声化妆，并正式采用他接受的昵称“小玉”。夜里众人为首日上班早睡，苏梦见独困暴雨、无力前行，现实并未发生梦中死亡。\",\"turn\":\"小玉得到名字上的认可；新工作的期待与无助梦境并行。\"},\"c113\":{\"key\":\"c113\",\"title\":\"大清早\",\"kind\":\"main\",\"start\":452,\"end\":454,\"summary\":\"苏雨晴五点起床，为大润发第一天工作准备。她穿方莜莜买的朴素女式衬衫，首次使用旧同桌赠的七格星期发卡，回忆那份生日礼物曾使她感到同龄人的关心。胡玉牛耐心等她一起出门，两人买包子边走边吃；谈及身材时苏又意识到自己的话可能触动胡，及时道歉。\",\"turn\":\"苏更主动以女性形象工作；旧同桌礼物连接被珍惜的过往。\"},\"c114\":{\"key\":\"c114\",\"title\":\"初次在超市上班\",\"kind\":\"main\",\"start\":455,\"end\":458,\"summary\":\"苏与胡从大润发员工通道进入，苏避开拥挤女更衣室，在卫生间换制服，再与胡打卡。胡去二楼后仓，苏找到主管张燕，被转交给员工指导姚玲，再由“百事”长期促销员带学分货与补货。她接触庞大的六层商场布局，面对流程与新同事既好奇又紧张。\",\"turn\":\"新的劳动关系建立；她被视作女孩，但仍害怕被注目。\"},\"c115\":{\"key\":\"c115\",\"title\":\"第一天的工作\",\"kind\":\"main\",\"start\":459,\"end\":462,\"summary\":\"百事促销员耐心教苏核对条码、规格和货架位置，苏为隐藏未成年而称自己十八岁。忙至九点后，她受命寻找需要帮助的同事，却因羞怯漫无目的；一名矮个男员工的薯片箱砸到她，她只觉其道歉带着戏弄。最后她主动去帮白发老伯搬米，寻找能安心投入的工作。\",\"turn\":\"苏学习能力不差，体力与沟通却吃力；结识友善长辈的契机出现。\"},\"c116\":{\"key\":\"c116\",\"title\":\"矮个子一米六\",\"kind\":\"main\",\"start\":463,\"end\":466,\"summary\":\"苏坚持帮老伯搬完十袋米，累得气喘，老伯温和劝她慢慢做并承担重活。他自我介绍夏仕尼，耐心回答顾客与苏的问题，午间教她用员工卡买优惠盒饭。付款时又遇到早先的矮个男员工，其调侃让苏恼火，却也提醒她带上通行所需小票。夏老伯随后邀她同桌吃饭。\",\"turn\":\"夏仕尼成为工作中的可靠引导者；矮个员工的戏谑关系尚未明朗。\"},\"c117\":{\"key\":\"c117\",\"title\":\"瓢盆大雨\",\"kind\":\"main\",\"start\":467,\"end\":470,\"summary\":\"胡玉牛为省钱吃泡面，苏告诉他员工餐优惠，并小心分享未碰过的鸡块。夏仕尼误会二人恋爱，苏澄清只是合租伙伴。老伯说自己曾为老板开车，因公司破产来超市工作，再两年退休。下午苏慢慢更换价签，胡为加班费继续搬货，她下班时发现外面已下大雨。\",\"turn\":\"同住者分享食物与信息；苏独自返家，将遇暴雨考验。\"},\"c118\":{\"key\":\"c118\",\"title\":\"挡住风的他和遮住雨的伞\",\"kind\":\"main\",\"start\":471,\"end\":473,\"summary\":\"没带伞的苏雨晴下班后冒雨回家，在红灯路口被狂风暴雨逼得蹲下。莫空忽然站在她前方挡风，把黑色雨伞递给她，只嘱路上小心便离去。苏握着带余温的伞平安回家，期待下次相遇时归还，也更强烈地意识到自己的心动；伞到本段结束仍在她手中。\",\"turn\":\"莫空的照顾转化为苏明确的期待与好感，赠伞留下再次相见的理由。\"},\"c119\":{\"key\":\"c119\",\"title\":\"雨鞋\",\"kind\":\"main\",\"start\":474,\"end\":477,\"summary\":\"唯一的球鞋湿透后，苏担心次日没鞋穿，先给同样淋雨回家的胡递毛巾，再打电话请张思凡代买。她趁等待练习已学会的煮饭。张回来提醒她本可在超市买伞，并带来三十六码短雨鞋，十元不必偿还，只开玩笑要她帮打扫房间；苏将莫空的伞留身边等归还。\",\"turn\":\"互助落实在生活急需上；苏开始掌握能独立完成的厨房技能。\"},\"c120\":{\"key\":\"c120\",\"title\":\"扫码的工作\",\"kind\":\"main\",\"start\":478,\"end\":481,\"summary\":\"临近六月，梅雨连绵。方莜莜下班后指导苏雨晴完成番茄蛋花汤，张思凡称赞，使苏获得做饭的成就感；胡仍为身体与脚码难改变而失落。翌日超市没有货柜，胡与后仓同事逐渐熟悉，张燕则教苏用便携终端扫描核价、打印新标签。细致且可独自完成的工作令苏暂觉自在。\",\"turn\":\"四人工作与生活初步稳定，苏的技能、自信缓慢增长。\"},\"c121\":{\"key\":\"c121\",\"title\":\"冉空城\",\"kind\":\"main\",\"start\":482,\"end\":485,\"summary\":\"苏雨晴在超市核价时回忆初中同桌冉空城：他曾主动交换手机号码，她因自卑与朦胧感情而推托。语文课替他提示答案后，两人遭同学羞辱，雨晴怕失去唯一的朋友。冉空城却当面斥责欺凌者，明确维护她，使这段校园记忆成为离家后仍珍惜的温暖。\",\"turn\":\"同桌主动维护她；当年没有交换号码留下遗憾。\"},\"c122\":{\"key\":\"c122\",\"title\":\"羡慕？嫉妒？\",\"kind\":\"main\",\"start\":486,\"end\":489,\"summary\":\"夏老伯体谅雨晴，让她慢慢完成核价。她为更换高处标签跳跃时撞倒一名普通少年，又为来寻人的漂亮女孩指路；女孩的外貌、声音与举止激起她强烈的羡慕和身体自卑。两名客人的关系并未证实，她关于两人会错过的直觉也只是自己的想象。\",\"turn\":\"陌生女孩强化了雨晴对自身女性形象的渴望。\"},\"c123\":{\"key\":\"c123\",\"title\":\"胡玉牛的面点手艺\",\"kind\":\"main\",\"start\":490,\"end\":493,\"summary\":\"下班路上，胡玉牛坦言羡慕能自然拥有女性身份和恋爱生活的女孩。回家后，他熟练制作饺子、烧麦与酸辣汤，细致厨艺得到雨晴及室友们赞赏；他仍羡慕雨晴柔嫩的手。雨晴随后出现身体不适，准备向朋友询问，温暖合住生活与身体焦虑并行。\",\"turn\":\"阿牛用厨艺融入家庭，雨晴的用药不适引出调整。\"},\"c124\":{\"key\":\"c124\",\"title\":\"拨通了的号码\",\"kind\":\"main\",\"start\":494,\"end\":497,\"summary\":\"晚餐后张思凡将未拆封的色谱龙赠给身体不适、经济拮据的雨晴，室友们又围绕洗碗打趣。独处时雨晴从冉空城所赠发卡袋里发现久藏的电话号码，拨通后听见他的声音却哭着挂断。冉空城疑似认出她而失神；回忆揭示他曾用数学小游戏探出生日并送她发卡。\",\"turn\":\"隐藏号码恢复联系的可能，但雨晴尚未敢表明身份。\"},\"c125\":{\"key\":\"c125\",\"title\":\"一夜未眠\",\"kind\":\"main\",\"start\":498,\"end\":501,\"summary\":\"雨晴因通话而整夜追忆初中，猫曲奇与咖啡陪在床边。她曾因沉浸身份探索而成绩下滑，被父母安排重读初二；冉空城也来到原班陪伴，她猜他为自己留级，双方没有说破。天将亮才睡着的雨晴险些误工，胡玉牛进房将她叫醒并扶住险些跌倒的她。\",\"turn\":\"冉空城的陪伴分量加深；缺觉开始影响现实工作。\"},\"c126\":{\"key\":\"c126\",\"title\":\"浑浑噩噩的感觉\",\"kind\":\"main\",\"start\":502,\"end\":505,\"summary\":\"睡眠不足的雨晴由胡玉牛一路扶到超市，又在女更衣室旧沙发上睡着。她勉强上岗时抽动货箱，险遭上层重物砸伤，幸被夏老伯及时挡住。夏老伯替她承担重活、安排休息，还在主管张燕询问时维护她，使陌生职场出现近似长辈照护的支持。\",\"turn\":\"疲惫暴露工作危险，夏老伯成为可信赖的保护者。\"},\"c127\":{\"key\":\"c127\",\"title\":\"超薄弹力贴身\",\"kind\":\"main\",\"start\":506,\"end\":509,\"summary\":\"夏老伯继续帮缺觉的雨晴挡下险落的货物，并让她午间补眠、替她应付主管。雨晴醒来后饥饿，得知新排班已发布，便买促销泡面；为避开拥挤收银处寻找三楼化妆品柜台，却走进女性用品区。她对领导的害怕又引出昔日误以为受罚、实为作文获奖的回忆。\",\"turn\":\"有人替她承担工作压力；意外进入用品区触发身份体验。\"},\"c128\":{\"key\":\"c128\",\"title\":\"七度空间少女系列\",\"kind\":\"main\",\"start\":510,\"end\":513,\"summary\":\"雨晴在忐忑中买下七度空间卫生用品，收银员将她当作羞怯少女，平常地完成结账；离开时按制度接受小票检查。她与阿牛下班回到室友身边，吃过简便晚餐，夜里独自尝试新购物品，从中获得被女性生活接纳的象征性安慰与安全感。\",\"turn\":\"一次普通而顺利的购买，让雨晴短暂体验到女性日常的归属与接纳。\"},\"c129\":{\"key\":\"c129\",\"title\":\"工作的日常（上）\",\"kind\":\"main\",\"start\":514,\"end\":517,\"summary\":\"雨晴醒来发现身体不适并非梦中转变，对镜观察自身变化后仍被外貌比较困扰。周日上班她得知周一休息、随后轮到晚班；夏老伯休假令她失去依靠。员工指导姚玲主动带她处理退货单据，肯定她娟秀字迹，也教她按照实际工作需要写大字。\",\"turn\":\"雨晴开始从长辈照顾转向学习独立承担文书工作。\"},\"c130\":{\"key\":\"c130\",\"title\":\"工作的日常（中）\",\"kind\":\"main\",\"start\":518,\"end\":521,\"summary\":\"周一张思凡在实习公司被要求制作新产品方案PPT，先无意贬低经理旧稿，后凭设计能力交出精美成果。她与王经理因《传奇》游戏找到共同话题，并帮他把稀有游戏道具和装备带回安全区。工作才能与活泼交际令上下级关系迅速亲近，也展现她在职场隐藏身份的另一面。\",\"turn\":\"思思的办公能力与游戏合作同时赢得上司认可，隐秘身份仍藏在工作表象下。\"},\"c131\":{\"key\":\"c131\",\"title\":\"工作的日常（下）\",\"kind\":\"main\",\"start\":522,\"end\":524,\"summary\":\"方莜莜对外使用本名方宇悠，在新公司任网络工程部主管，承担修电脑、建设网站和培训新人。朱志杰入职后认真学习；莜莜因眩晕险跌时被他扶住，他因察觉身体特征误猜主管是女扮男装。莜莜担心身份暴露却仍温和指导、请他吃午饭，显出独立逞强与平易近人的两面。\",\"turn\":\"新下属关系建立，身体虚弱和身份保密留下隐患。\"},\"c132\":{\"key\":\"c132\",\"title\":\"荡秋千的猫\",\"kind\":\"main\",\"start\":525,\"end\":528,\"summary\":\"休息日雨晴在小区公园思考离家追求自我的代价，曲奇带咖啡自在荡秋千。幼童小天跌倒，奶奶以男子汉不能哭安慰，引起她对童年性别规训的回想；小天随后带竹篓清理石头防止旁人跌倒，又逐渐沉迷收集美石，直至竹篓装满，给她新的生活隐喻。\",\"turn\":\"童年规训与取舍问题从观察普通家庭中重新浮现。\"},\"c133\":{\"key\":\"c133\",\"title\":\"生活中的哲学\",\"kind\":\"main\",\"start\":529,\"end\":531,\"summary\":\"小天为装新石头、提动竹篓不断舍弃旧石，雨晴由此联想自己为梦想失去亲情、朋友与尊严的代价，仍决定向前。秋千又唤起台湾外婆家花园和三位表哥的温暖记忆；他们包容她哭泣与想成为女孩的童言，尤其大表哥曾温柔答应儿时婚约，但多年未见后的态度仍未知。\",\"turn\":\"外婆家的自由回忆与石头取舍相互映照，雨晴开始衡量追梦所放下的亲情。\"},\"c134\":{\"key\":\"c134\",\"title\":\"胡玉牛的烦恼\",\"kind\":\"main\",\"start\":532,\"end\":535,\"summary\":\"雨晴从公园回家，看到阿牛为体毛与强壮外形苦恼，有限的解决办法也因费用和身体反应受阻。叙述转入阿牛成长史：父亲自幼训练他、寄望其振兴武学家族，而他被重担压迫，渐渐把成为女性与摆脱责任联系起来。自责、逃避和已深植的身份愿望交织，并未得到化解。\",\"turn\":\"阿牛把曾被父亲赞赏的体魄视为身份阻碍，身体改变与家族期待发生冲突。\"},\"c135\":{\"key\":\"c135\",\"title\":\"莫空的日常（一）\",\"kind\":\"main\",\"start\":536,\"end\":539,\"summary\":\"时间来到2004年六月，莫空独居廉价天台阁楼，靠写网络故事挣少量稿费，搬城时会拆装台式电脑。他闭门通宵写作，思索李慕翔这一名字，收入将尽又需考虑打工；午后买炒面回家睡觉，却因停电、旧空调停转而热醒，散漫自由与现实贫困同时显现。\",\"turn\":\"六月莫空的清贫写作生活展开，停电即将把他带向新的出行与相遇。\"},\"c136\":{\"key\":\"c136\",\"title\":\"莫空的日常（二）\",\"kind\":\"main\",\"start\":540,\"end\":543,\"summary\":\"莫空向年轻房东王果确认片区停电，决定去郊外海边散心。他乘公交、穿树林抵达未经开发的海滩，游水后烤贝类饮酒，享受宁静，也注意到远处别墅亮灯。自由景色令他反思家族社会束缚，并想到屡次偶遇的忧郁女孩雨晴，对她的处境生出关切。\",\"turn\":\"莫空接近海边别墅，雨晴在他心中的分量浮现。\"},\"c137\":{\"key\":\"c137\",\"title\":\"莫空的日常（三）\",\"kind\":\"main\",\"start\":544,\"end\":547,\"summary\":\"深夜莫空走近别墅，遭保镖礼貌驱离，并看到天台上美丽少女似乎对他出现感到意外；双方没有交谈。问得水泥路后，他出林才发现公交已停，只能步行回城。途中遇上夜游的黑猫曲奇与紫色鼠咖啡，原来他比雨晴更早认识曲奇；人和动物相伴走到岔路再告别。\",\"turn\":\"别墅少女身份未明；曲奇把独立人物线悄然相连。\"},\"c138\":{\"key\":\"c138\",\"title\":\"莫空的日常（四）\",\"kind\":\"main\",\"start\":548,\"end\":551,\"summary\":\"莫空步行至天亮，偶见与阿牛上班的雨晴，误把阿牛当作其男友而选择不打扰。回家昏睡后梦见昔日继任莫家家主：父亲因癌症去世，族人在就任仪式上各怀心思，以琐碎事务刁难。摸到祖传紫檀椅里的蛀洞，他决意放弃家主之位，梦境揭示其远行缘起。\",\"turn\":\"阿牛被误认男友；莫空主动辞去家主是自由生活根源。\"},\"c139\":{\"key\":\"c139\",\"title\":\"莫空的日常（五）\",\"kind\":\"main\",\"start\":552,\"end\":555,\"summary\":\"梦中莫空放弃权位后游历各地，以写故事和打零工维生；醒来发现已睡过一天一夜。他前往旧面馆期待再见雨晴，却从老板夫妇处得知她离家、父母曾来寻人及其出生时被认定的性别。面对老板娘责怪，莫空坚持每个人都有苦衷，理解多于评判。\",\"turn\":\"莫空得知雨晴身份与家庭处境，并未因此否定她。\"},\"c140\":{\"key\":\"c140\",\"title\":\"同性恋的传言\",\"kind\":\"main\",\"start\":556,\"end\":559,\"summary\":\"孙昊频繁打电话询问思思动态，既显亲密也暴露占有欲，并计划暑假探访。办公室听见男性声音后流传同性恋猜测，影响思思融入同事。她临时虚构来电者是哥哥、自己因算命而从小按女孩养大的说法，暂时化解排斥，却仍承受议论和被劝找女友的压力。\",\"turn\":\"职场暂时接纳以隐瞒真实关系为代价；恋人控制感初显。\"},\"c141\":{\"key\":\"c141\",\"title\":\"哆啦 A 梦的百宝袋\",\"kind\":\"main\",\"start\":560,\"end\":562,\"summary\":\"室友晚间分享变身题材小说《夜明珠》，又看《哆啦A梦》讨论想要的道具。思思喜时光旅行、童话入口，雨晴向往任意门与成真能力，莜莜从缩小电筒想到生活与资源问题。阿牛看似熟睡，三人费力将他搬回床上后，他梦话仍请求让谎言成真的道具，显露深藏愿望。\",\"turn\":\"共同幻想将群像愿望并列，阿牛的沉默并非无欲。\"},\"c142\":{\"key\":\"c142\",\"title\":\"收银员的学习\",\"kind\":\"main\",\"start\":563,\"end\":565,\"summary\":\"连续搬货让雨晴渐渐熟悉超市，能主动找事做。午餐时她鼓励阿牛以日常举止靠近理想形象，两人计划端午同游乐园，也被同事误看作情侣。张燕安排雨晴学习收银，夏老伯解释跨岗补位的需要；她随后向前台主管学习辨钞，工作技能由理货扩展到收银。\",\"turn\":\"雨晴工作自主性增强，节日集体出游有了计划。\"},\"c143\":{\"key\":\"c143\",\"title\":\"小城市的游乐园\",\"kind\":\"main\",\"start\":566,\"end\":568,\"summary\":\"端午四位室友都获连休，赶早乘车去邻镇游乐园。雨晴、思思、莜莜穿女装出行，阿牛因外形只穿休闲装，感到失落；莜莜制止思思越界玩笑，并给雨晴安全衣物。排队至十点后入园，雨晴想起童年被学习占满、只能在少年宫喂鸽子的生活，期待补回游玩的快乐。\",\"turn\":\"四人共同度假，衣着自由与外貌落差仍并存。\"},\"c144\":{\"key\":\"c144\",\"title\":\"真·旋转木马\",\"kind\":\"main\",\"start\":569,\"end\":572,\"summary\":\"四人体验旋转木马：雨晴选独角兽、思思抢白马、莜莜坐枣红马，阿牛因体型被安排水牛座位。思思未细看说明，恰好选中会高速自转的特殊白马，结束后眩晕呕吐，伙伴扶她休息、买水照顾。嬉闹与分享阿牛寿司等自带食物，使短暂惊险回到亲密轻松的节日氛围。\",\"turn\":\"思思莽撞造成不适，朋友互相照顾支撑欢乐。\"},\"c145\":{\"key\":\"c145\",\"title\":\"萝莉体型\",\"kind\":\"main\",\"start\":573,\"end\":575,\"summary\":\"摩天轮令雨晴恐高，之后她因身高未达要求，无法参加雷神之锤及其他刺激项目，只能在外等待，既遗憾又盼长高。思思逞强追逐刺激，莜莜体力不支，练武的阿牛最镇定。过山车乘客呕吐令思思抱怨，雨晴以玩笑回应，身体差异在同一游园经历中形成各自限制。\",\"turn\":\"雨晴被身高排除于项目外，群体玩乐呈现不同能力。\"},\"c146\":{\"key\":\"c146\",\"title\":\"“萝莉”的优势（上）\",\"kind\":\"main\",\"start\":576,\"end\":579,\"summary\":\"午后四人在游乐园大厅避暑，雨晴被限量水冰月玩偶吸引，把门票外剩余的钱全换成游戏币，仍抓取失败。她由此想到人生努力与舍弃可能都无回报，情绪崩溃落泪。旁观的洛胖、雷哥与管鹏注意到她；娃娃由园主侄子洛胖放入机器，三人商量上前帮忙。\",\"turn\":\"抓娃娃失败触发更深无望感，三个少年主动接近。\"},\"c147\":{\"key\":\"c147\",\"title\":\"“萝莉”的优势（下）\",\"kind\":\"main\",\"start\":580,\"end\":583,\"summary\":\"三位少年提出帮雨晴抓到水冰月，再由她登台唱歌作为交换。洛胖连续抓错但取得多个玩偶，雷哥换手后终于一次抓出三只、包括目标水冰月。雨晴感激又担心真实身份被知晓，仍接受约定走上小舞台，决定不放伴奏；少年们欣赏她却尚未留下联系方式。\",\"turn\":\"陌生人的帮助取得目标，唱歌约定让雨晴面对公众。\"},\"c148\":{\"key\":\"c148\",\"title\":\"动人的歌声\",\"kind\":\"main\",\"start\":584,\"end\":587,\"summary\":\"雨晴克服紧张，把平时自创旋律即兴填词，清唱迷茫前行、守住梦想的心情，感动大厅听众。三个少年交付水冰月及所有抓出的玩偶后离开，没有索取号码。她自留水冰月，将起司猫送莜莜、其余送思思，重新露出笑容；休息过后四人又决定去人工湖划船。\",\"turn\":\"歌声把个人困境转成被听见的表达，玩偶成为珍贵纪念。\"},\"c149\":{\"key\":\"c149\",\"title\":\"打地铺\",\"kind\":\"main\",\"start\":588,\"end\":591,\"summary\":\"划船时雨晴想起西湖与父母出游，向莜莜谈起希望被家人接纳；莜莜也承认父母古板但更喜欢独立生活。回家雨晴洗净玩偶，阿牛做面点，众人为避暑在客厅打地铺，读书、聊天、催思思给孙昊回电。雨晴受小说理想身份刺激而自行改变用药，温暖日常里藏着急切与风险。\",\"turn\":\"共眠客厅延长亲密感，思亲和求变压力未消。\"},\"c150\":{\"key\":\"c150\",\"title\":\"夜话\",\"kind\":\"main\",\"start\":592,\"end\":595,\"summary\":\"客厅夜话从宿舍闲聊转向身份与未来。思思坦言吸引对象不限于男性，阿牛询问药物代价；众人被未经证实的短寿传言压低情绪，又讨论不可逆身体改变、家人态度和谋生压力。思思承认愿望与顾虑并存，阿牛沉默最久。话题转开后，四人仍未找到解决困境的答案。\",\"turn\":\"改变身体的愿望与风险、家庭及工作之间的冲突被明说。\"},\"c151\":{\"key\":\"c151\",\"title\":\"相识\",\"kind\":\"main\",\"start\":596,\"end\":599,\"summary\":\"莜莜从噩梦惊醒，独自出门为四人买早餐，随后玩《传奇》。角色优子被怪群包围时，道士玩家有条色狼为她治疗解围，二人互加好友，相约挖矿练级，对方还送铁镐。原本习惯独自游戏的莜莜首次体会有伙伴一起走路、聊天的快乐，新关系在虚拟世界萌芽。\",\"turn\":\"安念在游戏里帮助新角色优子，使莜莜获得合租与公司之外的新朋友。\"},\"c152\":{\"key\":\"c152\",\"title\":\"相知\",\"kind\":\"main\",\"start\":600,\"end\":603,\"summary\":\"莜莜与有条色狼从游戏聊到生活和观念，得知对方住杭州，但因羞怯拒绝语音。室友们午前陆续起床，新闻预报夜间流星雨，思思提议上山观赏。雨晴清点药物后短暂胸痛，又回忆梦中成为女性、结婚育儿的圆满生活；醒后现实落差仍令她沉郁。\",\"turn\":\"网游关系加深；观星计划提出但本章未执行。\"},\"c153\":{\"key\":\"c153\",\"title\":\"前台收银\",\"kind\":\"main\",\"start\":604,\"end\":607,\"summary\":\"雨晴刚学收银便被抽调前台，未及时整理零钱又因紧张频频出错，遇到改价和权限问题只能求助主管。随着人流减少，她逐渐找到节奏，连报金额都不再结巴。过了下班时间仍无法离开，姚玲替她封住排队入口才结束加班；刚松口气，另一收银台传来顾客怒骂。\",\"turn\":\"首次实操形成能力与信心，却立即撞上服务冲突。\"},\"c154\":{\"key\":\"c154\",\"title\":\"前台纠纷\",\"kind\":\"main\",\"start\":608,\"end\":611,\"summary\":\"收银员与顾客因找回的旧钞发生争执，顾客先持物伤人，年轻员工暴怒反击酿成严重伤害，被警方带走，顾客送医。雨晴首次目睹如此暴力，震惊呕吐，回家路上仍不断重现现场；阿牛陪她并谈及自己的练武经历。事件将日常服务中的羞辱与瞬间失控的后果推到眼前。\",\"turn\":\"暴力结果尚待救治确认；目击给雨晴留下强烈冲击。\"},\"c155\":{\"key\":\"c155\",\"title\":\"平静的日常\",\"kind\":\"main\",\"start\":612,\"end\":615,\"summary\":\"室友晚间照常谈外貌、逗猫、打恋爱电话；莜莜宣布插画师朋友次日将来合住。曲奇按遥控器切到新闻，报道确认超市顾客抢救无效死亡、员工已被控制，室友才知道雨晴目击了事件。超市通知停业整顿、复工待定，雨晴与阿牛因此有空接待新室友。\",\"turn\":\"顾客死亡获新闻确认；停工连起新室友到来。\"},\"c156\":{\"key\":\"c156\",\"title\":\"林夕晨\",\"kind\":\"main\",\"start\":616,\"end\":619,\"summary\":\"林夕晨拖行李乘车至白兔街，在车上遭骚扰却没有外显回应。到合租屋后，雨晴与阿牛热情接待，她寡言而直接，自己挑空房入住，以药板表明与他们有相近经历。她自述一年前开始用药，父母尚不知情，容貌令两位室友羡慕；阿牛记下她喜欢鱼，准备晚餐。\",\"turn\":\"新室友入住，沉默性格与受骚扰时的反应尚待理解。\"},\"c157\":{\"key\":\"c157\",\"title\":\"三无少女\",\"kind\":\"main\",\"start\":620,\"end\":623,\"summary\":\"思思归家得知林夕晨十八岁，越界触碰对方却没有得到预期反应，反而被递上一罐旺仔牛奶。莜莜解释她是论坛ID夕子的插画师朋友、高中毕业后独立生活。众人晚间逛夜市，雨晴关心阿牛低沉状态，措辞却触痛其自卑；阿牛坦言不相信还能变得好看，关系首次明显紧绷。\",\"turn\":\"夕晨融入日常，阿牛却因体貌比较和不够体贴的安慰产生更深失落。\"},\"c158\":{\"key\":\"c158\",\"title\":\"胸部按摩\",\"kind\":\"main\",\"start\":624,\"end\":627,\"summary\":\"夕晨注意到雨晴低落，主动递牛奶，显示沉默中的关心。回家后雨晴因外貌比较而焦虑，独处时被夕晨误入房间撞见私密活动，尴尬地躲回客厅。思思与莜莜照常打闹，阿牛却因无人主动理会自己而受伤，只有夕晨观察到。超市停业三天明确，收银员父母仍请律师争取辩护。\",\"turn\":\"夕晨开始以行动表达关怀，阿牛孤立感加深。\"},\"c159\":{\"key\":\"c159\",\"title\":\"优雅的淑女\",\"kind\":\"main\",\"start\":628,\"end\":631,\"summary\":\"雨夜过后天气转凉，室友从客厅各回卧室；雨晴收拾曲奇偷开的猫粮，因超市尚停业而留家。思思和莜莜出门工作，雨晴为自己与夕晨准备粥、蛋和面包。夕晨极慢而优雅地用餐，主动分给她半杯牛奶，又因急着陪她喝完而显窘迫；阿牛反常地睡到很晚。\",\"turn\":\"雨晴渐懂夕晨的非言语亲近，阿牛作息异常继续。\"},\"c160\":{\"key\":\"c160\",\"title\":\"彩色铅笔画\",\"kind\":\"main\",\"start\":632,\"end\":635,\"summary\":\"夕晨在阴雨阳台以彩铅画出雨后夕阳、鸽群与浅虹，落款夕，再加雨晴二字郑重赠给她。雨晴感受被珍视，借夕晨工具回画许多带喜怒哀乐表情的Q版夕晨，祝她更自由表达心情。夕晨从身后握住雨晴执笔的手补画，亲密而温暖的接触使雨晴生出陌生悸动。\",\"turn\":\"夕晨用命名画作表达注视，雨晴第一次以回赠图画主动靠近她。\"},\"c161\":{\"key\":\"c161\",\"title\":\"温润的小手\",\"kind\":\"main\",\"start\":636,\"end\":639,\"summary\":\"夕晨补上一位张开双臂的大Q版人物，像拥抱其他小人；雨晴题名《心情》，夕晨珍藏。阿牛起床打断二人空间，雨晴独自反复回味牵手与香气，并读爱情文章对照心动。她由此困惑吸引与主动性是否影响自我认同，仍未得答案；窗外雨后晚霞竟与夕晨赠画相映。\",\"turn\":\"心动被雨晴辨认，但关系尚未表白；画中晴景在现实出现。\"},\"c162\":{\"key\":\"c162\",\"title\":\"新郎的梦\",\"kind\":\"main\",\"start\":640,\"end\":643,\"summary\":\"雨晴梦见自己作为成年新郎与林小姐结婚，梦境中的角色和身体却互相矛盾，使婚礼破碎。她又进入变得明亮热闹的梦中公园，见小男孩拥有妻子般的伴侣，被其安稳人生说法动摇，思考自己能否拥有婚姻与未来。小男孩送她香雪兰，梦末她认出书中赋予它的悲伤、痛苦与后悔寓意。\",\"turn\":\"梦境集中呈现身份与婚姻焦虑，不能视为真实婚礼。\"},\"c163\":{\"key\":\"c163\",\"title\":\"目送离开\",\"kind\":\"main\",\"start\":644,\"end\":647,\"summary\":\"复工清晨雨晴醒在夕晨床上，想起昨晚被思思灌醉却记不起如何睡来。两人出现亲吻与亲近，夕晨醒后仍平静，雨晴又惊又喜；闹钟显示已迟到。匆忙出门时，夕晨替她抹匀面霜，并始终在门口和窗边目送，雨晴将其想象成妻子送丈夫上班的温柔画面。\",\"turn\":\"真实亲近加深，但昨晚细节不明，雨晴误工。\"},\"c164\":{\"key\":\"c164\",\"title\":\"部门调动\",\"kind\":\"main\",\"start\":648,\"end\":651,\"summary\":\"迟到的雨晴被姚玲带往散称零食与酒柜部门，正式交给主管王海峰。她认出他曾失手让箱子砸到自己，而他与陈淑艳的拌嘴和搬货时的沉默形成反差。面对积压三天的大量货物，雨晴倍感吃力；王海峰随口说部门里女人也要当男人用，一度令她误以为身份暴露。\",\"turn\":\"岗位转入新部门，建立另一套同事关系与工作压力。\"},\"c165\":{\"key\":\"c165\",\"title\":\"跳脱的部门主管\",\"kind\":\"main\",\"start\":652,\"end\":655,\"summary\":\"忙到午后，王海峰与雨晴吃饭却记不住她的名字，还用烧焦的肉捉弄她，陈淑艳在旁维护并继续与他斗嘴。雨晴发现这位口无遮拦的主管会亲自做重活、处理事务井井有条。陈淑艳透露他出身贫困，由超市资助读大学，毕业后任主管五年，仍未升迁，令雨晴改观。\",\"turn\":\"雨晴开始能对领导顶嘴，也看到王海峰的能力与困境。\"},\"c166\":{\"key\":\"c166\",\"title\":\"抄写退货单\",\"kind\":\"main\",\"start\":656,\"end\":659,\"summary\":\"果冻公司业务员请求促销堆位，王海峰先以空间不足拒绝，私谈后答应下周安排，最终承认换取销售额分成。陈淑艳边调侃他边教雨晴抄退货单，雨晴观察便掌握流程，主动展示能力。主管去整理仓库、陈淑艳找货，她独自完成文书，新部门虽有灰色交易也有互相照顾的协作。\",\"turn\":\"雨晴融入新部门，看到主管权力与利益交换。\"},\"c167\":{\"key\":\"c167\",\"title\":\"苏雨晴的自制蛋糕\",\"kind\":\"main\",\"start\":660,\"end\":663,\"summary\":\"周五轮休日，夕晨完成插画订单，阿牛整上午把自己关在闷热房里。雨晴问午餐想吃什么，因夕晨答蛋糕便翻料理书尝试制作，辛苦搅拌仍想满足她。夕晨一直在旁安静陪看。直到等待出锅时，雨晴才发现冰箱本已有蛋糕，却仍珍惜亲手为她做食物的意义。\",\"turn\":\"雨晴以照顾表达好感，阿牛闭门准备另有缘由。\"},\"c168\":{\"key\":\"c168\",\"title\":\"胡玉牛的女装\",\"kind\":\"main\",\"start\":664,\"end\":667,\"summary\":\"阿牛鼓足勇气穿水手服、化妆走出房间，雨晴一时不知如何回应，夕晨却直接肯定并给他看身体转变的对照图片。得到鼓励后他感动落泪，雨晴也认真教日常穿裙礼仪。蛋糕因耽搁略焦但仍做成，夕晨点头认可，阿牛看出雨晴喜欢夕晨，问得她害羞辩解。\",\"turn\":\"阿牛获得珍贵肯定；雨晴情愫开始被同伴察觉。\"},\"c169\":{\"key\":\"c169\",\"title\":\"胡玉牛和莫空的邂逅\",\"kind\":\"main\",\"start\":668,\"end\":671,\"summary\":\"阿牛独逛夜市，海鲜香气唤起与父亲海边烧烤的童年，令他怀念过去又不愿退回原路。他买贝类和啤酒到公园竹林，遇到曾替雨晴挡混混的莫空。莫空说圆月残月各有观赏价值，接纳他的倾诉，却不逼问具体心事；阿牛仍盼自己能以理想形象获得保护。\",\"turn\":\"阿牛独自承受失落时遇莫空，残月与倾听为尚无答案的困境打开思考。\"},\"c170\":{\"key\":\"c170\",\"title\":\"天神和女神的故事\",\"kind\":\"main\",\"start\":672,\"end\":675,\"summary\":\"莫空给阿牛讲一个独立神话故事：恶魔之主杀害自愿献身保护众生的女神，夺回神位后陷入悔恨；女神所救妖狐寿终留下羽毛，与他保存的另一片相遇，使他回到过去成为妖狐。有限陪伴因轮回成为永恒，是莫空对结局的解释。阿牛还想追问为何不阻止悲剧，抬头莫空已离开。\",\"turn\":\"轮回寓言未回答能否改变悲剧，不能当现实主线历史。\"},\"c171\":{\"key\":\"c171\",\"title\":\"去集装箱房度假（上）\",\"kind\":\"main\",\"start\":676,\"end\":679,\"summary\":\"五位室友趁连休回郊区集装箱房，发现雨晴种的花与爬山虎已蓬勃生长。大家一起清扫灰尘、赶开踩脏床单的曲奇，忙碌也变得有趣。河边只一支钓竿，夕晨接手后熟练上鱼，思思与莜莜拿蚯蚓和网兜打闹，雨晴吹箫；曲奇玩水却被小螃蟹夹住爪子。\",\"turn\":\"共同劳动和田园生活巩固合住家庭感，夕晨钓鱼特长显露。\"},\"c172\":{\"key\":\"c172\",\"title\":\"去集装箱房度假（下）\",\"kind\":\"main\",\"start\":680,\"end\":683,\"summary\":\"曲奇反击螃蟹，夕晨钓满鱼篓后留大放小，五人傍晚烤鱼。雨晴因见血反胃，众人却又谈起药效停滞与私人诊所身体手术的可能；高昂费用和不确定安全让人犹豫，阿牛重新立志赚钱。许愿时多数人盼父母接纳，阿牛盼漂亮，夕晨却希望胸小些，揭示外人羡慕未必等于本人舒适。\",\"turn\":\"阿牛获得新的身体改变目标；各人愿望显示不同困境。\"},\"c173\":{\"key\":\"c173\",\"title\":\"安念\",\"kind\":\"main\",\"start\":684,\"end\":687,\"summary\":\"郊居清晨众人多仍贪睡，莜莜与游戏好友继续组队。对方送战士装备，两人交换名字：她报女性名方莜莜并谎称父母所取，他自报名安念，两人又加QQ。谈到大公会霸占练级区，安念提议自己建公会，莜莜愿作首位成员，友情由日常聊天迈向共同组织。\",\"turn\":\"有条色狼明确实名安念，双方建立更私人联系。\"},\"c174\":{\"key\":\"c174\",\"title\":\"春宫阁\",\"kind\":\"main\",\"start\":688,\"end\":691,\"summary\":\"安念拉好友凑十人创建《传奇》行会春宫阁及同名QQ群，莜莜加入并调侃会长。现实中众人发现冰箱没菜，思思提议捉蝉作为野趣午餐；雨晴怕热不愿去，被玩闹劝出门。思思自己又被高温吓退，伙伴合力阻止她临阵逃跑，五人带着笑闹向屋后树林出发。\",\"turn\":\"线上公会成立；线下郊游进入采集食物阶段。\"},\"c175\":{\"key\":\"c175\",\"title\":\"捉知了\",\"kind\":\"main\",\"start\":692,\"end\":695,\"summary\":\"树林捉蝉时思思徒手示范失败，阿牛踢树震落蝉，却感到体力不如从前。思思逞强爬高成功收获，下来时踩空，被莜莜抢先垫护，二人避免重伤。莜莜夸大疼痛吓她、提醒不可鲁莽，雨晴在旁配合；随后阿牛踢树、思思爬树、莜莜收集，分工继续。\",\"turn\":\"莜莜救下失足思思，以假装较重伤势促她谨慎。\"},\"c176\":{\"key\":\"c176\",\"title\":\"油炸知了\",\"kind\":\"main\",\"start\":696,\"end\":699,\"summary\":\"众人带近百只蝉回集装箱房，思思发现油不足，骑电瓶车去村店补买调料；莜莜负责清洗，怕虫的雨晴与夕晨搬餐具和沉重煤气罐。煤气又不足，只得改在院中生火烹制。香味引得大家品尝，雨晴仍不敢入口，莜莜耐心递给她尝试，度假由游玩变成集体劳动。\",\"turn\":\"众人分工解决油料与燃料不足，简单晚餐展示能力互补和相处的耐心。\"},\"c177\":{\"key\":\"c177\",\"title\":\"意外的美味\",\"kind\":\"main\",\"start\":700,\"end\":703,\"summary\":\"雨晴第一次吃蝉强忍不适，又主动重试，终于觉得美味，曲奇和咖啡也来分食。星空下众人谈未来：思思想与爱人经营僻静杂货店，莜莜想有伴侣并保留在家工作、领养孩子的生活，雨晴想做幼师、获父母认可和爱人相伴。阿牛说自己没有未来，模特愿望也像随口应付，温馨晚餐转为沉重自责。\",\"turn\":\"普通生活愿望显得遥远；阿牛绝望被明确说出。\"},\"c178\":{\"key\":\"c178\",\"title\":\"一个无法入眠的夜\",\"kind\":\"main\",\"start\":704,\"end\":707,\"summary\":\"同夜五人都无法入眠，雨晴以佛教观念作精神依靠，阿牛则坚持索取药贩联系方式、急于身体改变，思思暂缓回应。谈未来时夕晨沉默，叙述揭示她有三个姐姐、曾被重男轻女的父亲因成绩反复公开殴打羞辱，随后逃家。她其实渴望交流，却难以表达，暗中说出杀父的愿望，旁人没有听见。\",\"turn\":\"夕晨的沉默获得创伤背景，杀父念头尚未行动。\"},\"c179\":{\"key\":\"c179\",\"title\":\"酒柜\",\"kind\":\"main\",\"start\":708,\"end\":711,\"summary\":\"雨晴被安排在酒柜收银，虽比前台清闲却要久站，身体不适。王海峰先拿小梯子自坐、与她斗嘴，又以算术题捉弄她，最终把座位让出并宣布中午请部门同事吃饭。两人围绕长期卖不出的名贵茅台和没墨水的笔互损，雨晴在他面前展现不同于平日的活泼与不服气。\",\"turn\":\"王海峰嘴上戏弄而行动关照，雨晴敢平等顶嘴。\"},\"c180\":{\"key\":\"c180\",\"title\":\"排班表\",\"kind\":\"main\",\"start\":712,\"end\":716,\"summary\":\"王海峰告知每周可休两日，雨晴要求周末连休，却不愿独上晚班，缠得他与陈淑艳一同排晚班。主管因打麻将赢了钱，请早班五人去小餐馆；同事们在打卡、点菜和木瓜玩笑里互相调侃，陈淑艳甚至真咬他的手。雨晴感到轻松，也隐约看到工作规则中的变通。\",\"turn\":\"新的双休日与晚班确定，部门饭局拉近关系。\"},\"c181\":{\"key\":\"c181\",\"title\":\"明争暗斗\",\"kind\":\"main\",\"start\":717,\"end\":720,\"summary\":\"饭局上雨晴发现笑闹背后陈淑艳被翁锡芽和徐嫂疏远。徐嫂谈即将高三的儿子，王海峰透露自己读浙江大学农科，本想回乡种田，后因家乡偏远留在城市，并建议徐嫂考虑儿子喜欢动物的兽医方向。他自然替夹不起豆腐的雨晴夹菜，却引来成人暧昧玩笑，使她拘谨害羞。\",\"turn\":\"王海峰教育背景明确；雨晴察觉同事之间排斥与拉拢。\"},\"c182\":{\"key\":\"c182\",\"title\":\"勾心斗角\",\"kind\":\"main\",\"start\":721,\"end\":724,\"summary\":\"饭后打包剩菜又激起陈淑艳与两名女同事暗斗。回超市路上，徐嫂和翁锡芽逼雨晴表态认同对陈的贬低，并安排她与自己一起工作；她为免得罪只能含糊回应。回到王海峰面前，两人又笑脸融入聊天。麻将电话拆穿主管次日排晚班的理由，雨晴见识熟人嬉闹与职场站队并存。\",\"turn\":\"雨晴被动卷入同事阵营，日常交往不再全然轻松。\"},\"c183\":{\"key\":\"c183\",\"title\":\"胡玉牛的一天（上）\",\"kind\":\"main\",\"start\":725,\"end\":728,\"summary\":\"阿牛在后仓连续搬运重货，体力恢复变慢却仍超过同事。他主动替促销员取高处米箱，因任劳任怨被接纳；后仓主管察觉疲惫，暂给他分配较轻的传递工作。经理以请快餐鼓励继续，阿牛稍恢复又扛下收尾重活。群体认可主要建立在他的力量和勤劳上，与其内心愿望形成反差。\",\"turn\":\"阿牛获得劳动群体关心，也感到身体能力正衰减。\"},\"c184\":{\"key\":\"c184\",\"title\":\"胡玉牛的一天（下）\",\"kind\":\"main\",\"start\":729,\"end\":732,\"summary\":\"午后休息时阿牛抵挡不住同事递烟，又去买双喜，戒烟宣告中断。烟味让他回忆曾以父亲为榜样，后来怀疑所谓武学家族不过没落卖艺班，祖传伤药或比武术更有生计前景，却不被父亲接受。他由拒绝继承走向女性身份探索，如今仍无法辨清哪个自己才真实，急切想借药物改变身体。\",\"turn\":\"阿牛的家族神话被其自身质疑，情绪依靠转向吸烟。\"},\"c185\":{\"key\":\"c185\",\"title\":\"晚班\",\"kind\":\"main\",\"start\":733,\"end\":735,\"summary\":\"连上数日晚班后雨晴熟悉酒柜工作，偶尔替陈淑艳做文书与换标签。陈承担轻活招致同事嫉妒，雨晴选择不站队。一位和善的中年顾客突然要求最贵的酒，拒绝便宜替代品；王海峰开柜取出久未售出的龙年茅台，顾客仔细查看后决定买下，称临时有事未及准备礼物。\",\"turn\":\"长期陈列的茅台终遇买家，顾客身份引出疑问。\"},\"c186\":{\"key\":\"c186\",\"title\":\"陈淑艳的总结报告\",\"kind\":\"main\",\"start\":736,\"end\":739,\"summary\":\"购酒客付款离开，雨晴觉得他似台湾大表哥却不敢确定；同事争论他是官员还是商人，均无证据。王海峰因售出贵重酒获奖金，又催陈淑艳写半年总结；她胡乱夸大功劳后改抄他的范文，并拉雨晴帮抄。主管以排班迁就她，使部门的偏爱、互损和现实形式主义并行。\",\"turn\":\"茅台售出完成；购酒客与亲属是否相关仍未证实。\"},\"c187\":{\"key\":\"c187\",\"title\":\"深夜的街道\",\"kind\":\"main\",\"start\":740,\"end\":742,\"summary\":\"晚班十点后突降雨，雨晴独自步行回家，因不愿劳累早班的阿牛而拒绝接送。她在西瓜摊被当成晚归学生，顺着话题听摊主谈孩子作业，想起母亲逼自己套用作文范本的往事；虽原只想看看，仍因不好意思拒绝而买下大西瓜，继续在暗雨中艰难前行。\",\"turn\":\"怕麻烦别人和难以拒绝陌生人的性格，再次让她独自承受负担。\"},\"c188\":{\"key\":\"c188\",\"title\":\"雨中的街道\",\"kind\":\"main\",\"start\":743,\"end\":746,\"summary\":\"雨晴又在小摊挑选五个绳编小挂件，按朋友特点分配气球、梳子、兔子、红酒和猫脸，摊主另赠蝴蝶。黑暗路段的动静使她惊惧，靠近才知是曲奇出来迎接；猫陪她穿过小区回家。屋里只有思思仍撑着困意看电视，她把礼物放好，先替淋湿的猫洗澡，再去洗漱。\",\"turn\":\"曲奇的迎接和按人选礼物的细节，把独行的恐惧接回家庭般的日常。\"},\"c189\":{\"key\":\"c189\",\"title\":\"张思凡的心事（上）\",\"kind\":\"main\",\"start\":747,\"end\":750,\"summary\":\"雨晴带曲奇回房安睡，思思却为白天父母催找女友、安排相亲而失眠；她争辩时漏出对女孩无兴趣，担忧身份、家人和恋人无法兼容。她致电孙昊哭诉，对方在听到她本来的声音时烦躁喝止，待她恢复伪女声又温柔安慰，许诺永不抛弃；她未察觉这种态度变化。\",\"turn\":\"思思把父母的压力交给恋人安抚，而恋人的温柔已显出对声音与女性外表的条件。\"},\"c190\":{\"key\":\"c190\",\"title\":\"张思凡的心事（下）\",\"kind\":\"main\",\"start\":751,\"end\":755,\"summary\":\"孙昊答应下周一来陪伴，思思依恋通话直到手机断电，穿着让自己安心的女性衣物入睡。梦中却浮出被富客囚禁和性侵虐待的记忆：她因急需大笔钱接受中间人安排，到了别墅后失去反抗能力，对方用高额包养承诺和控制阻止离开。她不断求救，安全感被旧创伤彻底冲破。\",\"turn\":\"恋人的承诺暂时安抚现实焦虑，却未能阻止被控制和受辱的创伤重现。\"},\"c191\":{\"key\":\"c191\",\"title\":\"森林冒险（一）\",\"kind\":\"main\",\"start\":756,\"end\":759,\"summary\":\"周末雨停放晴，思思反常地早起招呼大家去海边散心，并用玩笑掩饰噩梦留下的恐惧；莜莜察觉后没有追问。阿牛以有事和晚间大夜班为由留下，他同样做了噩梦，梦见父亲因其女性身份而杀害自己并自尽。这只是他对父亲偏执的恐惧，并未在现实发生。\",\"turn\":\"四人外出与阿牛独留分成两条线；两人的噩梦揭出玩笑和沉默背后的恐惧。\"},\"c192\":{\"key\":\"c192\",\"title\":\"森林冒险（二）\",\"kind\":\"main\",\"start\":760,\"end\":763,\"summary\":\"四位室友换好女装结伴出发，阿牛在门关上后感到被美丽、女性身份和陪伴共同排除。公交车驶向郊外，雨晴有意同夕晨搭话，夕晨带了画具并因晕车靠在她肩头睡着；雨晴既满足于这种亲近，又误把照顾和心动看作男性角色的证明，对身份和爱情更加迷惑。\",\"turn\":\"阿牛的孤独与雨晴夕晨的亲密并置，关系内部的温差进一步扩大。\"},\"c193\":{\"key\":\"c193\",\"title\":\"森林冒险（三）\",\"kind\":\"main\",\"start\":764,\"end\":767,\"summary\":\"四人坐近两小时公交后仍须穿过农田走向森林。思思和莜莜兴奋地摘取他人田里的南瓜藤、黄瓜与丝瓜，再拉着同伴逃跑，雨晴体力最弱而腹痛疲惫。到林缘后众人休息，思思用过去来过的经验淡化野兽风险；夕晨把华夫饼分给雨晴，使她把普通照料感受为恋人的分享。\",\"turn\":\"轻率的野外准备和雨晴的虚弱为危险埋伏笔，夕晨的分享继续推动感情。\"},\"c194\":{\"key\":\"c194\",\"title\":\"森林冒险（四）\",\"kind\":\"main\",\"start\":768,\"end\":770,\"summary\":\"思思选择一条通往海边的林间小路，折树枝领队并不断安慰惧蛇的雨晴，享受保护妹妹般的成就感。越往深处杂草越密，莜莜被荆棘划伤，众人又闻到强烈腥臭，却未及时退出；树后突然出现棕熊逼近，思思率先拉起雨晴逃跑，原本轻松的郊游骤然变成险境。\",\"turn\":\"对安全的乐观判断被突发熊袭打破，四人的行动进入危机。\"},\"c195\":{\"key\":\"c195\",\"title\":\"森林冒险（五）\",\"kind\":\"main\",\"start\":771,\"end\":774,\"summary\":\"熊的追赶让四人慌乱跑散，思思先到海滩等候，莜莜与夕晨一起找到另一条小路。雨晴却奔跑过度昏倒，醒来已是夜晚，独自在陌生森林里无助地呼唤同伴；背包异响又使她惊惧，幸而钻出的是随行的曲奇，猫的出现让她从彻底孤立中获得一点安慰。\",\"turn\":\"同行者分成三组；雨晴在身体极限与失联中必须依靠曲奇。\"},\"c196\":{\"key\":\"c196\",\"title\":\"森林冒险（六）\",\"kind\":\"main\",\"start\":775,\"end\":778,\"summary\":\"雨晴发现已是晚七点半，手机没有信号，也辨不清方向。曲奇带她寻找树木栖身过夜，她勉强爬上树，仍被黑暗、冷意与声响折磨。莫空恰好路过，想吓一下树上迷路的孩子；雨晴误认树下黑影为熊，慌乱坠落昏厥，被他及时接住，这才认出是曾相识的少女。\",\"turn\":\"曲奇保全陪伴，莫空接住坠树的雨晴；救援前的惊吓也出自他的玩笑。\"},\"c197\":{\"key\":\"c197\",\"title\":\"森林冒险（七）\",\"kind\":\"main\",\"start\":779,\"end\":782,\"summary\":\"昏迷中的雨晴梦见祭坛和九尾狐耳少女，以为自己将转生而期盼成为天生女孩；醒来却在同伴身边，已到次日中午，得知莫空将她救出。大家在海边重聚，莜莜和思思仍以为莫空不知她们的出生性别，打趣他适合照顾雨晴；夕晨则以轻摸脑袋安慰她。\",\"turn\":\"雨晴脱险重聚；旁人未知莫空已在面馆得知她的身份，形成信息差。\"},\"c198\":{\"key\":\"c198\",\"title\":\"森林冒险（八）\",\"kind\":\"main\",\"start\":783,\"end\":786,\"summary\":\"莫空钓鱼、思思烧烤，众人在海边补吃迟来的午餐。他说明那只熊是附近猎人朋友饲养，主人尚未来得及喊住她们便跑散，并指出别墅旁有安全大路。莫空离开时，雨晴被他的沉稳吸引，却怕自己不被接受；对夕晨的心动又让她无法确定爱情与人生选择，莜莜劝她留给时间。\",\"turn\":\"熊袭性质被重新解释；雨晴对莫空和夕晨的两种吸引开始正面冲突。\"},\"c199\":{\"key\":\"c199\",\"title\":\"阳光、大海和沙滩（上）\",\"kind\":\"main\",\"start\":787,\"end\":790,\"summary\":\"夕晨把现实中明朗平静的海画成乌云怒浪，显出外表沉静之下的另一种情绪。等莫空离开，四人换泳装下海，难得享受不受旁人审视的身体自由。雨晴发现农村长大的夕晨竟完全不会游泳，便主动邀她入水、提出教学；追问往事触及她的忧伤后，又体贴地转开话题。\",\"turn\":\"雨晴从被照顾者转为照顾夕晨的人，海的自由与画中风暴形成反差。\"},\"c200\":{\"key\":\"c200\",\"title\":\"阳光、大海和沙滩（下）\",\"kind\":\"main\",\"start\":791,\"end\":794,\"summary\":\"夕晨初学游泳时失去平衡，惊慌抓住雨晴，把两人一起拖入水中，思思及时游来扶起。雨晴看见夕晨少见的脆弱反而感到特别的亲近，之后耐心示范，陪她逐渐克服恐惧、练习漂浮和换气。教学让两人长时间相伴，也使雨晴更加困惑于自己的爱意与性别角色想象。\",\"turn\":\"短暂险情被同伴化解，夕晨愿意继续尝试，雨晴通过照料体验更明确的心动。\"},\"c201\":{\"key\":\"c201\",\"title\":\"海边别墅（上）\",\"kind\":\"main\",\"start\":796,\"end\":798,\"summary\":\"游泳练习不觉持续到傍晚，雨晴舍不得结束这次与夕晨密切相处的下午，却仍未确定如何表达爱情。众人收拾泳具和零食，循莫空指示前往海边别墅旁的大路以赶末班车。思思与莜莜猜测别墅主人身份，提及整片海滩被长期承租；夕晨方向感好、曾带莜莜出林也在此说明。\",\"turn\":\"郊游将结束，四人沿大路返程前意外接近另一条人物线。\"},\"c202\":{\"key\":\"c202\",\"title\":\"海边别墅（下）\",\"kind\":\"main\",\"start\":799,\"end\":802,\"summary\":\"四人在别墅门外再次见到步行街与超市的美丽少女，原被保镖催离，却被她邀请入内；她让女仆水水同坐，拒绝交换姓名，只问该不该追回同时爱上两人后放弃选择的男孩。思思和莜莜反对，雨晴认为应见面确认是否仍爱，少女受到触动。客人离开后，她独叹那人已失去过去记忆。\",\"turn\":\"无名少女提出两难爱情，雨晴的理解给她希望；失忆与未揭姓名保留后续悬念。\"},\"c203\":{\"key\":\"c203\",\"title\":\"夜间飙车（上）\",\"kind\":\"main\",\"start\":803,\"end\":805,\"summary\":\"离开别墅后思思轻率地评说少女的恋爱烦恼，又泛谈初中生幼稚，雨晴反驳并不慎提到总帮自己的同桌，引来朋友追问。四人搭上返城公交，司机闲聊别墅财富，雨晴独坐后排想起冉空城，既盼对方来电又怕被记挂，离家小半年的矛盾思念仍未得到回应。\",\"turn\":\"外部的爱情问题牵出雨晴自己的旧同桌，她对过去的依恋仍与新关系并存。\"},\"c204\":{\"key\":\"c204\",\"title\":\"夜间飙车（下）\",\"kind\":\"main\",\"start\":806,\"end\":808,\"summary\":\"陌生来电让雨晴期待是冉空城，接通却只是保险推销，她失落挂断。返城路上飙车者两度逼停公交，司机称领头人是市长之子，敢凭家世压下事故，众人愤怒却只能避让。镜头转向领先轿车，男司机乱扔的烟被一名胡子拉碴的路人踢回烫伤，找不到人便把怒气转向女伴。\",\"turn\":\"雨晴的来电希望落空；街头权势与对弱者泄愤延伸小说的压迫主题。\"},\"c205\":{\"key\":\"c205\",\"title\":\"雌性激素注射针（上）\",\"kind\":\"main\",\"start\":809,\"end\":812,\"summary\":\"叙事回到周六中午：阿牛留城的真正要事是去星辰诊所寻求激素注射。外表改变缓慢使他愿意忽略代价，医生孔雀虽宿醉困倦、令他不安，却看透他的拘谨并表示不嘲笑。阿牛坚定接受注射并付费，把这次治疗当成尽快接近女性身体的希望，也开始考虑如何负担长期费用。\",\"turn\":\"阿牛从口服用药推进到私诊注射，追求变化的紧迫感压过风险顾虑。\"},\"c206\":{\"key\":\"c206\",\"title\":\"雌性激素注射针（下）\",\"kind\":\"main\",\"start\":813,\"end\":816,\"summary\":\"周日下午阿牛再次来到诊所，询问更强的抗雄药；孔雀推介昂贵注射和手术，他因费用与不可逆的恐惧暂时拒绝。回家联系不上尚在海边的同伴，他虽知道是自己选择留下，仍感到被抛弃，便独自去看青春爱情电影。银幕让他触动，身后情侣的不当亲热却破坏美感，引得他出声斥责。\",\"turn\":\"医学和经济限制未解，阿牛以独自观影填补空落，却又将受挫情绪带入陌生关系。\"},\"c207\":{\"key\":\"c207\",\"title\":\"一个人上班\",\"kind\":\"main\",\"start\":817,\"end\":820,\"summary\":\"暴雨工作日，前夜大夜班已做完多数工作，雨晴被安排独守酒柜早班。她费力逐瓶搬下高处的一箱酒，却仍受顾客责骂；午饭时又见夏伯伯惯被分派污脏破损品处理，替他不平，老人却认为总得有人做。她也注意到阿牛日益寡言敏感，会对绊脚板凳发怒，担心他的精神状态。\",\"turn\":\"雨晴独立处理工作困难；夏伯伯的全名揭为夏仕尼，阿牛的异常已被室友看见。\"},\"c208\":{\"key\":\"c208\",\"title\":\"孙昊又来了\",\"kind\":\"main\",\"start\":821,\"end\":824,\"summary\":\"孙昊突然告知火车将到，思思兴奋请假接站，却因来不及换女装而看到他明显失望，也不适应公共场合的亲昵。回家碰到女装化妆的阿牛，对方受惊后冷淡锁门；孙昊嘲笑其外貌，思思认真要求尊重每个人追梦的权利。孙昊答应住一周，思思仍满怀期待准备大餐。\",\"turn\":\"孙昊对思思男装与阿牛外表的反应，具体暴露他接纳身份的局限；思思为室友立下尊重边界。\"},\"c209\":{\"key\":\"c209\",\"title\":\"躁动\",\"kind\":\"main\",\"start\":825,\"end\":828,\"summary\":\"孙昊等思思换装时，阿牛独困热房，短暂出现轻生念头又压下，开始意识到自己的抑郁加深。思思精心换女装后重新获得恋人的热烈关注，随后忙做西餐，却被他不断纠缠亲热，她坚决拒绝在厨房继续。夕晨恰好出现，令两人尴尬，也立即吸引了孙昊的目光。\",\"turn\":\"阿牛心理危险上升；思思获得的亲密仍依赖女性形象，孙昊注意力开始转向夕晨。\"},\"c210\":{\"key\":\"c210\",\"title\":\"童颜巨乳的杀伤力\",\"kind\":\"main\",\"start\":829,\"end\":832,\"summary\":\"孙昊靠近夕晨看电视，介绍自己时有意只称思思的朋友；思思察觉不悦仍加以宽容。莜莜下班初次见他后礼貌相待，雨晴则一贯冷淡。西餐席上阿牛不会用刀叉而烦躁，夕晨默学雨晴；孙昊依次敬酒、盯视夕晨并调笑身材，莜莜遂明确告诉他夕晨与大家一样并非出生为女。\",\"turn\":\"孙昊淡化恋人名分并觊觎室友，晚餐上的身份揭示为进一步反应作铺垫。\"},\"c211\":{\"key\":\"c211\",\"title\":\"舔\",\"kind\":\"main\",\"start\":833,\"end\":835,\"summary\":\"得知夕晨身份后孙昊仍关注她，思思明显吃醋、要求他收敛，却把不安当作错觉。晚间夕晨替怕冷的雨晴分盖外衣，两人相拥睡在沙发上，莜莜再为她们盖毯；阿牛反锁房门不回应关心，大家仍相信他身体强壮。夜深后思思与孙昊亲密，叙述确认她曾受富商包养控制与药物伤害。\",\"turn\":\"照顾与隔绝同时发生；思思的旧伤获得叙述确认，阿牛的无回应被低估。\"},\"c212\":{\"key\":\"c212\",\"title\":\"榨干\",\"kind\":\"main\",\"start\":836,\"end\":839,\"summary\":\"思思与孙昊彻夜亲密直至极度疲惫，过程中她未充分尊重他想停下休息的意愿。两人睡到次日下午，声音嘶哑、乏力口渴，由夕晨递水照料；思思担心旷工被辞，才发现莜莜早已替她联系领导请假。随后她照顾仍虚弱的孙昊，也追问得知他交往过十几个女友。\",\"turn\":\"热烈亲密造成身体透支，同伴替两人维持生活与工作秩序；恋爱经历差异进一步显露。\"},\"c213\":{\"key\":\"c213\",\"title\":\"散心（上）\",\"kind\":\"main\",\"start\":840,\"end\":842,\"summary\":\"叙事回到当天早晨，休假的雨晴醒来发现自己抱着夕晨安睡，既羞怯又高兴。她不愿整天面对思思与孙昊，邀夕晨出门却被专注作画的对方婉拒，于是撑伞随意坐公交散心。车经过初来时露宿的小木屋与三流站，她意识到合租、工作与朋友已改变生活，又不自觉在无名面馆附近下车。\",\"turn\":\"新生活的安稳与旧地的回望相互映照，雨晴尝试整理自己失去和得到的东西。\"},\"c214\":{\"key\":\"c214\",\"title\":\"散心（下）\",\"kind\":\"main\",\"start\":843,\"end\":845,\"summary\":\"雨晴在无名面馆外看见李叔叔读报、张阿姨午憩，感激当年收留，也想告知如今安顿下来，却因穿裙且怕再遭其儿子般的羞辱而没有进门。她买奶茶沿旧街行走，习惯性寻找早已同住的曲奇，并回想一则能预知未来却每天失忆的故事，逐渐认可未知而不可重来的人生价值。\",\"turn\":\"她未完成旧友重逢，却清楚感受到有家难回的边界，并从寓言中理解未知的意义。\"},\"c215\":{\"key\":\"c215\",\"title\":\"夏日的河堤（上）\",\"kind\":\"main\",\"start\":846,\"end\":849,\"summary\":\"雨晴独坐旧河堤，想起莫空讲过的鱼与鹰，也困惑于自己越来越模糊的记忆，须反复核查排班。附近两位少年打闹落水又自行游起，她起初未认出他们；两人却认出游乐园唱歌的女孩，互相怂恿着来搭话。她感到被当作喜欢的女孩子看待，既开心又羞涩。\",\"turn\":\"旧游乐园缘分重新出现，雨晴首次体验同龄少年主动搭话的欣喜。\"},\"c216\":{\"key\":\"c216\",\"title\":\"夏日的河堤（下）\",\"kind\":\"main\",\"start\":850,\"end\":853,\"summary\":\"两位少年正式介绍姓名：浪人发型的是万剑雷，小圆脸是管鹏；玩笑与拘谨逗笑雨晴，也让她允许二人坐在附近。她隐瞒离家和打工，称自己仍在杭州上学、暑假来玩；他们则说即将升入文澜学院高中部。关于学校和未来的闲谈，使早早离校的她重新向往普通的求学生活。\",\"turn\":\"少年身份与关系被补全；雨晴以学生假话维护交往，也暴露她对正常校园生活的失落。\"},\"c217\":{\"key\":\"c217\",\"title\":\"淋雨（上）\",\"kind\":\"main\",\"start\":854,\"end\":857,\"summary\":\"管鹏拿万剑雷钱包扇风，翻出配美女图的维修广告名片，误会化解后，三人同步咳嗽又笑，雨晴羡慕两少年的默契。骤起风雨把她吹倒、伞也卷走，两人无需商量便一人扶她、一人追伞。少年们兴奋淋雨，她一边劝找地方避雨，一边向往这种无需顾忌的任性自由。\",\"turn\":\"默契不只停在玩笑中，也化为照料她的行动；保护与自由形成吸引。\"},\"c218\":{\"key\":\"c218\",\"title\":\"淋雨（下）\",\"kind\":\"main\",\"start\":858,\"end\":861,\"summary\":\"雨晴因早产、先天心脏病和童年重病经历不敢随少年淋雨，想起母亲长期照顾。万剑雷忽然决定离开，她又落入难结新友的孤独。之后独往集装箱，看燕子哺雏更思念父母，未坐多久便返程；第二阵暴雨来时，她终于收伞奔跑，虽疲惫打喷嚏，却由衷感到活着与偶尔任性的快乐。\",\"turn\":\"母爱既是保护也是负疚来源；一次主动淋雨使积郁暂时释放，却埋下身体后果。\"},\"c219\":{\"key\":\"c219\",\"title\":\"全身除毛\",\"kind\":\"main\",\"start\":862,\"end\":865,\"summary\":\"雨晴淋湿返家已觉头晕发冷，在门口遇到同样晚归的阿牛，发现他做了全身激光除毛，却因仍不像女孩而更加失落。两人沉默同行，她习惯性的“以后会好”也显得无力。阿牛再次锁门独处，雨晴帮他摆好乱踢的鞋，自己洗澡时既预感感冒，又从对照中意识到外表上的幸运。\",\"turn\":\"投入昂贵身体改变未缓解阿牛的自我否定；雨晴的任性则开始付出身体代价。\"},\"c220\":{\"key\":\"c220\",\"title\":\"后天性天然呆\",\"kind\":\"main\",\"start\":866,\"end\":869,\"summary\":\"雨晴洗澡被修后标识颠倒的冷热水开关吓到；夕晨在阳台画简笔画、照料曲奇和咖啡，叙述补充她平时也用复杂线条表达未知情绪。晚餐前莜莜被蚊咬向雨晴借风油精，她先拿成红花油，急着回房又绊倒，坐下后竟忘了借药之事，被思思戏称“后天性天然呆”。\",\"turn\":\"雨晴记忆与反应问题以笑闹呈现，夕晨的画及宠物照料补充其沉默之外的表达。\"},\"c221\":{\"key\":\"c221\",\"title\":\"龙卷风\",\"kind\":\"main\",\"start\":870,\"end\":873,\"summary\":\"天气反常早暗，雨晴感冒疲倦先睡，其他人也陆续回房；迟来的新闻警告海上龙卷风登陆，狂风暴雨造成街道积水、树木倒伏和设施损坏，次日还会有第二波，全城临时停课停工。她在高热梦中被纷乱线条困扰，清晨醒来看见死寂废墟，不知昨夜灾情而以为末日到来。\",\"turn\":\"暴雨后的身体病情与城市灾害并发，把日常住所变成暂时受困之地。\"},\"c222\":{\"key\":\"c222\",\"title\":\"严重发烧\",\"kind\":\"main\",\"start\":874,\"end\":877,\"summary\":\"发高烧的雨晴找不到室友回应，误以为只剩自己一人；思思被喊醒后抱住她，解释龙卷风和停工消息，再抱她回床休息。测得三十九点五度，家中退烧药几近用尽、药店未开，思思先用仅剩药物照料并熬姜汤，莜莜起床一起帮忙；她们的关心真实，临时应对却十分仓促。\",\"turn\":\"雨晴确认同伴仍在而重获安全感，有限药品和第二波灾害将考验照护。\"},\"c223\":{\"key\":\"c223\",\"title\":\"呓语\",\"kind\":\"main\",\"start\":878,\"end\":881,\"summary\":\"第二波大风提前到来，新闻纠正此次实际是台风，购药计划被迫取消。大家吃储备早餐，思思又被孙昊的专一誓言安抚；阿牛仍疏离。众人探望高烧梦中哭喊母亲的雨晴，夕晨握手贴颊使她平静。莜莜借机透露生母早年离开且已失联，如今与继母及父亲也少有亲近。\",\"turn\":\"夕晨的实际陪伴安抚雨晴的失亲恐惧，并引出莜莜不同于她的家庭缺憾。\"},\"c224\":{\"key\":\"c224\",\"title\":\"虚弱\",\"kind\":\"main\",\"start\":882,\"end\":885,\"summary\":\"海边别墅少女雯雯在风暴中向女仆水水谈及未来不同阶段的自己，嘱她照顾将来茫然抗拒世界的“我”；女仆长又称水水“小诗”。窗外莫空困惑于她所说的世界线，同时想起雨晴，明确选择不打扰的守护式爱意。另一边雨晴中午仍虚弱，夕晨守候并端来姜汤，一勺一勺照料。\",\"turn\":\"无名少女获得昵称并显出时间悬念；莫空的爱意与夕晨的贴身照料形成不同守护方式。\"},\"c225\":{\"key\":\"c225\",\"title\":\"喂食\",\"kind\":\"main\",\"start\":886,\"end\":889,\"summary\":\"夕晨喂病中的雨晴喝姜汤，以过分亲密却面无表情的方式帮她应对烫口，被思思和莜莜看见后起哄。雨晴脱口而出两人可以都是女朋友，得到她们认真认可，初次为自己的感情找到不必扮男性的解释；但她仍否认已成情侣，夕晨也依她的示意称其妹妹，关系保持含蓄未定。\",\"turn\":\"“两个都是女朋友”松动雨晴的性别角色困惑，但亲密举动尚不等于双方确认恋爱。\"},\"c226\":{\"key\":\"c226\",\"title\":\"停电\",\"kind\":\"main\",\"start\":890,\"end\":893,\"summary\":\"台风导致停电，思思因刚掉落的游戏装备未拾取而暴躁，被孙昊答应赔买后安抚；莜莜则提到游戏里有要好的朋友，明确并非男友。雨晴稍有好转，在黑暗中由夕晨牵手、曲奇叫声与尾巴提醒，慢慢走到客厅与大家汇合，莜莜用手机微光引路，众人决定聚着讲鬼故事。\",\"turn\":\"停电中烦躁与温柔同时显现，微光、牵手和猫共同建立集体的临时安全感。\"},\"c227\":{\"key\":\"c227\",\"title\":\"悬疑鬼故事\",\"kind\":\"main\",\"start\":894,\"end\":897,\"summary\":\"雨晴因一杯热水感到同伴关心，也自省近来会因微小玩笑长久难过。莜莜再次邀阿牛出房，他借黑暗穿护士装出来；孙昊暗中嘲笑，思思认真制止。随后思思讲浴室有鬼的故事，用激将法让病中的雨晴去看，她不愿被瞧不起而勉强走入，竟真的见到恐怖景象。\",\"turn\":\"阿牛暂时加入集体，恶作剧却利用雨晴怕被轻视的心理，把她推入惊恐。\"},\"c228\":{\"key\":\"c228\",\"title\":\"恶作剧\",\"kind\":\"main\",\"start\":898,\"end\":901,\"summary\":\"雨晴和莜莜先后被浴室发光鬼脸与尖叫吓坏，阿牛进去查看后也失声，思思、孙昊又相继“消失”。夕晨镇静开手电，照出装鬼的思思：录音机、贴纸和几人配合构成恶作剧，阿牛起初差点动手后才加入。雨晴生气，莜莜要求别再这样；夕晨解释母亲说鬼伤不了人。\",\"turn\":\"鬼故事以人为把戏收束，夕晨的镇定揭开真相，也显出她母亲给予的特殊安慰。\"},\"c229\":{\"key\":\"c229\",\"title\":\"融化的冰淇淋\",\"kind\":\"main\",\"start\":902,\"end\":905,\"summary\":\"停电使思思为大家买的昂贵进口冰淇淋逐渐融化，众人分吃后仍剩半箱，节俭的莜莜不舍丢弃。雨晴病未愈却吃冰淇淋，引发腹痛呕吐，思思自责道歉、莜莜热粥照料，阿牛沉稳确认医院仍开。朋友们担忧他的身份困境却不敢劝阻，彼此关怀与难以说出的真实想法交织。\",\"turn\":\"奢侈的小礼物因灾害失效，善意照料也会出错；阿牛仍能在他人危急时带来安定。\"},\"c230\":{\"key\":\"c230\",\"title\":\"黑暗中的国王游戏\",\"kind\":\"main\",\"start\":906,\"end\":909,\"summary\":\"莜莜提出成语接龙与传递信物结合的国王游戏，失败者由持信物者罚，众人选曲奇作传递对象，并让不擅说话的夕晨免答词。病中的雨晴不愿被排除，仍坚持参加；起初大家认真，后来规则被不断曲解、接龙偏向她难理解的成人笑话，她接连失败，把惩罚暂时累积。\",\"turn\":\"游戏让沉默与疏离者重新同坐，规则滑向越界玩笑也使雨晴的弱势更明显。\"},\"c231\":{\"key\":\"c231\",\"title\":\"暧昧的惩罚\",\"kind\":\"main\",\"start\":910,\"end\":913,\"summary\":\"接龙规则继续漂移，雨晴累积第三次失败，莜莜提出与夕晨亲密互动的惩罚，思思又在她犹豫时推着促成并拍照。阿牛虽曾开口，实际只建议关掉手电，没有真正制止压力。雨晴羞窘起身后头晕，倒在夕晨怀里睡着，众人确认只是困倦才放下心，游戏在疲惫与含蓄心动中停歇。\",\"turn\":\"游戏留下雨晴与夕晨的合照，但起哄和推动越过了明确同意，不能据此认定恋爱。\"},\"c232\":{\"key\":\"c232\",\"title\":\"神清气爽\",\"kind\":\"main\",\"start\":914,\"end\":916,\"summary\":\"台风离去的清晨，咖啡翻动雨晴摘抄本，平凡构成人生的句子与灾后安静相映。雨晴退烧醒来异常精神，发现病中已有几天没吃药，短暂向往不用药也能保持女性身体的生活，最终仍因害怕男性化而恢复用药。她看见数次未知号码未接来电，又读到王海峰要求今日复工的短信。\",\"turn\":\"身体轻松引出对长期代价的清醒犹豫；未知来电与复工将她重新带回外部世界。\"},\"c233\":{\"key\":\"c233\",\"title\":\"台风过后\",\"kind\":\"main\",\"start\":917,\"end\":920,\"summary\":\"雨晴早起整理工作物品，阿牛却以要提前上班为由独自先走，继续回避同行。她穿新帆布鞋缓步赴工，看到灾后积水、倒树、涨价早餐及与现实不符的乐观报道；上班者与学生仍须涉水恢复日常。一个把树枝当剑、兴奋玩水的小学生，让她想起自己渐被成长和社会磨去的天真。\",\"turn\":\"阿牛继续退出共同日常，雨晴在城市复工景象中体认成长的失落。\"},\"c234\":{\"key\":\"c234\",\"title\":\"芥末味棒棒糖\",\"kind\":\"main\",\"start\":921,\"end\":924,\"summary\":\"台风后超市仍供电，因无新货而清闲，王海峰安排雨晴与陈淑艳上班，并说明实习工无需补休。雨晴看两人互损、谈孩子复学与大学经历，感到工作像熟悉校园般轻松，甚至主动笑说不当电灯泡。陈淑艳表面谢主管照顾，递上一支写巧克力的棒棒糖，实际是芥末味，把王海峰辣得咳嗽。\",\"turn\":\"部门互损成为雨晴少有的轻松社交，她也逐渐能主动参与玩笑。\"},\"c235\":{\"key\":\"c235\",\"title\":\"炙热的艳阳\",\"kind\":\"main\",\"start\":925,\"end\":927,\"summary\":\"复工午间员工争抢临期食品茶话会，雨晴不惯抢食而独坐楼梯窗边吃炒面，比较旧日上流宴会的礼仪与底层生活的直接。灾后晴空使她向往历尽磨难后的重生，也意识到苦难未必换来幸福；王海峰受陈淑艳嘱托送来各种食物，以玩笑打断她的沉郁，让平凡同事情谊补回希望。\",\"turn\":\"雨晴对希望的抽象思考被具体关怀接住，部门两位同事共同照顾她。\"},\"c236\":{\"key\":\"c236\",\"title\":\"好烟和劣烟\",\"kind\":\"main\",\"start\":928,\"end\":931,\"summary\":\"阿牛独自清理后仓、少吃午餐以求身材变化，感到力气确实下降，旁人却仍只见强壮；复吸香烟也成了缓解孤独的习惯。买烟时他又遇莫空，对方同时买廉价大丰收和中华，先谈清贫与享乐，再说明只是体验笔下人物心理。阿牛从中想起兴趣与被迫工作之别，回头时莫空已离开。\",\"turn\":\"身体变化给阿牛微小希望，莫空以写作体验再度触及自主选择与幸福。\"},\"c237\":{\"key\":\"c237\",\"title\":\"一碗猪肉面（上）\",\"kind\":\"main\",\"start\":932,\"end\":934,\"summary\":\"思思带孙昊到公司附近网吧，边上班边频繁联系，既惜短暂相聚也回避他对男装的不适。独处的夕晨通过挂名工作室承接插画，收入浮动却有保障；她不追求电脑，擅手工、布置层次丰富的房间，画出房间及猫鼠时向咖啡露出罕见笑容。因不擅料理，中午抱着曲奇、咖啡出门找饭店。\",\"turn\":\"夕晨作为创作者的自主生活和对动物的柔情浮现，沉默不再等同情感贫乏。\"},\"c238\":{\"key\":\"c238\",\"title\":\"一碗猪肉面（下）\",\"kind\":\"main\",\"start\":935,\"end\":938,\"summary\":\"夕晨在灾后涨价的拉面馆点牛肉面，老板却送来猪肉面，她虽注意清真标牌与餐食矛盾，仍不愿追究，只分食给猫鼠并沉入童话幻想。叙述说明她有约三万元存款、内心世界是安全感寄托。店外随后来两派人，以宗教标识和侮辱问题争吵堵门，她仍安静吃面，与惊慌食客形成反差。\",\"turn\":\"幻想、节省与外界冲突并置，揭出夕晨将现实和心灵隔开的生存方式。\"},\"c239\":{\"key\":\"c239\",\"title\":\"刷墙工\",\"kind\":\"main\",\"start\":939,\"end\":941,\"summary\":\"店内两派人终于扭打，夕晨吃完付款，抱猫鼠安然离开。路遇烈日下悠闲刷墙的工人，她想起父亲农闲进城苦工供其读书、把她所赠登山鞋珍藏，以及为唯一儿子取“希望的早晨”之名却把希写成夕。她以创业为由离家，既深爱父亲又不后悔追求女性生活，强烈负疚使冷静面具崩溃，落泪归家。\",\"turn\":\"夕晨的无表情显出自我麻醉功能；父爱、重男轻女、身份与负疚形成深刻冲突。\"},\"c240\":{\"key\":\"c240\",\"title\":\"肯德基\",\"kind\":\"main\",\"start\":942,\"end\":945,\"summary\":\"思思忙完任务已近下午一点，与孙昊到肯德基吃午餐。男装的她被恋人当众亲昵称呼，引来顾客厌恶和母亲对孩子的贬斥，只能仓皇打包离开；她又把收银员口误疑作驱赶。孙昊轻描淡写说反正要变女孩，触怒她而挨一巴掌；两人沉默后同时道歉、继续去吃东西，表面和好却已埋下隔阂。\",\"turn\":\"社会羞辱与恋人不能理解她的双重身份引发冲突；相互道歉未能消除关系裂缝。\"},\"c241\":{\"key\":\"c241\",\"title\":\"大白腿（上）\",\"kind\":\"main\",\"start\":946,\"end\":949,\"summary\":\"方莜莜兼任后勤保全组长、程序开发与英文合同撰写，虽获老板信任，却一人承担多职、周旋于职场关系。她鼓励擅长数学但容易分心的年轻下属朱志杰学习编程。送餐女孩意外打翻饭菜弄脏她的裤子，她温和免于责难，准备请林夕晨送替换衣物。\",\"turn\":\"职场的男性呈现与真实身体之间，因换裤子的意外出现暴露风险。\"},\"c242\":{\"key\":\"c242\",\"title\":\"大白腿（下）\",\"kind\":\"main\",\"start\":950,\"end\":953,\"summary\":\"方莜莜在办公室脱去被汤弄脏的外裤，朱志杰意外注意到她明显女性化的身体，她担心同事把自己视为异类，随后误打开女装网页又加深尴尬。林夕晨送来宽松男裤，朱志杰主动买单、借上厕所避开换衣。方莜莜想以女性身份生活，却仍受手术费用与证件限制。\",\"turn\":\"朱志杰发现反常但尚未追问，双方努力维持同事关系。\"},\"c243\":{\"key\":\"c243\",\"title\":\"恐怖片（上）\",\"kind\":\"main\",\"start\":954,\"end\":957,\"summary\":\"苏雨晴早班回家，短暂不见林夕晨便觉得不安；室友陆续回来，合租屋的热闹重新带来安全感。众人担心胡玉牛越来越疏远，尤其怕他私自寻求危险的身体手术。张思凡和孙昊亲密嬉闹，林夕晨替他们拿衣物却全拿成女装，孙昊被迫短暂配合。\",\"turn\":\"集体日常的温暖，与胡玉牛独自承受压力形成落差。\"},\"c244\":{\"key\":\"c244\",\"title\":\"恐怖片（下）\",\"kind\":\"main\",\"start\":958,\"end\":961,\"summary\":\"孙昊穿女装引起笑闹后换回衣服。晚饭时胡玉牛仍未归，室友担忧却不敢强行干涉。张思凡坚持播放恐怖片，答应把一台 GBA 送给不愿看的苏雨晴。众人逐渐被影片吸引，门突然打开又关闭造成惊吓，最后发现只是胡玉牛回家，他的道歉显得十分生疏。\",\"turn\":\"胡玉牛与室友的隔阂被集体娱乐后的疏离反应再次显现。\"},\"c245\":{\"key\":\"c245\",\"title\":\"胡玉牛的爱情（一）\",\"kind\":\"main\",\"start\":962,\"end\":965,\"summary\":\"胡玉牛晚归沉默，原因并非工作或用药，而是十六岁顾客柳韵向二十岁的他告白。此前他在超市三次帮忙，让少女因安全感而喜欢上他。河中公园赴约后，胡玉牛既被打动，又害怕自己的女性愿望伤害对方，终于拒绝并逃走，留下柳韵哭泣。\",\"turn\":\"恋爱选择使胡玉牛的性别愿望、自卑与责任感正面冲突。\"},\"c246\":{\"key\":\"c246\",\"title\":\"胡玉牛的爱情（二）\",\"kind\":\"main\",\"start\":966,\"end\":969,\"summary\":\"胡玉牛在公交车上反省自己的愿望，承认它包含希望漂亮、受欢迎的成分，又认为梦想不必划分纯粹与否；回家仍拒绝交流，只读心理学书。新闻称面馆冲突嫌疑人已被警方控制。苏雨晴与咖啡相伴入睡，再梦见公园男孩，他哀悼一位未具名朋友，坟碑没有文字。\",\"turn\":\"自我反省没有消除胡玉牛的孤立；无名坟墓构成未解的不祥预示。\"},\"c247\":{\"key\":\"c247\",\"title\":\"胡玉牛的爱情（三）\",\"kind\":\"main\",\"start\":970,\"end\":973,\"summary\":\"梦中血雨冲开坟墓、露出模糊魁梧身影，苏雨晴惊醒后迅速遗忘。现实中柳韵在河中公园睡着，神秘九尾狐耳少女替她盖上男式外套；她误认是胡玉牛暗中照顾，重燃追求希望。胡玉牛一夜不眠又担心她受伤害，清早独自上班，对苏雨晴仍亲善却因自卑回避同行。\",\"turn\":\"一件来历被误认的外套，让本已被拒绝的恋爱继续发展。\"},\"c248\":{\"key\":\"c248\",\"title\":\"胡玉牛的爱情（四）\",\"kind\":\"main\",\"start\":974,\"end\":977,\"summary\":\"胡玉牛工作时心神不宁，拒绝与苏雨晴同行，下班受莫名心悸驱使走向与家相反的河边。听见呼救后发现柳韵正遭数名混混围困、面临性侵。他挺身救人，先借谈钱转移持刀者注意，但身体状态下降导致判断失误，最后一刻仍挡下了威胁柳韵的刀。\",\"turn\":\"保护他人的习惯压过退缩；救人使胡玉牛直面身体能力的变化。\"},\"c249\":{\"key\":\"c249\",\"title\":\"胡玉牛的爱情（五）\",\"kind\":\"main\",\"start\":978,\"end\":981,\"summary\":\"胡玉牛击倒六名混混，带柳韵离开后已明显体力透支；少女却把他视为理想英雄，更加主动亲近，自述小名音音来自奶奶的误读。她拿出外套坚信胡玉牛暗中爱护自己，即使他否认也不信。胡玉牛害怕坦白愿望后受鄙视，最终陪她逛步行街，在恋爱与自我追求间摇摆。\",\"turn\":\"救援转成约会，关系已靠近，但身体愿望的核心事实尚未坦白。\"},\"c250\":{\"key\":\"c250\",\"title\":\"胡玉牛的爱情（六）\",\"kind\":\"main\",\"start\":982,\"end\":985,\"summary\":\"柳韵喜欢巨型白熊却因价高放弃，胡玉牛被她的体谅打动，买下玩偶。她把它视为定情信物，并回赠黑线狮子戒指和黑狮子编织玩偶，自称未婚妻。胡玉牛承认内心幸福，却仍隐瞒脱毛等身体改变；送她回家后提出一个月冷静期，柳韵把它理解为爱情考验。\",\"turn\":\"双方互赠信物却没有共同理解的正式承诺，一个月之约留下悬念。\"},\"c251\":{\"key\":\"c251\",\"title\":\"苏雨晴在超市工作的日常（上）\",\"kind\":\"main\",\"start\":986,\"end\":988,\"summary\":\"2004年8月7日立秋暴雨，苏雨晴梦见幼儿园时母亲来接自己，醒来担心父母已经放弃寻找她。离家四个多月的她仍不敢计划春节返家，只为购电脑、身体手术等愿望存钱。清晨自制肉松鸡蛋泡饭，发现胡玉牛仍失眠恍惚；冰箱里持续出现的蛋糕则体现林夕晨的偏好。\",\"turn\":\"思乡与不敢回家并存，经济目标暂时代替了明确的人生方向。\"},\"c252\":{\"key\":\"c252\",\"title\":\"苏雨晴在超市工作的日常（下）\",\"kind\":\"main\",\"start\":989,\"end\":992,\"summary\":\"胡玉牛难得与苏雨晴共伞上班，试探真正的爱及受到女生告白后该如何选择。苏雨晴说愿尝试喜欢喜欢自己的人，想到若告白者是林夕晨则不能确定会拒绝。到超市后她面对大批货柜；女部门经理把正常轮休的王海峰指责为偷懒，使她看见善良勤劳也会被责难。\",\"turn\":\"胡玉牛向人求助却不明说；苏雨晴第一次具体设想与林夕晨恋爱的可能。\"},\"c253\":{\"key\":\"c253\",\"title\":\"背锅侠王海峰\",\"kind\":\"main\",\"start\":993,\"end\":996,\"summary\":\"苏雨晴帮徐嫂整理沉重货箱，照例接受琐碎差事，用少说话保护身份秘密；筋疲力尽后几经折返才吃上午饭。休息日被叫回的王海峰又遭训斥：数据部把九十九元的酒错录为九元九，经理仍怪他未纠错。他不愿无休止争辩，表示愿承担五瓶酒的损失。\",\"turn\":\"职场权责不对等显形，苏雨晴对王海峰的同情和理解加深。\"},\"c254\":{\"key\":\"c254\",\"title\":\"职业打假人\",\"kind\":\"main\",\"start\":997,\"end\":1000,\"summary\":\"常务经理老梅愿替王海峰澄清赔钱之事并邀他调去防损部，王海峰嫌工作易得罪人而拒绝。回酒柜后，翁锡芽替苏雨晴写表格。一个在柜前徘徊很久的男人买下一百九十九元红酒，随后到前台投诉商品不合格，王海峰接报判断可能遇上职业打假者。\",\"turn\":\"不合格红酒引出索赔事件，年轻员工担心赔款被转嫁。\"},\"c255\":{\"key\":\"c255\",\"title\":\"专业的和业余的\",\"kind\":\"main\",\"start\":1001,\"end\":1004,\"summary\":\"苏雨晴被叫到前台证明销售经过，忧虑索赔导致工资受损。王海峰问出对方熟知职业打假圈地盘更替，打电话给已接手本地的老耀；索赔者得知归属后退让。王海峰接回酒，再赠一包中华缓和冲突，使这场投诉在非正式人情与势力关系中被压下。\",\"turn\":\"投诉撤回，实际解决方式并非正式质量或法律裁决。\"},\"c256\":{\"key\":\"c256\",\"title\":\"检查保质期\",\"kind\":\"main\",\"start\":1005,\"end\":1008,\"summary\":\"王海峰圆满结束索赔协调，众人以玩笑缓和气氛；其他部门争邀苏雨晴，前台年轻女职员对王海峰流露好感。王海峰回去后要求酒柜促销员核查保质期和缺失厂家信息的商品，又把炒货区域每月检查交给苏雨晴，允许劳累的她当天先休息，次日开始。\",\"turn\":\"事件转化成例行质量检查；苏雨晴增加固定责任。\"},\"c257\":{\"key\":\"c257\",\"title\":\"一个人在家\",\"kind\":\"main\",\"start\":1009,\"end\":1012,\"summary\":\"下班后室友及宠物都不在家，林夕晨留纸条称有事，张思凡与孙昊外出约会，方莜莜也参加公司活动。已经依恋共同生活的苏雨晴因独处失落，独自做饭、看电视购物打发时间。她注意到眼下新生泪痣，入夜后因怕黑逐处开灯，最后躲回明亮卧室。\",\"turn\":\"她的安全感已深度依赖室友的在场，独处成为情绪引爆条件。\"},\"c258\":{\"key\":\"c258\",\"title\":\"冉空城的电话\",\"kind\":\"main\",\"start\":1013,\"end\":1015,\"summary\":\"苏雨晴补写日记，记录打假见闻、宠物习惯并画红酒；游戏机没电又使她无事可做。想让方莜莜带电池时误拨冉空城，旧友回电令她几乎失语。她说不会再打扰便挂断关机，随即因怀念过去与害怕破坏他的生活而大哭，一边责备自己的软弱。\",\"turn\":\"偶然通话重新刺痛旧日关系，冉空城尚未被明确告知身份。\"},\"c259\":{\"key\":\"c259\",\"title\":\"没有人的公园\",\"kind\":\"main\",\"start\":1016,\"end\":1019,\"summary\":\"哭累入睡的苏雨晴再次来到梦中公园，外面热闹却仍被无形屏障隔开，秋千上的男孩首次不见。黑暗推进时她坐上秋千，竟变成那个幼小男孩，思考能力也受限；面对一个似曾相识的女孩，重复以往男孩寻找出路的话。梦境破碎时她又恢复自身，看见男孩在对面微笑。\",\"turn\":\"梦中身份互换将男孩与她的自我关联推到前景，但并未解释机制。\"},\"c260\":{\"key\":\"c260\",\"title\":\"热闹的合租房\",\"kind\":\"main\",\"start\":1020,\"end\":1023,\"summary\":\"方莜莜回家，扶起从床上跌落又忘记梦境的苏雨晴，分享公司庆祝会带回的零食和奶茶，并温柔替她梳头、谈长发愿望。林夕晨衣着略乱地回来，只说去工作；随后胡玉牛、张思凡和孙昊也归来。合租屋恢复笑声，苏雨晴终于重新感到安心。\",\"turn\":\"照护与陪伴安抚情绪，林夕晨外出工作的具体内容仍未交代。\"},\"c261\":{\"key\":\"c261\",\"title\":\"黑檀木梳\",\"kind\":\"main\",\"start\":1024,\"end\":1026,\"summary\":\"苏雨晴首次核查大量炒货保质期，才知同一区域的徽记促销员也应分担，却一直未帮忙；她仍选择认真做完自己的工作。下班寻不到胡玉牛，便按方莜莜推荐去古风梳子店。汉服老板娘介绍材质，并针对她的睡眠和体弱情况推荐黑檀木梳，苏雨晴准备在百元左右挑选。\",\"turn\":\"梳子从日常工具成为改善自我生活的消费选择；同事分工失衡暂未抗争。\"},\"c262\":{\"key\":\"c262\",\"title\":\"送给自己的礼物\",\"kind\":\"main\",\"start\":1027,\"end\":1030,\"summary\":\"苏雨晴花一百二十元买下双面青莲纹的半圆黑檀木梳，获赠同材质木镜，视它为提醒自己保持本色、善待自己的礼物。回家后见林夕晨替宠物洗澡，又读到冉空城问“你是苏雨晴吗”的短信，最终删去不回。随后回想同桌拍照留念的往事，重温彼此希望美好时刻停留的心情。\",\"turn\":\"她开始主动善待自己，却仍回避旧友伸来的联系。\"},\"c263\":{\"key\":\"c263\",\"title\":\"促销商品\",\"kind\":\"main\",\"start\":1031,\"end\":1034,\"summary\":\"王海峰让徽记促销员分担检查，苏雨晴终于查完保质期，午睡后被安排到电梯口推销清仓商品。她怕受关注，始终不敢吆喝，旺旺促销员示范也没令她放开。王海峰亲自招来顾客再交给她应答，她虽紧张，仍认真反复解答老人们的问题，逐渐进入工作状态。\",\"turn\":\"同事分工问题得到介入；被迫面对人群成为社交锻炼。\"},\"c264\":{\"key\":\"c264\",\"title\":\"被搭讪了\",\"kind\":\"main\",\"start\":1035,\"end\":1037,\"summary\":\"清仓商品卖掉半车，苏雨晴留两包进口巧克力准备买回家，想到从优裕家庭到独立谋生后的节俭变化。防损部年轻男员工借挑货与她搭话，随后谎称新规定要求登记所有员工信息。她虽察觉可能是搭讪，却因对其岗位有所顾忌，仍交出姓名和电话号码。\",\"turn\":\"工作身份被周超借作接近渠道，陌生人的追求开始进入日常。\"},\"c265\":{\"key\":\"c265\",\"title\":\"短信聊天\",\"kind\":\"main\",\"start\":1038,\"end\":1041,\"summary\":\"周六众人在郊外集装箱房赏雨，猫狗燕子相伴，张思凡与孙昊畅想有钱后在乡间共同生活。胡玉牛缺席，室友猜测其恋情与身体选择。苏雨晴收到昨天男员工短信；对方坦承骗取号码，自称周超，用可乐冰淇淋、占卜等话题热情聊天，她因无聊逐渐回应。\",\"turn\":\"周超接近成功；集体对胡玉牛的判断仍建立在猜测上。\"},\"c266\":{\"key\":\"c266\",\"title\":\"哈士奇到底有多二\",\"kind\":\"main\",\"start\":1042,\"end\":1045,\"summary\":\"雨停后大家到河边，看哈士奇抓鱼却叼回石头，发现一只大草龟载着曲奇和咖啡游水；苏雨晴吹箫，心情趋于平静。周超连续邀请她去寺院、步行街，最后用新开的猫咖啡馆打动她。她怕单独赴约出现告白尴尬，提出带朋友同行，对方接受。\",\"turn\":\"好奇与谨慎同时起作用，约会以携带朋友的条件成立。\"},\"c267\":{\"key\":\"c267\",\"title\":\"和林夕晨一起去\",\"kind\":\"main\",\"start\":1046,\"end\":1049,\"summary\":\"张思凡和方莜莜都不愿陪苏雨晴赴约，林夕晨则默默答应。听见周超可能转而追林夕晨的玩笑，她立刻紧张，室友察觉其占有欲。郊外晚餐后哈士奇阿灰随猎人主人老王回家；翌日苏雨晴七点才醒，匆匆与林夕晨乘公交赴约，带着对迟到的担忧。\",\"turn\":\"林夕晨成为陪伴者；苏雨晴对她的感情通过吃醋间接显露。\"},\"c268\":{\"key\":\"c268\",\"title\":\"可乐味的冰淇淋\",\"kind\":\"main\",\"start\":1050,\"end\":1053,\"summary\":\"公交堵车使苏雨晴与林夕晨迟到，周超耐心等候并体贴招待。叙述补充他热爱追求、喜新厌旧，却通常在关系结束后才寻找下一位对象。三人买可乐味冰淇淋，周超的从容渐渐缓解苏雨晴紧张；她同时想到父母期待与自己的负罪感，随后同意去占卜店。\",\"turn\":\"苏雨晴对周超的戒备有所减轻，尚未形成恋爱承诺。\"},\"c269\":{\"key\":\"c269\",\"title\":\"占卜（上）\",\"kind\":\"main\",\"start\":1054,\"end\":1057,\"summary\":\"三人进入以船舱、六芒阵和灯光营造神秘气氛的占卜店。苏雨晴一面识破舞台机关，一面期待对未来的安慰。黑袍占卜师说她前路虽有迷雾仍可通行，困难在受束缚的心而非不完整的身体，钥匙在她自己的天空。她震惊于话语仿佛洞悉身份，却追问不到具体答案。\",\"turn\":\"“天空中的钥匙”成为解开心结的主题伏笔，非已验证的预言。\"},\"c270\":{\"key\":\"c270\",\"title\":\"占卜（下）\",\"kind\":\"main\",\"start\":1058,\"end\":1061,\"summary\":\"苏雨晴获赠星空水晶球；林夕晨沉默占卜，得到血色火焰、尸骸与鬼脸的立体卡片；周超问两人谁能成为女友，收下八音盒和正反写“你好美”“想得美”的双面卡。午休后揭示黑袍人其实是莫空，老店主正式让他主持占卜工作，苏雨晴等人尚不知道。\",\"turn\":\"读者得知熟人身份；三份赠物各自留下人物命运的暗示。\"},\"c271\":{\"key\":\"c271\",\"title\":\"深夜的星空\",\"kind\":\"main\",\"start\":1062,\"end\":1064,\"summary\":\"莫空深夜在天台观察众生、回忆技术与时代变化，仍珍视想象力和保持内在本色。他生于1982年，现把占卜工作当人生旅程的一段；曲奇和咖啡每晚来陪伴。困倦中他仿佛见到佩脚铃的少女从星空走来，指触额头后沉沉睡去，现实与幻觉界限未明。\",\"turn\":\"旁观世界的莫空也被纳入神秘线索；曲奇的双重家庭生活得到交代。\"},\"c272\":{\"key\":\"c272\",\"title\":\"不能说话的少女\",\"kind\":\"main\",\"start\":1065,\"end\":1068,\"summary\":\"莫空醒后赶去占卜店，向年轻女房东提醒股市风险，回忆自己曾放弃家主位置以选择自由。开店时一位无法说话的少女静坐门口，眼神异样，最终递给他一张绘有狐狸与山水的精薄木卡后离去。他感到她与昨夜幻见少女相似，却不能解释来意。\",\"turn\":\"狐狸卡由神秘来客送到莫空手中，身份与含义均待后文。\"},\"c273\":{\"key\":\"c273\",\"title\":\"付账\",\"kind\":\"main\",\"start\":1069,\"end\":1071,\"summary\":\"周末约会平静结束后，周一超市忙碌，陈淑艳照顾疲惫的苏雨晴，周超解释自己是便衣暗保并邀请午餐。苏雨晴不愿欠人情，也珍惜为身体改变所存的钱，选择价廉的沙县小吃；周超要一并付账时，她坚持各付各的，努力维持清楚的相处界限。\",\"turn\":\"交往持续但付账边界明确，苏雨晴的节俭、独立与犹豫同时显现。\"},\"c274\":{\"key\":\"c274\",\"title\":\"划破手指\",\"kind\":\"main\",\"start\":1072,\"end\":1075,\"summary\":\"苏雨晴坚持午餐各自付账，周超最终尊重。回超市处理破包垃圾时，她遇见同样常被派脏累活的夏仕尼；周超负责监督，主动帮她拆包，还叫来废品老板加快处理。她连续开启易拉罐划伤手指，周超急忙拿消毒用品与创可贴，照顾让二人的距离缩短。\",\"turn\":\"拒绝经济依赖的边界成立，实际照护却令新关系更亲近。\"},\"c275\":{\"key\":\"c275\",\"title\":\"准备迎接大人物的小城市\",\"kind\":\"main\",\"start\":1076,\"end\":1079,\"summary\":\"小城市为迎接高级官员及外国考察团，整饰市容、关闭店铺、增加身份证盘查和通行收费。占卜店停业，莫空重回写作生活；他决定外出，因郊区公交骤减只能坐出租车，被加收高价仍接受。途中看到店主、居民与管理人员的冲突，城市发展愿景与普通人的生活损失并置。\",\"turn\":\"公共事件中断工作并限制出行，促成莫空郊游及后续假期。\"},\"c276\":{\"key\":\"c276\",\"title\":\"回忆里的老仆人\",\"kind\":\"main\",\"start\":1080,\"end\":1083,\"summary\":\"莫空赴郊外海边，村民兄弟互动触发少年家族回忆：父死母失踪后，奶奶被逼自尽、如祖父般的老仆遭毒害；他以派系斗争报复，眼看能继家主却选择离开。回到当下，他绕熟悉森林路来到别墅附近准备露营，远望体弱大小姐在女仆、管家陪同下乘帆船。\",\"turn\":\"莫空的克制与自由选择获得悲剧背景，别墅线再次接入主叙事。\"},\"c277\":{\"key\":\"c277\",\"title\":\"莫空和大小姐\",\"kind\":\"main\",\"start\":1084,\"end\":1087,\"summary\":\"莫空海边夜钓时，大小姐谈重复人生与死亡，自称来自未来、将由另一个自己接替身体；影响未来的信会被抹除，他便建议留下信物。她归家发高烧，要求女仆水水称自己雯雯，并托其照顾未来变稚嫩的自己。水水坚持陪伴，女仆长落姨与厨师一起照料。\",\"turn\":\"未来来客与身体接替成为核心谜团，目前只是角色陈述与异常症状。\"},\"c278\":{\"key\":\"c278\",\"title\":\"苏雨晴和创可贴\",\"kind\":\"main\",\"start\":1088,\"end\":1091,\"summary\":\"超市将于24日停业，城中顾客开始储备物资。苏雨晴两天前的指伤仍包着创可贴，周超继续关心并常来聊天；防损部员工指导起哄撮合，让她难以回应。王海峰及时插入玩笑解围，强调她太小，不存在自己的追求意图。周超看见她自在拌嘴的一面，愈发觉得可爱。\",\"turn\":\"照顾累积熟悉感，旁人把普通交往推向恋爱解读。\"},\"c279\":{\"key\":\"c279\",\"title\":\"快开学了，你还会来吗？\",\"kind\":\"main\",\"start\":1092,\"end\":1095,\"summary\":\"独自午餐时，冉空城发短信问快开学是否回来，并追问离家出走传言。苏雨晴感到被挂念的温暖，也怕失去唯一旧友，谎称自己已转去外地学校。耐不住连续来电接通后，冉空城热情邀见面、同考大学，提到女班长曾护她；她却故作冷淡让他忘记自己。\",\"turn\":\"她主动切断关心以保护秘密，这种舍弃并非旧友拒绝她。\"},\"c280\":{\"key\":\"c280\",\"title\":\"苏雨晴和平凡的少年\",\"kind\":\"main\",\"start\":1096,\"end\":1099,\"summary\":\"苏雨晴挂断冉空城、关机哭泣，又用工作压住情绪。胡玉牛来告知回乡几日，她劝他放弃女性化道路，遭冷眼后才反省：自己坚持相同愿望，却要求朋友妥协。下班绕路经过中学，看见独自练羽毛球的平凡少年，想起自己曾为免冉空城受嘲笑而拒绝陪伴。\",\"turn\":\"对胡玉牛的劝说适得其反；孤独少年使她看见自己拒绝帮助的旧模式。\"},\"c281\":{\"key\":\"c281\",\"title\":\"胡玉牛村里的家（上）\",\"kind\":\"main\",\"start\":1100,\"end\":1103,\"summary\":\"父母多次催回家，胡玉牛仍怕秘密暴露，先在无名面馆逗留。食客抱怨城市封店，老板额外加面的小善意却让他重新看见温暖。傍晚河堤遇莫空，二人分享烤蟹、小黄鱼与啤酒，保持不追问隐私的分寸。谈及家族压力时，莫空说责任先要值得自己承担。\",\"turn\":\"与莫空的无压迫交谈缓冲焦虑，为直面家庭创造心理空间。\"},\"c282\":{\"key\":\"c282\",\"title\":\"胡玉牛村里的家（下）\",\"kind\":\"main\",\"start\":1104,\"end\":1107,\"summary\":\"胡玉牛与莫空饮酒后梦见自己孤独悬在深海，醒来独自穿越幽暗山间小路，竟再度恐惧。归家时母亲热情关心他消瘦，父亲则察觉肌肉与体毛改变，责备缺乏锻炼；他谎称文员工作忙、服从公司形象要求。父亲意外没有继续动手干预，承认他该有自己的想法。\",\"turn\":\"家带来安全感又威胁秘密；父亲短暂让步并未触及核心身份问题。\"},\"c283\":{\"key\":\"c283\",\"title\":\"快点找个女朋友\",\"kind\":\"main\",\"start\":1108,\"end\":1111,\"summary\":\"在家安睡后，胡玉牛看见荒废道馆与旧武术用品，理解父亲怀念家族昔日兴盛。父亲让他演醉拳，他借内心苦楚超常表现，虽耐力不足仍获肯定。母亲清晨精心做海鲜丸子，父母接着催他找女友、结婚，并把身体虚弱误解为需要进补，亲情和男性期待再次重叠。\",\"turn\":\"他感动于照料却必须隐瞒愿望；父母婚恋期待为柳韵线增加压力。\"},\"c284\":{\"key\":\"c284\",\"title\":\"妹子的声音！\",\"kind\":\"main\",\"start\":1112,\"end\":1115,\"summary\":\"孙昊临近开学离城，张思凡送站后发现方莜莜正与网友安念在游戏里逃避大公会追杀：两人抢到稀有麻痹戒指，而追兵恰属自己所在公会。她想协助逃脱，误打开语音使女声暴露，方莜莜急忙关麦；操作中断导致两人角色死亡，幸好戒指仍在。\",\"turn\":\"网友性别呈现危机打开新亲密关系，同时孙昊结束本次同住。\"},\"c285\":{\"key\":\"c285\",\"title\":\"安念的追问\",\"kind\":\"main\",\"start\":1116,\"end\":1120,\"summary\":\"安念追问声音，方莜莜起初否认，终于因渴望在网上以女性身份相处而开麦。二人从紧张变回熟悉，她婉拒照片请求与亲昵称呼。安念承诺分她一半戒指收入，张思凡转达经理出价三千元被拒；聊及女友时，安念坦言自己虽已上大学却未恋爱，双方气氛开始暧昧。\",\"turn\":\"方莜莜主动接受女性网络身份，但真实情况尚未向安念说明。\"},\"c286\":{\"key\":\"c286\",\"title\":\"给林夕晨当模特\",\"kind\":\"main\",\"start\":1121,\"end\":1124,\"summary\":\"封店及外来人口清退使城市空荡，合租者靠本地二房东暂避影响；林夕晨挂在张思凡暂住证下，丢失身份证的苏雨晴最缺保障。林夕晨邀她外出写生，途中主动牵手。到公园后山土丘，她让苏雨晴面向天空做模特；苏沉浸被专注注视的幸福，却怕表白会失去朋友。\",\"turn\":\"含蓄的双向亲近开始明确可见，苏仍以朋友解释林的主动。\"},\"c287\":{\"key\":\"c287\",\"title\":\"林夕晨的拥抱\",\"kind\":\"main\",\"start\":1125,\"end\":1128,\"summary\":\"林夕晨认真画成苏雨晴的肖像，又坚持请她给自己作画。苏担心水平不够，仍超常完成素描，并一度看见她温柔含笑。两人互赠各自画作后继续看城市；松子砸疼苏的头，林忽然将她拥入怀中抚慰。直接的关心令苏害羞，也让她对这段感情更难放下。\",\"turn\":\"互赠肖像和拥抱成为关系转折，尚无正式口头告白。\"},\"c288\":{\"key\":\"c288\",\"title\":\"小混混们的善良\",\"kind\":\"main\",\"start\":1129,\"end\":1132,\"summary\":\"莫空逛待拆旧小区，看见一群年轻混混因狭隘的民族情绪弃玩游戏王、改学围棋，想起自己曾引导类似青年读书、学艺。河边少女失足落水，为首的狗哥立即跳水，众人合力救起她；少女起初仍害怕他们。莫空解释救援经过时，胡玉牛冲来误以为有人欺负她。\",\"turn\":\"外貌标签被实际善行打破，胡玉牛的二分判断即将受考验。\"},\"c289\":{\"key\":\"c289\",\"title\":\"再相遇\",\"kind\":\"main\",\"start\":1133,\"end\":1136,\"summary\":\"莫空及时拦住胡玉牛，说明柳韵是被混混们救起。她亲近胡玉牛并继续自称未婚妻，狗头帮主动结交，帮主黄枸逐一介绍金毛狮王、剑鱼、凤凰、青蛙、鼠标、彩虹和赤脚大仙等成员及特长。胡玉牛承认对方有善意，礼貌交友，随后抱湿衣的柳韵回家。\",\"turn\":\"误会解除，胡玉牛与狗头帮建立联系，并再度与柳韵单独相处。\"},\"c290\":{\"key\":\"c290\",\"title\":\"闺房\",\"kind\":\"main\",\"start\":1137,\"end\":1140,\"summary\":\"胡玉牛抱柳韵走回家，虽累也想维持可靠形象。她邀请他进闺房，他从白熊玩偶与写满爱语的纸张看到她持续的心意，开始真心想以男友身份陪伴，却仍不肯面对身体选择。柳韵换好衣物后说一个月考验已过，重申认真爱情并主动亲吻，让他无法再假装未被打动。\",\"turn\":\"亲密关系转向需要明确答复，秘密却仍被拖延。\"},\"c291\":{\"key\":\"c291\",\"title\":\"我……喜欢你\",\"kind\":\"main\",\"start\":1141,\"end\":1144,\"summary\":\"柳韵要求胡玉牛正视自己，明确说若他不喜欢便不强求。胡玉牛终于承认喜欢她，却只答应以后再解释此前拒绝的苦衷。柳韵快乐地要做午餐，并让他替自己扎头发；他关心她是否会被厨房器具弄伤。这份平凡的关怀令短暂幸福更真切，也掩住了尚未解决的冲突。\",\"turn\":\"双方明确彼此喜欢，恋爱成立，但知情程度不对等。\"},\"c292\":{\"key\":\"c292\",\"title\":\"柳韵的黑暗料理\",\"kind\":\"main\",\"start\":1145,\"end\":1149,\"summary\":\"柳韵精心尝试的蝴蝶面难以下咽，胡玉牛先顾及她的心情，待她自己尝过才改为教做面点。两人共同做爱心形状的面，失败料理化成合作的温馨午餐。胡玉牛称她是自己的救赎并说爱她，仍把是否停止身体改变的问题留给以后，幸福和逃避同时加深。\",\"turn\":\"共同生活的想象初步成形，核心抉择依然悬置。\"},\"c293\":{\"key\":\"c293\",\"title\":\"趴在大腿上睡着了\",\"kind\":\"main\",\"start\":1150,\"end\":1152,\"summary\":\"写生归家后，方莜莜与安念语聊，张思凡用游戏里的不同账号调节男女声身份。苏雨晴和林夕晨看动画，渴望永远支持自己的伴侣，靠着她睡去；林轻放她枕在腿上、替她理发。苏梦见两人乘巴士、火车、飞机一直同行，被张思凡逗醒时发现林腿麻仍无怨言。\",\"turn\":\"无言照护进一步加深依恋，同行之梦直接呈现她的亲密愿望。\"},\"c294\":{\"key\":\"c294\",\"title\":\"蹭胸\",\"kind\":\"main\",\"start\":1153,\"end\":1156,\"summary\":\"张思凡做牛排、鹅肝，方莜莜做糕点汤，室友一起吃西餐。张把红酒说成黑莓汁，苏雨晴识破后为逞强接连饮酒而醉；方莜莜责怪玩笑过火并劝止。醉中的苏直接说最喜欢林夕晨、主动寻求拥抱与亲昵，最后被妥善安置在沙发，梦呓请求她不要离开。\",\"turn\":\"酒后直接表达依恋，但不能把醉态当双方清醒确认的恋爱承诺。\"},\"c295\":{\"key\":\"c295\",\"title\":\"失去了蛋蛋的人生\",\"kind\":\"main\",\"start\":1157,\"end\":1160,\"summary\":\"曾带人侵害柳韵的混混头目住院，回忆被胡玉牛重击后因逞强拖延就医，最终必须切除坏死的生殖器官。他不想失去原有男性生活，深感恐惧羞耻，并怨恨施伤者；父母照料又寻人无果。母亲改口小遥使他愤怒，父母暂仍叫小天，孩子否认哭泣却止不住眼泪。\",\"turn\":\"伤害造成长久创伤并埋下报复支线，原有生活和身份均遭撼动。\"},\"c296\":{\"key\":\"c296\",\"title\":\"天语遥\",\"kind\":\"main\",\"start\":1161,\"end\":1164,\"summary\":\"父母提议今后进行女性化手术，天语遥先激烈拒绝，后在心理辅导中减少冲突，却依然痛苦。父亲办休学和新身份证，将名字改成天语遥；母亲梳头、设想乖巧女儿。父母一面说支持选择，一面认定女性生活更好。天语遥沉默接受新证件，心中仍以报复胡玉牛维系情绪。\",\"turn\":\"外在转变伴随家庭推动，沉默不等于原本身份愿望得到尊重。\"},\"c297\":{\"key\":\"c297\",\"title\":\"开学季\",\"kind\":\"main\",\"start\":1165,\"end\":1168,\"summary\":\"会议到八月底结束，小城市和超市恢复运作。九月开学清晨，苏雨晴穿父母买的猫耳卫衣上班，路过中学看家长学生聚集，强烈怀念校园与冉空城。她渴望重新读书，却认为经济和身体愿望难以兼顾；被新生错认作学姐后，她温柔道别，也像在告别已失去的道路。\",\"turn\":\"停业结束，生活恢复；教育机会的损失成为她自立道路上的清晰代价。\"},\"c298\":{\"key\":\"c298\",\"title\":\"刁难\",\"kind\":\"main\",\"start\":1169,\"end\":1172,\"summary\":\"王海峰延长休假，部门由翁锡芽负责。苏雨晴被派去领软标，途中看见陈淑艳以与老梅吃早餐回避迟到责难。防损部一名胖女员工从开门、说明流程到借笔、字迹都刻薄挑刺，还把失窃怪到她们部门；苏始终礼貌完成登记拿走软标，出来才松口气。\",\"turn\":\"缺少熟悉主管庇护时，小职权与部门敌意直接压向新人。\"},\"c299\":{\"key\":\"c299\",\"title\":\"刻薄\",\"kind\":\"main\",\"start\":1173,\"end\":1176,\"summary\":\"翁锡芽劝苏雨晴别与防损部冲突，派她去酒仓协助盘点。她看到胡玉牛在后仓睡觉，得知其整个假期没回合租屋。陈淑艳只给她轻松扫码工作；刻薄防损女员工来核对时不断讥讽，陈当面反击，酒柜促销员调停，拖延一小时才结束，让苏更厌倦职场争斗。\",\"turn\":\"对不同同事的亲疏更清晰；胡玉牛与合租群体继续脱离。\"},\"c300\":{\"key\":\"c300\",\"title\":\"小弟们的看望\",\"kind\":\"main\",\"start\":1177,\"end\":1180,\"summary\":\"出院休学后的天语遥沉迷网络，面对父亲给出的两种激素方向仍痛苦难决。旧部带花果篮探望，狗头帮黄枸也携蛇酒为早前地盘冲突赔礼；众人误以为伤势已好，谈女人与报仇反让其更难堪。临别时他强撑旧口吻自称天冲云，明确揭示天语遥改名前的姓名。\",\"turn\":\"旧友关心与不知情话语相互冲突，黄枸成为两条混混关系线的交点。\"},\"c301\":{\"key\":\"c301\",\"title\":\"自残\",\"kind\":\"main\",\"start\":1181,\"end\":1184,\"summary\":\"访客离开后天语遥因被迫选择与失去旧身份而崩溃，自伤后失去意识，父母及时回家呼救送医。昏迷中他梦见狐耳少女温柔引导自己离开黑暗，醒来才知仍活着。父亲承认不该逼迫，愿改回名字并寻找治疗；天语遥疲惫拒绝折腾，说就这样，创伤尚未消失。\",\"turn\":\"自伤危机获救，父亲反思控制；人物的妥协与生存愿望仍需继续辨别。\"},\"c302\":{\"key\":\"c302\",\"title\":\"选择\",\"kind\":\"main\",\"start\":1185,\"end\":1188,\"summary\":\"获救后的天语遥清醒表示选择成为听话女儿，请父母叫自己小遥，并要求父亲多陪家人、不要再为昂贵治疗拼命挣钱。她承诺不再自伤，仍拒绝回校；母亲喂巧克力、谈小时给她穿裙，父亲买清淡饭和她喜欢的零食，也买来女士香烟。家庭开始重新对话，但接受新身份不等于创伤消失。\",\"turn\":\"父母开始尊重孩子意愿；小遥主动选择新的家庭身份，痛苦仍待修复。\"},\"c303\":{\"key\":\"c303\",\"title\":\"是他们吗？\",\"kind\":\"main\",\"start\":1189,\"end\":1192,\"summary\":\"苏雨晴担心整日昏睡、不吃饭的胡玉牛，劝他不适就请假。她在柜台打盹，梦见父母来无条件接纳自己，醒后似见二人背影却被陈淑艳打断。章末父母真实对话证实曾来探望：父亲决定尊重孩子选择、帮助她并等她自愿回家，母亲建议准备女孩礼物。苏本人尚不知道这场态度转变。\",\"turn\":\"梦中团聚未现实发生，但父母现实态度已转向接纳，苏仍孤独猜测。\"},\"c304\":{\"key\":\"c304\",\"title\":\"接柳韵放学\",\"kind\":\"main\",\"start\":1193,\"end\":1196,\"summary\":\"夏仕尼提醒后胡玉牛才惊醒，发现睡过班且已迟到接柳韵的时间。他打车到小城市第一高中，故意不回催促短信以制造惊喜，放学时迎上并抱起她。柳韵提父母不在家，胡只提议吃饭；两人在沙县小吃分享饮料与食物。胡异常疲倦的原因未解，也继续隐瞒自身变化。\",\"turn\":\"恋爱进入接送和共餐日常，秘密与异常困倦仍被搁置。\"},\"c305\":{\"key\":\"c305\",\"title\":\"亲亲我我\",\"kind\":\"main\",\"start\":1197,\"end\":1200,\"summary\":\"胡玉牛喂柳韵馄饨，答应亲手做小笼包。店内中年妇女嘲讽他们的亲昵，柳韵反击，胡劝她不要耗在争吵中，对方最终离开。二人沿河散步，柳跳起小时候学过的舞，又因心疼胡而放弃让他表演劈砖。她憧憬浪漫长久的爱情，他享受被爱却仍犹豫如何坦白秘密。\",\"turn\":\"两人的体贴与性格差异更鲜明，公开亲密也招来外部目光。\"},\"c306\":{\"key\":\"c306\",\"title\":\"在我这里……过夜吧\",\"kind\":\"main\",\"start\":1201,\"end\":1204,\"summary\":\"柳韵记起作业后带胡玉牛回家，两人用贡丸馅合作做小笼包，吃完已近十点。胡帮她抄写语文作业，回忆小时被罚抄家规练出的速度，见她手酸又帮忙揉按。共同料理和学习让柳韵更不舍分别；胡准备返回合租屋时，她主动邀请他留下过夜。\",\"turn\":\"家庭式相处强化依恋，过夜邀请使胡面对隐瞒与责任的顾虑。\"},\"c307\":{\"key\":\"c307\",\"title\":\"钻进怀里的小猫咪\",\"kind\":\"main\",\"start\":1205,\"end\":1208,\"summary\":\"胡玉牛怕未坦白就把关系推进太深，起初拒绝留下，最终因柳韵独自在家害怕而睡客厅。他梦见说出秘密后获得支持，但现实并未坦白；清晨醒来发现柳韵已依偎在沙发怀里，昨夜没有性行为。二人起身吃早餐，她换上校服准备上学，胡此前的异常困倦暂时消失。\",\"turn\":\"梦境表达坦白愿望，现实的秘密继续延后；日常亲密与依赖加深。\"},\"c308\":{\"key\":\"c308\",\"title\":\"送柳韵上学\",\"kind\":\"main\",\"start\":1209,\"end\":1212,\"summary\":\"柳韵带胡玉牛走连接超市后山与学校后山的小路，看野花而不摘，畅想有菜地禽畜的山居生活。他背她沿山路前行，宁肯上班迟到也坚持送到校门，依恋越发强烈。两人约周六去流庆寺求签、购买刻双方名字的爱情锁；到校后门胡帮助她翻墙进校，再匆忙跑去上班。\",\"turn\":\"未来共同生活的想象与寺庙约定建立，实际赴约及坦白仍未发生。\"},\"c309\":{\"key\":\"c309\",\"title\":\"吕布闪卡\",\"kind\":\"main\",\"start\":1213,\"end\":1215,\"summary\":\"教师节当天学校半日放假，超市因上级检查让未成年和证件不齐员工提前下班，苏雨晴获得午后闲暇。她仍收到冉空城问候却不回复，回忆他与女班长给予的不同保护。走到学校小店买童年零食时抽出稀有吕布闪卡，引来学生围观；一名男生出五十元求购，交易尚未决定。\",\"turn\":\"旧友与求学生活再度进入当下，一张卡片触发新的偶遇。\"},\"c310\":{\"key\":\"c310\",\"title\":\"彩色小鸡\",\"kind\":\"main\",\"start\":1216,\"end\":1219,\"summary\":\"求购吕布闪卡的出价从五十涨到两百，一位文澜学院腼腆高中男生认真求卡，苏雨晴却免费送给他后跑开。她路过学院再次向往高中生活，走进步行街，想起尚未把玩的星空球。看见染色雏鸡，她花一元买下红色小鸡，取名朱雀；叙述先提示这类小鸡生命脆弱，她本人尚不知情。\",\"turn\":\"卡片带来无偿善意的新联系，朱雀进入苏的照护生活。\"},\"c311\":{\"key\":\"c311\",\"title\":\"病怏怏的大小姐\",\"kind\":\"main\",\"start\":1220,\"end\":1222,\"summary\":\"苏雨晴在步行街喂朱雀，羡慕橱窗中的昂贵人偶，也认出愈发虚弱的海边别墅大小姐。暴雨将至，其他人避雨，大小姐却独坐树下说终于来了，短暂闭眼。雷暴忽来忽止，她醒后对地点、电子钟和自己的身体震惊，举止已明显不同；苏旁观感到困惑，接替身份的机制尚未明说。\",\"turn\":\"大小姐预告的转变疑似到来；叙述展示行为突变而未直接解释时间机制。\"},\"c312\":{\"key\":\"c312\",\"title\":\"在步行街巧遇张思凡\",\"kind\":\"main\",\"start\":1223,\"end\":1226,\"summary\":\"相貌近似大小姐的年轻女人买来等身毛绒熊，将仍迷惘的她抱上跑车离开；苏雨晴感到时间似被截断，黑蝶又重新出现。她偶遇同样因检查提前下班的张思凡，陪她选孙昊生日礼物。张被游戏厅吸引，双人射击几乎独自通关，苏转玩抓娃娃；玩兴中张终于想到送模型手枪。\",\"turn\":\"大小姐离开，礼物支线转入模型枪；张对孙的重视和贪玩消费习惯显露。\"},\"c313\":{\"key\":\"c313\",\"title\":\"林夕晨寄信\",\"kind\":\"main\",\"start\":1227,\"end\":1230,\"summary\":\"张思凡买下一百元毛瑟观赏模型枪并附贺卡寄给孙昊，在邮局巧遇寄钱家书的林夕晨。林已一年多未回偏远山村，家人不知她的女性生活；她仍牵挂父母，却刻意不写回址，怕极度重男轻女的父亲发现。父亲曾粗暴对待几个姐姐。张追问未来打算，也被苏指出自己同样回避家里问题。\",\"turn\":\"林与原生家庭的经济牵挂和身份隔阂被揭明；张寄出了生日礼物。\"},\"c314\":{\"key\":\"c314\",\"title\":\"陶艺\",\"kind\":\"main\",\"start\":1231,\"end\":1233,\"summary\":\"天语遥伤未全愈便回家，把自己裹在宽大外套中，减少与旧日兄弟联系却又舍不得彻底断开。网上寻找独处能做的事时，她被制陶广告启发，想起小时随爷爷做糖人的爱好，考虑学习可自主塑形的陶艺，甚至日后独立谋生。母亲邀她去游乐园，她首次答应出门，并问哪里能买材料。\",\"turn\":\"旧社交圈逐渐疏离，陶艺为恢复主动性和新的生活道路提供起点。\"},\"c315\":{\"key\":\"c315\",\"title\":\"当我们老去\",\"kind\":\"main\",\"start\":1234,\"end\":1237,\"summary\":\"苏雨晴、张思凡与林夕晨沿街听老人争论时代、子孙和入学，苏因老去而焦虑，担心未来形象不再符合愿望。张以未经证实的短寿说法回应，又提醒人会因牵挂而不愿死去；这只能视为角色认知。三人继续买菜，合租者各尽所能补充食材的默契展现共同生活的支持。\",\"turn\":\"苏的青春与死亡焦虑显露，张的看似轻佻回应内含对牵挂的理解。\"},\"c316\":{\"key\":\"c316\",\"title\":\"抢猫粮的小红鸡\",\"kind\":\"main\",\"start\":1238,\"end\":1240,\"summary\":\"工作日渐忙碌，合租采购改为各人零散补充，胡玉牛常不在家，大家感到隔阂。苏雨晴购买廉价火龙果分享，体现独立后学会节俭及珍惜小幸福；胡难得笑着归来主动做饭，却以加班解释晚间外出。朱雀被介绍给曲奇和咖啡，大胆抢猫粮，温顺的曲奇忍让后向苏求安慰。\",\"turn\":\"胡的恋爱改变家庭出勤，伙伴仍关心；朱雀开始融入人与动物的小家庭。\"},\"c317\":{\"key\":\"c317\",\"title\":\"爱的便当\",\"kind\":\"main\",\"start\":1241,\"end\":1243,\"summary\":\"胡玉牛装好便当六点出门，苏雨晴留下收拾并给加班的方莜莜留饭。林夕晨首次主动帮她整理和洗碗，说要一起做，随后从背后拥抱怕冷的苏，两人不善言说的依恋再次加深。胡冒冷雨去第一高中，等数学补习的柳韵近一小时；他把保温饭盒护在怀里，盼她放学。\",\"turn\":\"苏林以共同家务与拥抱表达关爱；胡持续把恋情置于日常优先位置。\"},\"c318\":{\"key\":\"c318\",\"title\":\"喂你吃\",\"kind\":\"main\",\"start\":1244,\"end\":1247,\"summary\":\"柳韵数学补习测验过关，欢快扑进等候的胡玉牛怀中；胡先前因害羞对保安谎称接妹妹，只好故作兄长。离校后他撑伞抱她到公园亭子分享亲手做的便当，二人轮流照顾进食。柳说明父母忙筹电脑配件店、近日晚归，谈父亲像孩子般亲近；胡由此看见与自己严父不同的家庭相处。\",\"turn\":\"数学补习阶段过关，双方用体贴与家庭分享深化关系；父母开店为真实计划。\"},\"c319\":{\"key\":\"c319\",\"title\":\"垃圾食品的副作用\",\"kind\":\"main\",\"start\":1248,\"end\":1250,\"summary\":\"朱雀与曲奇、咖啡同处，猫让出饼干，小鼠帮咬成小块，动物间形成照护。苏雨晴夜里受空城噩梦与胡晚归洗澡声影响，继而腹痛腹泻，猜是白天零食所致但未就医确诊。她忆及早产、多病和童年电梯受困，担忧身体妨碍自由，仍不愿放弃选择；折腾后才短暂睡稳，次晨腿酸。\",\"turn\":\"身体脆弱、童年恐惧与梦想代价交织；动物照护与苏孤独噩梦形成并置。\"},\"c320\":{\"key\":\"c320\",\"title\":\"天语遥和游乐园\",\"kind\":\"main\",\"start\":1251,\"end\":1254,\"summary\":\"连续秋雨中天语遥再度冒出自毁念头，被母亲邀约打断，仍决定去人少的游乐园。父亲因出差缺席，实际努力工作是为她未来生活预留保障。出租车司机对其性别称呼变化令天心绪复杂，她既躲开母亲拥抱又渴望理解。到园后高危露天项目停开，她选择射气球，母亲买币陪同。\",\"turn\":\"生存危机尚未解除；首次母女外出成为重新接触世界的尝试。\"},\"c321\":{\"key\":\"c321\",\"title\":\"天语遥和小白兔\",\"kind\":\"main\",\"start\":1255,\"end\":1257,\"summary\":\"天语遥借射气球释放压抑情绪，花五十元清空靶面，赢得MP3并难得获得母亲赞赏。母女在中心大厅买软陶材料、工具、书及教学碟，让她可在家自学。逛花鸟市场时，她想起从前投喂并随她行动的大黑狼犬，担心旧部是否继续照顾；停在兔笼前出神，母亲再次询问要不要买。\",\"turn\":\"陶艺计划获得现实资源；旧日温柔面与动物牵挂被揭示，宠物购买尚待决定。\"},\"c322\":{\"key\":\"c322\",\"title\":\"天语遥和女装\",\"kind\":\"main\",\"start\":1258,\"end\":1260,\"summary\":\"母亲替天语遥买下黑白兔，二人按方格饼干般毛色给它取名饼干，又买盆栽。逛服装层时天自觉昔日七彩造型幼稚，对店主称自己为女儿感受复杂；母亲买齐四季女装邀她试穿。天口头拒绝却觉内心动摇，原文将身体变化与心理联系只是角色困惑，不能当作必然规律。\",\"turn\":\"新宠物落定姓名，服装使身份与自主选择矛盾进一步具体化。\"},\"c323\":{\"key\":\"c323\",\"title\":\"软陶骰子\",\"kind\":\"main\",\"start\":1261,\"end\":1263,\"summary\":\"母亲反思只要孩子健康快乐便好，回家后天语遥为饼干挡风，独处时终于说出喜欢可爱的情绪。她耐心学习软陶，花下午做出精整黑白骰子，继而尝试印章等小作品，把书架清空作为展示处。父亲疲倦晚归为缺席出游道歉，天虽心疼仍赌气，陶艺上的成就先于亲子和解到来。\",\"turn\":\"陶艺建立耐心与成就感，关心父亲的情绪尚难直接表达。\"},\"c324\":{\"key\":\"c324\",\"title\":\"调皮的母亲大人\",\"kind\":\"main\",\"start\":1264,\"end\":1267,\"summary\":\"天语遥专注制作后早早疲倦，母亲照常给她助眠药。她梦见软陶能化为真实事物，并恢复失去的身体，梦最终转为惊惧。母亲夜里未经她同意趁熟睡替她换上女装，期待她适应；次晨天照镜发现，愤怒又无奈地质问，母亲装无辜打趣。情节虽以玩笑描写，仍存在身体与选择边界被越过。\",\"turn\":\"恢复身体只是梦；现实换装未经同意，母女相处仍含关爱与控制。\"},\"c325\":{\"key\":\"c325\",\"title\":\"方莜莜的家事\",\"kind\":\"main\",\"start\":1268,\"end\":1271,\"summary\":\"连绵秋雨中苏雨晴逗朱雀，与合租伙伴谈中秋回家。张与林均未向家里坦白，苏仍自认无家可归，只有胡计划回村。方莜莜透露幼年父母离婚且生母不要自己，父亲另娶后又与继母疏离，近来赴大城市工作；她以无人管束换自由自我安慰。旁边林默画令人不安的纷乱色线。\",\"turn\":\"不同原生家庭状况使合租屋成为替代归属；方的温柔背后显露被舍弃经验。\"},\"c326\":{\"key\":\"c326\",\"title\":\"方莜莜的地址\",\"kind\":\"main\",\"start\":1272,\"end\":1275,\"summary\":\"林夕晨画完抽象人形后如释重负，把画揉团丢弃，这与她珍存普通作品形成区别。苏替懒散张做饭，胡因恋爱短信羞涩防备。方与安念在游戏中因劫掠行为遭多公会追杀，下线后继续亲近聊天；安借暂存物品索地址，方只给附近代收杂货店，既怕暴露身份又暗盼现实相见。\",\"turn\":\"林用画泄压；方安关系从线上迈向可收实物的联系，真实身份仍隐瞒。\"},\"c327\":{\"key\":\"c327\",\"title\":\"萎靡的小红鸡\",\"kind\":\"main\",\"start\":1276,\"end\":1279,\"summary\":\"周一王海峰解释培训缺人而调苏雨晴休假，实是为她避开最繁重班次；王、陈淑艳拌嘴仍共同护着她，梅经理也宽和。午餐时苏与胡在安静走廊交谈，胡沉默认已开始注射药物，苏担心其身体下降却难劝出口。二人下班回家，见林夕晨担忧蹲在已显萎靡的朱雀旁。\",\"turn\":\"职场保护持续，胡健康顾虑获证实，朱雀病危开启失落事件。\"},\"c328\":{\"key\":\"c328\",\"title\":\"小红鸡之死\",\"kind\":\"main\",\"start\":1280,\"end\":1282,\"summary\":\"苏雨晴发现朱雀病重，众人和曲奇、咖啡都努力照顾却未能挽回。胡解释染色雏鸡的脆弱，苏仍自责，带猫鼠到小区绿化角落埋葬，以石头和柳枝作记号。回家后林夕晨赠她海景画安慰。苏渐平静，却因宠物寿命想到父母也终会离世，重新审视永不相见的决定。\",\"turn\":\"朱雀确实死亡安葬；失落深化苏对亲情和时间不可逆的意识。\"},\"c329\":{\"key\":\"c329\",\"title\":\"方莜莜的生日（一）\",\"kind\":\"main\",\"start\":1283,\"end\":1285,\"summary\":\"九月二十二日苏雨晴轮休在家，翻日记、看朱雀小墓并思考自由与束缚；冉空城问候减少到节日，她仍不回应。林送来自己署名、共四十九幅无字画册，每页背身主角穿行不同景象，其中海中变形鱼与折翼鹰明显呼应莫空寓言。苏欲细究，被请半天假的张思凡归来打断。\",\"turn\":\"林画册把既有寓言化为视觉线索；生日筹备前苏反思自己的相对幸运。\"},\"c330\":{\"key\":\"c330\",\"title\":\"方莜莜的生日（二）\",\"kind\":\"main\",\"start\":1286,\"end\":1288,\"summary\":\"张思凡说明今日是方莜莜生日，已买十二寸蛋糕，三人用气球、彩带和窗花布置惊喜。苏备画有包装图案的钢笔，林送珍藏名家拨云见日山水画，张的大盒礼物暂保密。她亲自做满桌食物，众人与猫鼠等到天黑仍不见方；苏既期待又敏感地察觉张方旧友关系更亲近。\",\"turn\":\"共同筹备以具体劳动表达珍惜，同时映出苏对关系地位与被爱程度的不安。\"},\"c331\":{\"key\":\"c331\",\"title\":\"方莜莜的生日（三）\",\"kind\":\"main\",\"start\":1289,\"end\":1292,\"summary\":\"项目完工后方莜莜正常下班，接马甲蛋糕店来电，才知雨晶杂货店有礼物。以方宇悠身份工作的她谎称自己是方莜莜男友取件，确认安念按资料生日送来高档蛋糕，又收到生日快乐短信。多年独自或不过生日的方深受触动，既期待亲近又畏真实相见，绕路落泪后回家。\",\"turn\":\"方宇悠为方的出生名；安的礼物打动方，线上情感首次具体进入现实。\"},\"c332\":{\"key\":\"c332\",\"title\":\"方莜莜的生日（四）\",\"kind\":\"main\",\"start\":1293,\"end\":1296,\"summary\":\"方莜莜回家被礼花与祝福惊喜包围，外表埋怨惊吓，内心因多年缺失的庆生而感动。安念送的彩虹蛋糕虽跌落略损仍完整，数字蜡烛标明方二十一岁；她先称自买，后承认网友相赠但对方不知身份。众人吃张的自制餐点，点两份蛋糕蜡烛唱歌，方把同一愿望许两遍，未公布内容。\",\"turn\":\"生日使原生家庭的缺席由朋友陪伴补足；方对安的心意未正式确立恋爱。\"},\"c333\":{\"key\":\"c333\",\"title\":\"方莜莜的生日（五）\",\"kind\":\"main\",\"start\":1297,\"end\":1300,\"summary\":\"庆生正热闹时胡玉牛未经事先告知带柳韵进门，伙伴因身份隐私紧张，方及时改男声接待，柳以为这里有三个女孩。大家确认她仍不知胡的愿望和合租者身份，对贸然来客不满。苏提议吃蛋糕缓和场面，柳吃醋后用奶油逗胡，众人加入玩闹，暂时掩盖了边界冲突。\",\"turn\":\"柳初见合租伙伴仍不知实情；隐私边界与胡对群体的隔阂变得明显。\"},\"c334\":{\"key\":\"c334\",\"title\":\"方莜莜的生日（六）\",\"kind\":\"main\",\"start\":1301,\"end\":1304,\"summary\":\"十点胡送柳回家，听她称自己很有男子气概时勉强微笑，想问秘密却再次退缩。其他人清扫到近午夜，方拆出苏的钢笔、林的山水画和张的成人用品玩笑礼盒，窘迫收起。胡回来为没帮忙道歉，苏无心说大家习惯了，反使他感到被排除；庆生欢乐后各自隐藏的失落仍在。\",\"turn\":\"胡被恋人肯定的男性形象与本愿冲突，伙伴的一句习惯触动其归属危机。\"},\"c335\":{\"key\":\"c335\",\"title\":\"新世界之门（上）\",\"kind\":\"main\",\"start\":1305,\"end\":1307,\"summary\":\"天语遥母亲照护半月后返工，父母为未来保障更忙，父还考虑合资工厂但未实施。天研究兔子照护、更换饼干笼具，逐渐能面对用药和外观变化，旧部仍只以为她变乖。她因好奇网上搜索自愿改变性别的人，从强烈排斥转向阅读资料，却仍难理解别人主动追求自己痛失的改变。\",\"turn\":\"天开始认识不同性别经验，接纳自己仍与对别人偏见并存。\"},\"c336\":{\"key\":\"c336\",\"title\":\"新世界之门（下）\",\"kind\":\"main\",\"start\":1308,\"end\":1311,\"summary\":\"父母疲惫返家带饭和食品，天语遥第一次难为情地关心父亲劳累，逐渐看见一直存在的爱。她问为何有人愿放弃男性身份，母亲提醒每人有苦衷、应先尊重别人；天虽激动否认同类，仍收敛敌意。她继续搜索，找到需邀请码的“新世界之门”论坛，申请审核群，准备进一步接触。\",\"turn\":\"家庭关心修复关系，母亲推动尊重差异；天正式迈向同类社区入口。\"},\"c337\":{\"key\":\"c337\",\"title\":\"好想做个女孩子\",\"kind\":\"main\",\"start\":1312,\"end\":1315,\"summary\":\"审核管理员月橙发来用药和心理问卷，天语遥为入论坛尝试以女性心理作答，通过后取昵称软陶，并加入“好想做个女孩子”群。论坛令她发现主动与被动改变者并存，理解更多经历，也生出未来身体可能性的希望；她仍难赞同他人选择、仍恨伤自己的胡。热情群聊与沉郁帖子形成反差。\",\"turn\":\"天以软陶进入既有社群，认知开始变化但仇恨和身份边界尚未消解。\"},\"c338\":{\"key\":\"c338\",\"title\":\"空壳\",\"kind\":\"main\",\"start\":1316,\"end\":1318,\"summary\":\"苏雨晴在休息日疼痛乏力，伙伴称为反噬，机制只是圈内传闻。昏睡中她见自我相残、亲友死亡或精神失常、陌生者复仇及自己永恒漂流，均为噩梦。随后她以不能自主控制的视角来到天台，熟悉却看不清脸的男子称她女友，并介绍大学生秋易；彩色光洞再现，她才醒来。\",\"turn\":\"身体痛苦与密集梦境形成重大伏笔，不能把梦见的死亡当作已发生结局。\"},\"c339\":{\"key\":\"c339\",\"title\":\"中秋（上）\",\"kind\":\"main\",\"start\":1319,\"end\":1322,\"summary\":\"中秋苏雨晴病痛后醒来，只记得梦中被称女友的片段，猜测可能与冉空城有关，却无从确认。冉又发短信，引她回忆两年同桌情谊：他以善意看待她的柔美，为阻止体育课代表强派搬水而争辩并打架，反遭扔进垃圾桶。苏想援手仍受恐吓，女班长及时进教室制止。\",\"turn\":\"苏动摇于友情是否含爱情，校园保护往事揭示依恋形成的具体缘由。\"},\"c340\":{\"key\":\"c340\",\"title\":\"中秋（下）\",\"kind\":\"main\",\"start\":1323,\"end\":1326,\"summary\":\"回忆中校长女儿金晶呵退有体育教师表哥撑腰的孔荀，命苏以后遇欺凌求助；苏与冉留级后她仍常探望。现实短信告知金已赴别城读高中，苏仍不回冉，想切断旧关系又难舍。无月中秋，伙伴分享月饼，方温柔劝她可回家；苏担心不被接纳，只把团圆推给以后，也反思喜欢林是否受性别限制。\",\"turn\":\"旧友去向部分明确，苏的亲情和爱情都处于渴望与自我阻拦之间。\"},\"c341\":{\"key\":\"c341\",\"title\":\"流庆寺（上）\",\"kind\":\"main\",\"start\":1327,\"end\":1330,\"summary\":\"国庆出游因车票与人潮取消杭州计划，五名合租者改去流庆寺，门外拥堵两个多小时令苏几乎站不稳。传闻寺内接待贵客，九点后才开门；饮水与伙伴照应助她缓过。进寺后众人讨论各自信仰，苏和林一同上香，张方受浓烟困扰，胡冷淡旁观，群体共同出游中各有心事。\",\"turn\":\"旅行暴露苏体力限制；信仰与求愿议题开启，杭州之行未成。\"},\"c342\":{\"key\":\"c342\",\"title\":\"流庆寺（下）\",\"kind\":\"main\",\"start\":1331,\"end\":1334,\"summary\":\"胡玉牛说寺内弥勒像由自己家族捐资，却未能阻止家道没落，因此心怀怨意。苏虔诚祈求父母接纳和未来顺利，其余人亦各自礼拜。后院售卖开光物与抽签让张不满，昂贵青莲手串未购；苏区分自己的信仰与僧人买卖行为，带大家去吃斋饭，表现出信仰中的自持与判断。\",\"turn\":\"胡家衰落与寺庙关联揭示；苏对信仰有个人边界，未简单依附宗教权威。\"},\"c343\":{\"key\":\"c343\",\"title\":\"叶族博物馆\",\"kind\":\"main\",\"start\":1335,\"end\":1337,\"summary\":\"众人吃斋后参观寺院收贫家孩子的学习托管处，张逗弄小和尚被方拉开，离寺前买护身符。挤公交时林主动依偎，苏拥抱她，下车后林又主动牵手，关系更加亲密。五人到叶族博物馆参观村落遗迹与兵器，发现巨大叶祖像及弑仙传说；张方、苏林各结伴，胡夹在中间愈显孤单。\",\"turn\":\"苏林双向依偎更明显；集体无意疏离胡，叶祖线与城市来历浮现。\"},\"c344\":{\"key\":\"c344\",\"title\":\"神话传说\",\"kind\":\"main\",\"start\":1338,\"end\":1341,\"summary\":\"苏和张认出叶祖像所持“轮回”剑与百流山山顶所见相同，张买叶族神话册，众人讨论家族传说、历史及湖泊来历，但尚不能证实神话。疲累返家后决定假期不再外游，张因电视阅兵激昂，林画各国军队共同对抗似叶祖的巨人。方处理完工作又与安念相约在游戏里看风景。\",\"turn\":\"实物图像连接此前山顶线索，神话与林画相互呼应但真假尚未回收。\"},\"c345\":{\"key\":\"c345\",\"title\":\"奶油布丁\",\"kind\":\"main\",\"start\":1342,\"end\":1344,\"summary\":\"国庆第三天苏雨晴整理四个月收支，自记存款三千四百元，在电脑、未来手术和过冬衣物之间取舍，最终放弃买电脑并标出必需用品。方第一次做奶油与酸奶布丁，四人与猫鼠边吃边看憨豆先生；苏和林偏爱酸奶，张偏爱奶油。经济紧缩没有消除细小享受，苏逐渐找到自主安排生活的乐趣。\",\"turn\":\"苏把生存与梦想写进预算，节制与共同生活使有限资源仍能带来幸福。\"},\"c346\":{\"key\":\"c346\",\"title\":\"方莜莜的决定\",\"kind\":\"main\",\"start\":1345,\"end\":1348,\"summary\":\"方莜莜已存三万元，因工作难请足恢复假而决定辞职后安排身体手术，张存一万多、拟实习结束再做，仍犹豫。方选择不先告诉父母，以去父母城市工作为由手写辞职报告，估计最快十二月离职；报告尚未获准。苏希望明年底实现计划，方劝成年再做，张支持其坚持。安与方继续暧昧聊天但未确立恋爱。\",\"turn\":\"方愿为身体道路放弃良好职位；工作、家庭隐瞒和亲密关系的后果尚待展开。\"},\"c347\":{\"key\":\"c347\",\"title\":\"莫空和大黑狗\",\"kind\":\"main\",\"start\":1349,\"end\":1352,\"summary\":\"莫空在国庆仅有的一天休假到废旧小区河边读书，给压住书本的大黑狗饼干。戴帽清瘦少年来探，先想退避，被大黑认出扑迎，随后温柔喂丰盛嵌糕；面对莫却戒备，抽女士烟并自称这片老大。莫尊重不追问，两帮此前分日期使用的公共区如今已能共同聚会。\",\"turn\":\"大黑牵引天重回旧地，莫与天首次现实会面形成新的观察关系。\"},\"c348\":{\"key\":\"c348\",\"title\":\"莫空和天语遥\",\"kind\":\"main\",\"start\":1353,\"end\":1356,\"summary\":\"莫空已从黄枸听过天冲云，询问身体使天误以为仇敌来犯。他只加热罐头相赠，天吃不惯转喂大黑，随后默然离开。回家她发现罐底纸条劝既决心断过去便不必追忆，对莫如何知情疑惑。末尾旧部其实已知她受创且仍愿接纳，黄枸劝不要打扰其新生活，引发争执。\",\"turn\":\"莫看穿天的割舍痛苦；旧部已有接纳而天不知，仇怨未被化解。\"},\"c349\":{\"key\":\"c349\",\"title\":\"仇人相见\",\"kind\":\"main\",\"start\":1357,\"end\":1360,\"summary\":\"国庆过后胡玉牛已一月未注射、半月未用药，体力恢复，却仍想重启计划，继续在梦想与柳韵间犹豫。二人河边许诺过年见面、柳毕业后一同去杭州，恋爱将近两月。天语遥偶然认出他们，控诉重伤后果；胡承认出手过重，柳指出先前侵害。胡流露复杂羡慕被天视为讽刺，二人离开，她哭誓报复。\",\"turn\":\"天与胡当面对质未动手，停药没有解决胡身份冲突，复仇线重新燃起。\"},\"c350\":{\"key\":\"c350\",\"title\":\"被撕开的伤口\",\"kind\":\"main\",\"start\":1361,\"end\":1364,\"summary\":\"重遇胡后天语遥的创伤与复仇执念激烈爆发，昏厥并第三次入院。两天两夜后醒来，母亲转述贫血、发热已退，天却忘记重遇当天的事。父亲送进口电子烟取悦并承诺周末全家游杭州，随即返工；天虽不舍却体谅，要求回家让母亲上班。她主动说永远是妈妈孩子，亲子关心增加而创伤暂被遗忘。\",\"turn\":\"记忆缺口暂压复仇，家庭关系继续软化；杭州约定尚未见执行。\"},\"c351\":{\"key\":\"c351\",\"title\":\"一剑破万法\",\"kind\":\"main\",\"start\":1365,\"end\":1368,\"summary\":\"秋雨中林夕晨通过样画、圈点和手把手方式教苏融合素描与写意，苏的暗恋更深却不敢明说，林神色似有幸福。张读悟空传激动模仿台词，方劝其休息，并拆穿她借茶叶谈环境的牵强哲理。苏把完成的御剑仙人山水图送张，张惊喜后与方争画，平淡生活中梦想与亲昵交织。\",\"turn\":\"苏林通过技艺交流加深依恋，苏将受教成果化为对伙伴的礼物。\"},\"c352\":{\"key\":\"c352\",\"title\":\"偷吃巧克力\",\"kind\":\"main\",\"start\":1369,\"end\":1372,\"summary\":\"王休假时苏与陈淑艳及促销员在灯坏多时的散称仓盘点，翁只要求当天完成。陈以工作被剥削为由邀请偷吃商品巧克力，苏受催尝了一块，见他人习惯如此仍良心不安，拒绝继续。她担心自己被社会同化、失去本色，也因久未见周超猜他离职而失落，但周的实际去向此时并未确认。\",\"turn\":\"受照顾者也有道德瑕疵，苏开始主动守住边界；周离职只是猜测。\"},\"c353\":{\"key\":\"c353\",\"title\":\"吹牛打屁\",\"kind\":\"main\",\"start\":1373,\"end\":1376,\"summary\":\"连雨令狗头帮聚在废楼梯下打牌聊天，墙纸和废料茶几构成秘密基地。彩虹分享新闻与知识，剑鱼解题出主意又以民族话术掩饰英语不足，凤凰跑腿买面。黄枸严禁成员沾毒，强调感情需负责，却对偷窃打斗等仍放任。成员彼此陪伴又吹嘘，自我规则与现实伤害并存。\",\"turn\":\"帮派分工、友情和选择性道德进一步呈现，为仇敌相遇作铺垫。\"},\"c354\":{\"key\":\"c354\",\"title\":\"是你！\",\"kind\":\"main\",\"start\":1377,\"end\":1380,\"summary\":\"彩虹领人用废木做床，天语遥帮的元老也在公共基地。胡带柳来探救过她的狗头帮，老三突然认出胡正是伤天之人，六名旧部想报仇。黄枸首次知道伤人者身份，认为天侵害在先而两不相帮；老二以实力不足和应让老大决定劝住老三。胡带柳离开，未发生新打斗，但报复追踪将继续。\",\"turn\":\"原本友好探访让仇人身份向旧部公开，老二暂阻冲突却未化解仇怨。\"},\"c355\":{\"key\":\"c355\",\"title\":\"同在小城\",\"kind\":\"main\",\"start\":1381,\"end\":1384,\"summary\":\"天语遥花三天制成大黑软陶像并在论坛晒图，书架已能排出迷你街道。她渐融入论坛日常，仍不全理解不同性别愿望。群聊揭月橙就是张思凡、优子就是方莜莜；得知张同住小城市白兔街后，天答应次日拜访，接受地址电话。她实报十七岁，却把一米六一虚报一米七以维护旧自尊。\",\"turn\":\"天与合租群体即将现实交会，网名身份对应明确，仍隐瞒被动变化缘由。\"},\"c356\":{\"key\":\"c356\",\"title\":\"男人……也能长得这么漂亮？\",\"kind\":\"main\",\"start\":1385,\"end\":1388,\"summary\":\"天语遥独自乘出租车到白兔街，八点致电确认后进入合租屋。张热情介绍自己月橙、方优子、苏清泉、林夕子；胡不在场。天惊讶同伴容貌与女性声音，尤其苏林完全超出她的先入想象。得知声音可以练习转换，她更觉新奇，却用不常上网掩饰为何对社区知识陌生。\",\"turn\":\"网络联系转为现实，同伴形象打破天的刻板预期；仇人胡没有在场。\"},\"c357\":{\"key\":\"c357\",\"title\":\"天语遥的会面\",\"kind\":\"main\",\"start\":1389,\"end\":1392,\"summary\":\"初次会面中天语遥受林夕晨吸引又纠结性别，既恢复些豪爽，又怕坦白自己并非主动选择会被排斥。张擅自掀帽、端详脸型、指出谎报身高，邀化妆屡遭拒绝；再谎称果汁下了助眠药逗她，触发其强烈戒备后才说只是玩笑。方温柔递纸，与张缺少边界的热情形成差异。\",\"turn\":\"天的身份冲突和个人边界显露；果汁并未实际下药，不可写成真投药。\"},\"c358\":{\"key\":\"c358\",\"title\":\"天语遥的女“妆”\",\"kind\":\"main\",\"start\":1393,\"end\":1396,\"summary\":\"方莜莜为张的玩笑解围并提醒需尊重同意，林递星形饼干使天感到被善待。天对妆后形象好奇，终于随张去梳妆；张又越界触碰引她愤怒委屈，随后道歉。镜中女性形象令天惊讶，口头淡漠却同意拍照并索要照片，拒绝过分姿势。她体验新可能，同时仍认为自己是在强迫改变。\",\"turn\":\"温柔安慰与越界并存，天首次愿意保留女性形象，却未解决内在不认同。\"},\"c359\":{\"key\":\"c359\",\"title\":\"小弟的留言\",\"kind\":\"main\",\"start\":1397,\"end\":1400,\"summary\":\"会面次晨天语遥想念热闹，反复整理外表并从张发来的照片选三张发论坛，受到赞美、嘲讽和不受欢迎邀约，后者被她鄙弃。老三留言表示兄弟已知受创却永认她为老大，又告知发现胡。温情令她感动，仇敌线索却恢复上次昏厥前记忆，复仇愤怒重燃，她努力保持冷静。\",\"turn\":\"新的自我探索被旧仇打断，旧部接纳与复仇消息共同拉她回过去。\"},\"c360\":{\"key\":\"c360\",\"title\":\"那次事情之后和小弟们的第一次见面\",\"kind\":\"main\",\"start\":1401,\"end\":1404,\"summary\":\"天语遥回神发现自己已在阳台抚兔，对记忆空白与失控感恐惧。她回复老三，意外垃圾信息原是其电脑中木马；电话中旧部重申接纳，天部署寻找胡，得知帮派因缺席面临分裂。她承诺立即见面，带着仍未消失的自毁念头与复仇目的赴烂尾工地旁旧木屋，敲门后获二十余名兄弟惊喜迎接。\",\"turn\":\"截至本段天重返旧群体且开始找胡，实际复仇未发生，心理危机仍持续。\"},\"c361\":{\"key\":\"c361\",\"title\":\"这一切，终将逝去\",\"kind\":\"main\",\"start\":1405,\"end\":1408,\"summary\":\"天语遥重回昔日小弟身边，得到抛起庆祝的热情欢迎。她带忠心的兄弟登山，面对离心者已无意强留；身体衰弱使熟悉山路也走得艰难。重新有水却改道的小溪触动她对旧生活的怀念，她意识到帮派终将散去，仍舍不得眼前的情谊。\",\"turn\":\"旧日首领身份与身体变化冲突，天语遥开始考虑散帮。\"},\"c362\":{\"key\":\"c362\",\"title\":\"言语侮辱\",\"kind\":\"main\",\"start\":1409,\"end\":1412,\"summary\":\"在溪边休息的天语遥被雷声惊得落水，原部下老六带分裂者前来，趁机以性别和伤后身体辱骂她并争夺老大位置。忠心小弟揭穿老六忘恩负义，天语遥克制后接受挑战，凭经验将其击倒并放他离开，但受辱者仍准备偷袭。\",\"turn\":\"老六的夺权与恶意羞辱将冲突升级，失败后仍不肯罢休。\"},\"c363\":{\"key\":\"c363\",\"title\":\"残身\",\"kind\":\"main\",\"start\":1413,\"end\":1416,\"summary\":\"老六偷袭不是继续比武，而是公开暴露天语遥的伤后身体，揭出自己对旧恋情的嫉恨；他恶意歪曲夏归月选择天语遥的往事。兄弟们制伏老六并表忠心，但天语遥心理崩溃而严重自伤。众人将她救起，冒暴雨抬下山求救；老六及追随者乘乱逃走。\",\"turn\":\"天语遥陷入生命危机；背叛和公开羞辱造成创伤复发。\"},\"c364\":{\"key\":\"c364\",\"title\":\"急救\",\"kind\":\"main\",\"start\":1417,\"end\":1420,\"summary\":\"众兄弟凑钱后才得以将天语遥送上救护车，外包人员又未施行急救。医院内的管医生则平等温和地救治她，手术成功使她脱离危险。管鹏为父亲送饭，支持父亲离职的念头；叙述明确预告管医生后来辞职。天语遥父母赶来照顾，并未责怪救人的兄弟。\",\"turn\":\"天语遥获救，兄弟情进一步稳固；医护与逐利管理形成对照。\"},\"c365\":{\"key\":\"c365\",\"title\":\"不想再醒来的梦\",\"kind\":\"main\",\"start\":1421,\"end\":1424,\"summary\":\"天语遥昏迷中梦见自己以天冲云身份与旧恋人夏归月结婚，拥有儿女与平静生活；她意识到这只是难以实现的愿望后不愿醒来。狐耳九尾少女将她推出梦境。醒后老二以报仇劝她活下去，她要求暂不告知父母仇人线索，并向母亲承诺不再轻生。\",\"turn\":\"与夏归月的婚姻仅为梦境；报仇暂时成为天语遥继续生活的动力。\"},\"c366\":{\"key\":\"c366\",\"title\":\"林夕晨的外套\",\"kind\":\"main\",\"start\":1425,\"end\":1428,\"summary\":\"王海峰因人手调整建议苏雨晴去轻松的玩具部，她舍不得和善主管而拒绝。下班暴雨将她困住，林夕晨主动撑伞来接，又将自己的大衣披给她；这份无声照料令苏雨晴更确信自己的爱意。回家后的一次浴后尴尬使她害羞躲开，夕晨则露出宠溺笑容。\",\"turn\":\"夕晨主动接送与让衣，使雨晴对这段感情的期待加深。\"},\"c367\":{\"key\":\"c367\",\"title\":\"电视剧的套路\",\"kind\":\"main\",\"start\":1429,\"end\":1432,\"summary\":\"曲奇捣乱引发两人尴尬的浴后照面，夕晨表面平静却悄悄脸红。两人一起看思凡租来的电视剧：故事里两个因女人结仇的男子最后相爱，表现爱可跨越性别；雨晴半途睡着，夕晨看完并因剧中的爱情寓意提出想吃柠檬，还偷偷看向雨晴。\",\"turn\":\"夕晨对雨晴的情感借电视剧与柠檬意象得到暗示，未明说。\"},\"c368\":{\"key\":\"c368\",\"title\":\"再平淡不过的一天\",\"kind\":\"main\",\"start\":1433,\"end\":1436,\"summary\":\"休息日雨晴写周记并照料宠物，发现咖啡毛色已完全变为深紫。胡玉牛为改变外形强穿小鞋，雨晴担忧却无从帮助。夕晨穿昂贵服装、化淡妆出门，让雨晴误以为赴约而吃醋；夕晨以拥抱安抚，明确否认去见男友，并为她露出笑容。\",\"turn\":\"夕晨的外出目的未明；胡玉牛外貌焦虑持续加重。\"},\"c369\":{\"key\":\"c369\",\"title\":\"早点回来\",\"kind\":\"main\",\"start\":1437,\"end\":1440,\"summary\":\"王海峰通知雨晴因领导检查而再休一天，使未具身份证的用工状态显露。雨晴整日惦记外出的夕晨，抱着宠物等候。晚饭时夕晨仍未归，电话里声音疲惫，只说会晚回；雨晴发短信提醒夜路安全，又特意留出她喜欢的春卷、糖醋藕和蛋糕。\",\"turn\":\"夕晨迟归引发不安，雨晴的关怀落实在留饭与等候中。\"},\"c370\":{\"key\":\"c370\",\"title\":\"小城市小商品市场\",\"kind\":\"main\",\"start\":1441,\"end\":1444,\"summary\":\"雨晴等夕晨到睡着，翌日在夕晨床上醒来，具体如何被移至床上未叙。她邀夕晨盛装陪逛小商品市场，精打细算购入换季衣物并首次费力议价买羽绒服。两人牵手同行，雨晴又买红色狐尾围巾送夕晨，为自己挑白猫围巾；夕晨笑着表示喜欢。\",\"turn\":\"雨晴送出具有成对意味的围巾，两人度过亲密的购物日。\"},\"c371\":{\"key\":\"c371\",\"title\":\"上晚班的日常（上）\",\"kind\":\"main\",\"start\":1445,\"end\":1448,\"summary\":\"雨晴上晚班时耐心回答顾客问路，却被投诉霉米的老人错当服务台人员斥责羞辱。周超以清楚解释和带路替她解围；她才发现他仍在超市工作。另一边王海峰与厂家商议促销地堆并收取小额好处，叙述借此呈现人情与职场规则对好人的侵蚀。\",\"turn\":\"周超重新出现并展现善于沟通的一面，雨晴感激他的帮助。\"},\"c372\":{\"key\":\"c372\",\"title\":\"上晚班的日常（下）\",\"kind\":\"main\",\"start\":1449,\"end\":1452,\"summary\":\"周超确认已由防损部调到酒柜，称喜欢王海峰的工作氛围，对雨晴又有明显亲近之意。雨晴为顾客结账、替家电部处理锁机后的付款，面对陌生人已比初入社会时自然成熟。新的中年兼职也到岗；雨晴坚持等交班才去吃饭，显示责任感。\",\"turn\":\"雨晴工作能力成熟，周超成为直属同部门同事。\"},\"c373\":{\"key\":\"c373\",\"title\":\"你竟然也住在这里\",\"kind\":\"main\",\"start\":1453,\"end\":1455,\"summary\":\"周六清晨天语遥来合租屋做客，询问房租并想搬来，实因父母在两次自伤后严密看护，令她失去自由。思凡说明整套六房由五名同伴承租，以避免外人打扰。正当她问起未见过的第五人，去见柳韵后情绪不佳的胡玉牛回家；天语遥立即认出了仇人。\",\"turn\":\"天语遥与胡玉牛意外相遇，原本分离的仇恨线汇入合租主线。\"},\"c374\":{\"key\":\"c374\",\"title\":\"天大的笑话\",\"kind\":\"main\",\"start\":1456,\"end\":1459,\"summary\":\"天语遥意识到致自己重伤的胡玉牛也是渴望女性身份的同伴，原定以同样伤害复仇的计划失效。她在失控中攻击其外形后哭着离开。室友不知真实缘由，思凡用感情纠纷玩笑试图缓和，胡玉牛拒绝解释。天语遥跑到陌生小公园痛哭，意外遇见旧恋人夏归月。\",\"turn\":\"复仇计划受挫；夏归月重新进入天语遥生活。\"},\"c375\":{\"key\":\"c375\",\"title\":\"夏归月\",\"kind\":\"main\",\"start\":1460,\"end\":1462,\"summary\":\"夏归月认出哭泣而虚弱的天语遥并拉住她；天语遥羞于展示变化，试图否认身份和逃走，却一度昏倒。夏归月以膝枕照料，回忆昔日一年多恋情及和平分手，坚决而温柔地劝她倾诉。天语遥口称已成陌路人，夏归月看穿逞强，主动亲吻她。\",\"turn\":\"旧情在脆弱与照料中重燃，天语遥的男性强硬形象被打破。\"},\"c376\":{\"key\":\"c376\",\"title\":\"说出来会好受一些\",\"kind\":\"main\",\"start\":1463,\"end\":1466,\"summary\":\"天语遥终于向夏归月讲出遭遇与内心苦痛。夏归月先因现实顾虑委婉拒绝复合，提出做姐妹，天语遥拒绝被同情而离开；她孤独的回望又让夏归月决定跨越顾虑追求旧爱。夏归月追上明确提出在一起，天语遥嘴上拒绝，最终接受牵手同行，把眼前幸福视作可能短暂的安慰。\",\"turn\":\"夏归月重新提出恋爱关系；天语遥仍对共同未来缺乏信心。\"},\"c377\":{\"key\":\"c377\",\"title\":\"来，我喂你吃\",\"kind\":\"main\",\"start\":1467,\"end\":1470,\"summary\":\"夏归月带天语遥吃火锅，发现她已不能适应从前爱吃的辣，便换清淡锅底并细心喂食。天语遥承认父母已将身份证姓名改为天语遥，却希望夏归月仍叫冲云以保留旧日自我。两人恢复亲密约会，夏归月邀请她回家见父母，天语遥虽紧张仍接受。\",\"turn\":\"饮食和称呼凸显变化；关系推进至正式见家长。\"},\"c378\":{\"key\":\"c378\",\"title\":\"爸，妈！\",\"kind\":\"main\",\"start\":1471,\"end\":1474,\"summary\":\"初见夏归月父母时，沉浸婚后幻想的天语遥误喊爸妈，令众人尴尬。夏父开明友善，夏母对女儿带恋人回家保留顾虑；两人不断送水果查看房内情况。夏归月给天语遥戴小红花取乐，她逐渐看见自己不再独断控制后，归月比旧日恋爱时更自由快乐。\",\"turn\":\"夏归月父母首次接触天语遥，暂不知其身体情况；恋爱权力关系改变。\"},\"c379\":{\"key\":\"c379\",\"title\":\"柳韵调戏胡玉牛\",\"kind\":\"main\",\"start\":1475,\"end\":1478,\"summary\":\"胡玉牛与柳韵在公园竹林玩大富翁和五子棋，柳韵调皮争胜又大胆表达亲密，阿牛则纵容她并在意她的情感经历。肯德基约会看似甜蜜，阿牛却想起孔雀医生所述生育与身体变化问题，面临维持恋情和继续转变的两难，仍拖延作出取舍。\",\"turn\":\"阿牛渴望兼得恋爱与身份转变，逃避选择埋下后患。\"},\"c380\":{\"key\":\"c380\",\"title\":\"让他走吧\",\"kind\":\"main\",\"start\":1479,\"end\":1482,\"summary\":\"夏归月学业繁忙，两人的恋爱多靠短信维系。部下再次发现阿牛，天语遥赶到小城第一高中，表面接受道歉并命兄弟放行，还把帮主交给老三后退出。实际上她已决定假装和解，争取搬入合租屋搜集阿牛身份的证据，借柳韵及其亲属实施更深的报复。\",\"turn\":\"天语遥退出帮派，表面宽恕掩盖针对阿牛社会关系的复仇计划。\"},\"c381\":{\"key\":\"c381\",\"title\":\"周超和他的新女朋友\",\"kind\":\"main\",\"start\":1483,\"end\":1486,\"summary\":\"周超的未具名女友来到酒柜，两人公开亲密并购买食品日用品。雨晴短暂失落于自己误判他的追求，继而思考普通恋情与自身身份处境的差距。她从孙昊细微神情怀疑他只对思凡抱猎奇心理，但缺乏把握没有提醒；想到夕晨，仍是甜蜜与不安并存。\",\"turn\":\"周超已有女友；雨晴对孙昊动机的怀疑尚属个人判断。\"},\"c382\":{\"key\":\"c382\",\"title\":\"游戏里的结婚\",\"kind\":\"main\",\"start\":1487,\"end\":1490,\"summary\":\"莜莜上线《传奇》后被安念带去婚姻殿堂。因她用男性角色优子，安念换女号有只银娘，二人在游戏结婚并办只有两人的喜宴。莜莜决定继续隐瞒自身经历，既幸福又担忧无法现实相见；夜里梦见婚后被安念发现身份而辱骂惊醒，显示隐瞒带来的焦虑。\",\"turn\":\"两人确立网恋；现实身份未坦白，辱骂仅发生于莜莜噩梦。\"},\"c383\":{\"key\":\"c383\",\"title\":\"莫空和胡玉牛的对话\",\"kind\":\"main\",\"start\":1491,\"end\":1494,\"summary\":\"莫空将跳上岸的鱼放回水中，随后听胡玉牛坦白身份愿望、天语遥旧怨与柳韵恋情。莫空表示不歧视，以鱼的生存处境劝其慎重，并列出放弃转变、放弃恋情、兼顾两者三条路。阿牛仍寄望奇迹，选择同时前行；莫空提醒若真爱柳韵，也须考虑她的感受。\",\"turn\":\"阿牛选择兼顾两条道路，莫空强调决定与责任最终仍在本人。\"},\"c384\":{\"key\":\"c384\",\"title\":\"猫大王\",\"kind\":\"main\",\"start\":1495,\"end\":1498,\"summary\":\"雨晴与夕晨带曲奇、咖啡晨游公园，夕晨主动牵她的手。曲奇击退挑衅的宠物犬，却与大黑狗亲近相处，形成狗背猫、猫背鼠的奇景。摄影者获许只拍局部，雨晴避免面貌曝光。她提出向夕晨持续学画，希望将来一起在家工作，夕晨温柔答应。\",\"turn\":\"雨晴确定学画愿望；宠物跨物种亲密呼应人与人的接纳。\"},\"c385\":{\"key\":\"c385\",\"title\":\"搬到外面去住（上）\",\"kind\":\"main\",\"start\":1499,\"end\":1502,\"summary\":\"天语遥带兔子饼干在小区吃草，感叹笼中安稳与自由的代价。退帮后的空落里，她将夏归月视为暂时温暖，甚至打算复仇后告别生活。看到父亲劳累、母亲照料又心疼不已；软陶教程未能吸引注意，她最终在晚饭时向父母提出搬出居住。\",\"turn\":\"搬离计划开始执行，恋爱和亲情尚未消除她的自毁倾向。\"},\"c386\":{\"key\":\"c386\",\"title\":\"搬到外面去住（下）\",\"kind\":\"main\",\"start\":1503,\"end\":1506,\"summary\":\"天语遥以融入同类、学习接纳变化为理由请求搬去合租，隐瞒真正的复仇目的。父母整夜商量后，由父亲说服母亲同意，条件是周末回家、出事即搬回，并亲自检查住处。他们迅速替她准备被褥行李，父亲又给一千元生活费；她感激父母，却继续维持说辞。\",\"turn\":\"父母授权搬入同伴住处，天语遥获得接近胡玉牛的机会。\"},\"c387\":{\"key\":\"c387\",\"title\":\"住满了的合租房\",\"kind\":\"main\",\"start\":1507,\"end\":1510,\"summary\":\"父母陪天语遥带行李来到合租屋，而她事前并未征得室友同意。莜莜顾虑旧怨，思凡见她恳求而心软接纳，六间房从此住满。父母认真审视住处、整理家具并不断询问室友情况；莜莜准备午饭，最终勉强收下三百元伙食费，众人面对过度关怀既理解又不自在。\",\"turn\":\"天语遥正式入住，第六房被填满；复仇者进入共同家庭。\"},\"c388\":{\"key\":\"c388\",\"title\":\"和平相处\",\"kind\":\"main\",\"start\":1511,\"end\":1514,\"summary\":\"天语遥父母留下联系方式离去。雨晴靠夕晨肩头睡着，夕晨换左手画画以免吵醒她，却画出令曲奇不安、带创伤意味的画面。傍晚阿牛携柳韵回家，众人担心旧怨揭开秘密；天语遥继续伪装释怀，没有揭露阿牛身份，使他误以为纠纷已过。\",\"turn\":\"表面和平建立；夕晨隐藏情绪通过不安的画作流露。\"},\"c389\":{\"key\":\"c389\",\"title\":\"方莜莜的辞职申请\",\"kind\":\"main\",\"start\":1515,\"end\":1518,\"summary\":\"总经理正式处理方莜莜的辞职请求，惜其能力与潜力而挽留。她以去外地陪恋人为借口，真实目的是安排手术；获准最早次月二十日、月底左右离职。莜莜加紧完成任务，准备推荐并培养朱志杰接任；朱自觉学历不足、也舍不得这位友善主管。\",\"turn\":\"辞职时间确定，手术准备提速，工作传承开始。\"},\"c390\":{\"key\":\"c390\",\"title\":\"搜集证据\",\"kind\":\"main\",\"start\":1519,\"end\":1521,\"summary\":\"天语遥一直等夕晨外出，终于在她盛装离家后搜集阿牛证据，却发现房门上锁，客厅物品也无法证明属于他。她想到需要数码相机及更完整计划，只先收集部分药盒。佛经暂缓她的急躁，饼干受限与曲奇的自由形成对照，她承认自己擅长大局却缺耐心。\",\"turn\":\"搜证首次受挫，天语遥准备把报复从物件搜查推进至影像证据。\"},\"c391\":{\"key\":\"c391\",\"title\":\"在梦中做个女孩子\",\"kind\":\"main\",\"start\":1522,\"end\":1525,\"summary\":\"立冬休息日雨晴从成为理想女孩的梦中醒来，面对身体不适、寒冷与现实失落，以佛教文字平复心绪，却坚持人不能完全没有愿望。天语遥周末回家后提前带各种早餐返屋，既为融入与行事方便，也是真心感谢同伴。雨晴开心吃嵌糕，二人称呼更亲近。\",\"turn\":\"共同生活开始改变天语遥习惯；雨晴仍坚持自身选择。\"},\"c392\":{\"key\":\"c392\",\"title\":\"天语遥和夏归月和过山车\",\"kind\":\"main\",\"start\":1526,\"end\":1529,\"summary\":\"天语遥离开合租屋后与夏归月在游乐园约会，两人吃冰淇淋、坐摩天轮并亲吻。她既珍惜眼前甜蜜又担心没有未来。归月首次坐过山车前犹豫，天语遥鼓励同行，却也紧张虚脱；仍坚持自己解安全带并照顾归月，显示她不愿放下强撑的习惯。\",\"turn\":\"天语遥在亲密中短暂松弛，旧日强硬自尊仍在。\"},\"c393\":{\"key\":\"c393\",\"title\":\"婚纱摄影\",\"kind\":\"main\",\"start\":1530,\"end\":1533,\"summary\":\"夏归月想尝试游乐园服装摄影，天语遥付钱选婚纱套餐。两人先穿旗袍中山装、皇帝皇后装，再拍六张婚纱照；归月坚持分担费用，天语遥则以亲密关系回应。自然投入的拍摄让她仿佛实现梦中婚礼，但这仅是情侣留影，她们等待现场打印照片。\",\"turn\":\"婚纱照片把未实现的婚姻愿望变成可保存的纪念物。\"},\"c394\":{\"key\":\"c394\",\"title\":\"公益捐款的策划\",\"kind\":\"main\",\"start\":1534,\"end\":1537,\"summary\":\"思凡被分派筹划元旦前后的公益募捐，却苦于项目和基金会联络。众人讨论后，莜莜提供做性别相关支持工作的群友联系方式，思凡准备联系并申报。对未成年者选择的讨论令雨晴更明确自我；莜莜忙着赶工辞职，思凡则坦言对不可逆手术仍犹豫。\",\"turn\":\"公益支线启动；不同角色对身份选择和手术的态度被区分。\"},\"c395\":{\"key\":\"c395\",\"title\":\"真角大古\",\"kind\":\"main\",\"start\":1538,\"end\":1541,\"summary\":\"雨晴绕路到中学旁小卖部，看学生吃零食、玩四驱车和看《迪迦奥特曼》结局。她既怀念校园，也意识到自己的童年被学习及功利安排占据，难与同龄人共享话题。回家后想到春节将近、超市忙碌和王海峰明年辞职的传闻，担心友善工作环境随之消失。\",\"turn\":\"雨晴把童年遗憾与当前就业不安联系起来；大古仅为文化引用。\"},\"c396\":{\"key\":\"c396\",\"title\":\"枯黄的爬山虎\",\"kind\":\"main\",\"start\":1542,\"end\":1545,\"summary\":\"众人回到思凡郊外的集装箱房打扫，雨晴面对枯黄爬山虎回忆初来小城的失窃、流浪、面馆工作与再次迁居。她想念父母身体和旧日照料，承认离家带来的悔意，却仍不愿放弃自我。悲伤中即兴写曲唱出失去、哭泣与继续前行，天语遥坐来倾听。\",\"turn\":\"雨晴以创作容纳乡愁，承认悲伤也能与坚强共存。\"},\"c397\":{\"key\":\"c397\",\"title\":\"正式的辞职离开\",\"kind\":\"main\",\"start\":1546,\"end\":1549,\"summary\":\"方莜莜完成全部任务后正式辞职，推荐朱志杰任临时主管，并鼓励他靠学习独当一面。离别有惋惜也有解脱，她终于拥有个人时间，去河边与一名未具名落魄男子喂鱼，观察蚂蚁和自然细节，重新感到希望，决定预约周末手术以便朋友照应。\",\"turn\":\"莜莜结束重要工作阶段，进入手术与休养生活；朱志杰获试任机会。\"},\"c398\":{\"key\":\"c398\",\"title\":\"斩断退路的方莜莜\",\"kind\":\"main\",\"start\":1550,\"end\":1553,\"summary\":\"莜莜在孔雀私人诊所接受去势手术，雨晴、思凡、夕晨和天语遥守候，阿牛未到场。手术成功但恢复疼痛，孔雀轻率展示术后组织令天语遥创伤反应强烈。孔雀正是群中基金会经营者，给予费用优惠和后续照料。莜莜心中反而安定，开始考虑向安念坦白。\",\"turn\":\"莜莜完成去势手术，尚非完整性别确认手术；坦白恋情的念头成形。\"},\"c399\":{\"key\":\"c399\",\"title\":\"跟踪胡玉牛\",\"kind\":\"main\",\"start\":1554,\"end\":1557,\"summary\":\"天语遥连续第五天跟踪阿牛，终于从超市一路跟到孔雀诊所。她使用向父亲撒娇换来的高清数码相机拍下阿牛接受激素注射，又向孔雀假称收藏讨走空针筒，视作照片与实物配套证据。她知道仍需完整证明，但报复计划首次取得有价值的材料。\",\"turn\":\"天语遥掌握关键影像与实物，复仇具备实施基础。\"},\"c400\":{\"key\":\"c400\",\"title\":\"下雪了\",\"kind\":\"main\",\"start\":1558,\"end\":1561,\"summary\":\"十二月小城初雪，莜莜在家恢复，雨晴接手做清淡饭菜、厨艺渐进，夕晨帮她收碗并继续教画。六人难得同桌，阿牛刻意少吃引人担忧。天语遥制作一套夏归月陶人，面对已经齐全的复仇证据却决定暂缓，想先弥补旧日遗憾，与归月过一个快乐新年。\",\"turn\":\"照料使合租生活温暖；天语遥因爱情推迟复仇到过年后。\"},\"c401\":{\"key\":\"c401\",\"title\":\"把真相告诉你\",\"kind\":\"main\",\"start\":1563,\"end\":1566,\"summary\":\"术后数周的莜莜通过QQ和YY向安念坦白药娘经历与手术真相，用变换声线证明自己此前隐瞒的身份。安念惊讶后明确接纳并维持恋爱，说明自己童年也想过成为女孩，因此能部分理解。莜莜喜极而泣，约定明年六月在安念生日时见面，并改成表达爱意的QQ签名。\",\"turn\":\"噩梦中的被抛弃没有成真，坦诚成为网恋转向现实计划的转折。\"},\"c402\":{\"key\":\"c402\",\"title\":\"为什么要这个时候生病？\",\"kind\":\"main\",\"start\":1567,\"end\":1570,\"summary\":\"圣诞前超市忙碌，王海峰因结石就医仍被总经理叫回，又遭不合情理的病中责难，副经理附和。周超、翁锡芽、徐嫂、陈淑艳等同事一致为他不平，梅经理也愿代请假。他继续工作，众人默契分担重活；多年受排挤后，他宣布明年辞职，认为资助上大学的恩情已偿还。\",\"turn\":\"病中受辱坚定王海峰离职，众员工显出真实团结与不舍。\"},\"c403\":{\"key\":\"c403\",\"title\":\"大雪纷飞的圣诞夜（上）\",\"kind\":\"main\",\"start\":1571,\"end\":1573,\"summary\":\"大雪中的圣诞夜，其他室友各有约会或复诊安排，雨晴与夕晨牵手逛街，关系已自然亲密。她们向老伯买糖苹果，又尝路边小吃、到开放海边公园买荧光棒。雨晴暂不计较花费，只想珍惜共同快乐；夕晨面对糖苹果有一瞬低落，随即掩藏。\",\"turn\":\"圣诞约会承载亲密幸福，也闪现夕晨未解释的忧伤。\"},\"c404\":{\"key\":\"c404\",\"title\":\"大雪纷飞的圣诞夜（下）\",\"kind\":\"main\",\"start\":1574,\"end\":1577,\"summary\":\"两人在海边大石后休息，遇见一名沧桑男子自言自语谈孤独、捷径与金钱代价。夕晨罕见震惊，并流畅低声说不那样做又该如何，雨晴尊重秘密未追问。夕晨随后捡起黄白色贝壳，分为两半各留一半；雨晴猜测是信物，却没敢问明，深夜两人回家。\",\"turn\":\"半贝壳成为亲密信物；夕晨赚钱与表情控制伏笔加深。\"},\"c405\":{\"key\":\"c405\",\"title\":\"2004 年年末的日常（上）\",\"kind\":\"main\",\"start\":1578,\"end\":1581,\"summary\":\"年货陈列增多，雨晴因失眠疲惫，在值守酒柜时误把顾客交来的彩票当钱，导致七百元茅台损失。发现后她在隐瞒侥幸与承担责任间挣扎，不愿同事赔偿，更担心上报后的处分与猜疑，最后想到用个人积蓄补齐钱箱。\",\"turn\":\"一次疲劳失误威胁雨晴积蓄，她决定自行承担七百元损失。\"},\"c406\":{\"key\":\"c406\",\"title\":\"2004 年年末的日常（下）\",\"kind\":\"main\",\"start\":1582,\"end\":1585,\"summary\":\"雨晴午休赶回家，从自缝布袋取出七百元补入钱箱，积蓄近减半，整日心疼自责。夕晨察觉她低落，送来昂贵外文复合药物，恰缓解即将缺药的经济焦虑。雨晴感激并决定日后回赠，仍不愿说出失误，早睡不吃晚饭；室友误以为只是身体不适。\",\"turn\":\"失误被私人补足，夕晨的赠药深化信赖，来源仍不明。\"},\"c407\":{\"key\":\"c407\",\"title\":\"真的好喜欢你\",\"kind\":\"main\",\"start\":1586,\"end\":1589,\"summary\":\"年末一天以多组恋情并置：莜莜找工作时与安念互诉依恋；思凡收到孙昊寄来的机械八音盒，听《月光》并相信长久承诺。雨晴差点向夕晨说出喜欢，急以冰淇淋掩饰；天语遥将爱藏心中；阿牛与柳韵在天台相拥，都希望永远相伴。\",\"turn\":\"相似爱语背后各含信任、隐瞒或不安，为命运对照铺垫。\"},\"c408\":{\"key\":\"c408\",\"title\":\"元旦节\",\"kind\":\"main\",\"start\":1590,\"end\":1593,\"summary\":\"元旦雨晴写日记改年份，为室友做早餐，回顾八个月里从独自流浪到六人同住的过程。她羡慕天语遥父母支持，却不知对方转变并非自愿。思凡说明公益活动推迟至一月内，谈到为未来接纳而行动的必要；莜莜恢复后也更会与同伴嬉闹。\",\"turn\":\"新年串联合租成员来历，公益募捐延期但继续推进。\"},\"c409\":{\"key\":\"c409\",\"title\":\"信\",\"kind\":\"main\",\"start\":1594,\"end\":1597,\"summary\":\"夕晨收到大姐来信，得知父亲肿瘤需赴城市医院治疗、需要更多钱。她回忆父亲重男轻女却对自己宠爱、三个姐姐早嫁少受教育，既想家又惧怕改变后的身体被发现。她寄出存款五千元、只留一千；在邮局外为治疗费发愁时，接到男人以宝贝相称的西餐邀约。\",\"turn\":\"父病与经济压力具体化，夕晨对外身份和收入隐情渐显。\"},\"c410\":{\"key\":\"c410\",\"title\":\"被偷东西的超市\",\"kind\":\"main\",\"start\":1598,\"end\":1601,\"summary\":\"超市连续三晚遭盗，笔记本样机和名酒丢失，破损员工门与防损值班失察引发不满。王海峰已因长期不公心寒，不再把超市损失当己任。他与陈淑艳仍保护体弱雨晴、互相斗嘴；雨晴坦言若王离职自己也不想留，这份友好关系成为她留职核心。\",\"turn\":\"超市盗案未破；王海峰职业疏离与雨晴的去留相连。\"},\"c411\":{\"key\":\"c411\",\"title\":\"青年广场上的爱心传递（上）\",\"kind\":\"main\",\"start\":1602,\"end\":1605,\"summary\":\"青年广场公益募捐开场，思凡与知其身份的大学同学子凡搭起偏角小摊，莜莜、夕晨帮忙，孔雀因外出缺席。子凡讨论不能凭外形判断性取向。第一位母亲听明项目后带孩子避开并辱骂，令众人受挫；天语遥随后到场捐一百元，留下协助。\",\"turn\":\"公益行动遭遇公开偏见，但同伴仍守住摊位。\"},\"c412\":{\"key\":\"c412\",\"title\":\"青年广场上的爱心传递（中）\",\"kind\":\"main\",\"start\":1606,\"end\":1609,\"summary\":\"雨晴获王海峰允许延长午休，到青年广场寻找同伴。拥挤的人群、以受创儿童博取同情的展示令她强烈反感，并投射出对自身未来的恐惧。大雨中她找到仅天语遥留守的摊位，海边别墅大小姐和女仆也来避雨，雨晴担心被认出而避开目光。\",\"turn\":\"雨晴对被怜悯、被展示的反感加深；大小姐再度进入故事。\"},\"c413\":{\"key\":\"c413\",\"title\":\"青年广场上的爱心传递（下）\",\"kind\":\"main\",\"start\":1610,\"end\":1613,\"summary\":\"女仆阅读性别相关募捐传单后发问，雨晴因长期偏见经验而误以为将受羞辱。天语遥勉强解释援助目的，女仆实际捐出两百元，大小姐亦默默捐约一两千元。雨晴随后捐一百元，在登记性别栏填男，并借思凡黑伞离开；他人的善意与她的戒备构成反差。\",\"turn\":\"大小姐主仆实际援助；雨晴仍受身份暴露与自我认定困扰。\"},\"c414\":{\"key\":\"c414\",\"title\":\"莫空捐赠的折扣券\",\"kind\":\"main\",\"start\":1614,\"end\":1617,\"summary\":\"思凡与子凡接手摊位，莜莜不适返家、夕晨临时有事离去。莫空前来读海报，注意雨晴登记的性别，捐入一张女人之家高级VIP一折券后离开且未署名。思凡把限购五件的券收入自己口袋。全天募得两千多元，却多遭辱骂与带矫正意味的同情，活动标语显得讽刺。\",\"turn\":\"公益只获有限款项；折扣券由思凡保存，集体受到现实冲击。\"},\"c415\":{\"key\":\"c415\",\"title\":\"暂别\",\"kind\":\"main\",\"start\":1618,\"end\":1621,\"summary\":\"一月底春节将至，天语遥、思凡、莜莜陆续回家，阿牛也计划返村，只剩雨晴与夕晨留守。莜莜因父亲继母和好而回去团圆，穿男装掩饰变化，雨晴担心她不再回来。两人与莜莜在火车站道别，她承诺节后回来，并鼓励两人感情；成对围巾随行。\",\"turn\":\"六人分散返乡，雨晴与夕晨将独自共度第一个离家春节。\"},\"c416\":{\"key\":\"c416\",\"title\":\"临近\",\"kind\":\"main\",\"start\":1622,\"end\":1626,\"summary\":\"除夕前最后晚班，周超透露自己是职高实习班学生，计划暑假前离职学面点、奶茶或做销售；王海峰也准备同期走，雨晴尚未确定下一工作。阿牛与雨晴下班同行，她羡慕他能回家，他反羡慕她断开家庭束缚；被问是否向柳韵坦白或停药，他仍无法决定。\",\"turn\":\"就业转折临近；阿牛对关系与转变的逃避持续。\"},\"c417\":{\"key\":\"c417\",\"title\":\"除夕（一）\",\"kind\":\"main\",\"start\":1627,\"end\":1630,\"summary\":\"除夕清晨雨晴发现夕晨睡在沙发，担心着凉并费力抱她回房，夕晨却没有不适。冰箱食材已空，雨晴决定与她去思凡的郊外集装箱房过年。两人采购米菜、水果、烟花和春联，带曲奇咖啡搭公交至农村终点，再雇三轮车去花芯村后森林前。\",\"turn\":\"雨晴主动为两人建立过年仪式，离开城中喧闹寻找安宁。\"},\"c418\":{\"key\":\"c418\",\"title\":\"除夕（二）\",\"kind\":\"main\",\"start\":1631,\"end\":1634,\"summary\":\"雨晴与三轮车司机议价后抵达集装箱房，整理住处、晒被，宠物与乡间狗群游玩。午间她因思念父母而哭，夕晨拥抱安抚，使她重新振作。两人合作准备年夜饭，雨晴耐心教不会下厨的夕晨，户外桌上摆家常菜与酸菜鱼，也为宠物留食。\",\"turn\":\"乡愁被理解承接，两人以照料和共同劳动建立家庭感。\"},\"c419\":{\"key\":\"c419\",\"title\":\"除夕（三）\",\"kind\":\"main\",\"start\":1635,\"end\":1638,\"summary\":\"雨晴与夕晨在烟花下举杯迎年，夕晨默默为她夹好菜。另一线阿牛离开全村年夜饭，借摩托去接柳韵；她大胆提议翻墙进入关闭的游乐园。二人体验无人园区的刺激与私密，坐上停摆海盗船看星空，柳韵遗憾无月亮见证爱情。\",\"turn\":\"两段不同约会并置，柳韵的月亮爱情观成为后续意象。\"},\"c420\":{\"key\":\"c420\",\"title\":\"除夕（四）\",\"kind\":\"main\",\"start\":1639,\"end\":1642,\"summary\":\"午夜烟花齐放，雨晴邀夕晨笑，夕晨举起新年快乐横批并真诚微笑。雨晴趁烟火巨响喊出喜欢，却不能确定她是否听见，未获直接回答。两人继续燃放烟花，雨晴想起童年、感叹长大；困倦饮酒后被夕晨抱回床陪伴，夕晨直到天亮才入睡。\",\"turn\":\"雨晴第一次喊出爱意，关系即将从暗恋转为明说。\"},\"c421\":{\"key\":\"c421\",\"title\":\"大年初一（上）\",\"kind\":\"main\",\"start\":1643,\"end\":1646,\"summary\":\"两人睡到大年初一傍晚才醒，夕晨少见地自然微笑、流畅说话。雨晴问新年愿望，夕晨让她感受心跳，并明确说愿望是和她在一起。雨晴惊喜确认这是真实发生，两人相拥认定爱情，不再执着谁扮男方女方；随后起床热年夜饭剩菜、喂等了一天的宠物。\",\"turn\":\"主角情侣正式互通心意，这是现实中的确认关系。\"},\"c422\":{\"key\":\"c422\",\"title\":\"大年初一（下）\",\"kind\":\"main\",\"start\":1647,\"end\":1650,\"summary\":\"返乡的天语遥看雪想念夏归月，也回忆兄弟们的愿望，承认旧日选择带来伤痛。她仍打算年后报复再结束生命，却又割舍不下爱情。与归月跨省通话时，她终于说想念；归月期待做她新娘、催她早回，两人互唱《水调歌头》，暂时驱散她的压抑。\",\"turn\":\"爱情暂缓自毁情绪却未改计划；返乡地理与前文存在矛盾。\"},\"c423\":{\"key\":\"c423\",\"title\":\"艳阳高照\",\"kind\":\"main\",\"start\":1651,\"end\":1654,\"summary\":\"正月初五，雨晴与夕晨吃完集装箱房剩余食材，带曲奇返城。确定恋情后雨晴觉得世界明亮起来，围栏裂缝里萌出的嫩芽呼应她的希望。乡间哈士奇追随曲奇送到车站，两人回到尚无室友返回、已经积灰的公寓。莜莜来电说带着大批家乡特产即将到站，邀请她们接站分享年味。\",\"turn\":\"恋情使雨晴重新产生希望，假期结束、室友即将陆续重聚。\"},\"c424\":{\"key\":\"c424\",\"title\":\"张思凡对阵熊孩子\",\"kind\":\"main\",\"start\":1655,\"end\":1658,\"summary\":\"思凡在老家仍隐瞒身份。顽皮小表弟来访，她担心收藏被毁，带一群孩子到村里玩雪地捉迷藏。两个小时后才发现小表弟偷偷回屋，趁大人纵容损坏高达与美少女战士模型、小霸王游戏机和新买的PSP。她愤怒地打孩子屁股，却被母亲和亲戚指责不该为玩具较真。\",\"turn\":\"珍爱收藏被毁且家长偏袒小孩，思凡与母亲的矛盾急剧升级。\"},\"c425\":{\"key\":\"c425\",\"title\":\"负气\",\"kind\":\"main\",\"start\":1659,\"end\":1662,\"summary\":\"母亲又要求将思凡花一个月制作的限量高达送给小表弟，孩子当面摔坏它。思凡愤怒毁掉剩余收藏和电脑显示器，负气离家乘车返城，打算毕业后接受去势手术。列车上，她先梦见与孙昊相守、收养孩子的晚年，又梦见父母拒绝和恋人背叛；醒后仍选择相信孙昊。叙述补明父母正在向表舅借创业款，偏袒孩子为保借款，争执使原许诺十万降至三万，思凡并不知情。\",\"turn\":\"亲子双方都感委屈且信息不通，幸福婚姻和遭弃仅是两段梦境。\"},\"c426\":{\"key\":\"c426\",\"title\":\"神秘的包裹\",\"kind\":\"main\",\"start\":1663,\"end\":1666,\"summary\":\"莜莜回到公寓分家乡点心，感慨父亲和继母有了孩子后疏远自己；思凡也负气归来，向室友诉说亲子冲突。顺丰送来一个没有寄件地址的大包裹，内有雨晴童年爱吃的进口零食、合身衣鞋、抱枕和昂贵SD娃娃。众人猜是她父母所寄，雨晴口头否认父母知道住处，心里却渴望获得他们的接纳，抱着礼物哭着想回家。\",\"turn\":\"神秘寄件人尚未查明，礼物唤起雨晴对父母接纳的期待。\"},\"c427\":{\"key\":\"c427\",\"title\":\"讽刺和还击\",\"kind\":\"main\",\"start\":1667,\"end\":1670,\"summary\":\"春节返乡后，天语遥到旧帮会与黄枸帮会共用的小巷，怀念初见夏归月的时刻，向流浪大黑狗倾诉。两名混混辱骂她的身体变化，她凭旧日打架经验迅速反击，随后克制了进一步造成严重伤害的冲动。外表与体力改变并未消除她维护尊严的强硬，内心却开始察觉自己不愿让别人重受同样的痛苦。\",\"turn\":\"她能克制当下报复冲动，针对胡玉牛的长期仇恨却仍未化解。\"},\"c428\":{\"key\":\"c428\",\"title\":\"抱着我\",\"kind\":\"main\",\"start\":1671,\"end\":1674,\"summary\":\"天语遥陪夏归月游百流山，讨论身体与心灵的自由。她本想照顾恋人，却因体力衰退反被夏归月拉上山；两人参观供奉叶祖的旧庙，谈起族谱和历史。夏归月信任她会守护自己，天语遥却暗认自己不配、准备离开，忍着泪请求对方紧抱不放，归月虽不知缘由仍温柔回应。\",\"turn\":\"共享山顶亲密时刻，天语遥单方面安排离别而夏归月尚不知情。\"},\"c429\":{\"key\":\"c429\",\"title\":\"她最喜欢的是什么呢？\",\"kind\":\"main\",\"start\":1675,\"end\":1678,\"summary\":\"新年上班后，雨晴发现胡玉牛将调往更辛苦、待遇较高的退货部，两人与其他室友日渐疏远。她认真检查保质期、午间用奶油蛋糕犒劳自己，在食堂偶遇阿牛。谈到情人节礼物，她问柳韵最喜欢什么，阿牛竟答不出来，只能继续困惑自己是否了解恋人、是否爱得足够深。\",\"turn\":\"室友间距离扩大；一个礼物问题促使阿牛检视恋爱中的不了解。\"},\"c430\":{\"key\":\"c430\",\"title\":\"外国人\",\"kind\":\"main\",\"start\":1679,\"end\":1682,\"summary\":\"雨晴用有限英语帮助一名外国女顾客找中国白酒，交流遇阻后请王海峰协助，终于弄清对方要整箱二锅头。她因此想起父母对移居海外的不同看法，也向往更能接纳自己的生活。促销员借口补货把检查保质期留给她，陈淑艳为她不平；雨晴不愿引起争执，婉拒替自己出头，维持平静工作。\",\"turn\":\"工作应对能力增强，但雨晴仍以退让回避同事间的利益冲突。\"},\"c431\":{\"key\":\"c431\",\"title\":\"计划开始\",\"kind\":\"main\",\"start\":1683,\"end\":1686,\"summary\":\"阴冷独处的一天，天语遥决定正式实施报复，不再顾虑证据会连带伤害室友。她检查两套照片以及标名的针筒、药盒和隔门录音，联络老三次日到初见之处帮最后一次忙，并冷淡拒谈帮会近况。老三忆起小学受欺负时被她带领反抗，既忠诚又心痛，感到昔日关系正在消散。\",\"turn\":\"报复从搜集资料进入实施，天语遥明确不顾对共同居住者的波及。\"},\"c432\":{\"key\":\"c432\",\"title\":\"冷笑\",\"kind\":\"main\",\"start\":1687,\"end\":1690,\"summary\":\"天语遥想象报复后退出夏归月的生活，又反复否定两人长久相守的可能，以为离开才是替她着想。独处时遇见胡玉牛，她用冷笑回应歉意，暗示对方会感谢自己。她决定数日不见归月，以免动摇。阿牛则接柳韵放学，掩饰肌肉变化，应邀到柳家做饭留宿，不知危机已逼近。\",\"turn\":\"阿牛误以为旧怨已解，天语遥借主动断联维持报复与离别决心。\"},\"c433\":{\"key\":\"c433\",\"title\":\"意乱情迷\",\"kind\":\"main\",\"start\":1691,\"end\":1694,\"summary\":\"阿牛在柳韵家做土豆饼和红豆粥，两人在厨房共进温暖晚餐。他对继续身体转变与承担恋爱责任仍犹豫，甚至怀疑自己的身份愿望是否含有逃避；但柳韵主动亲近使两人关系进一步发展。他沉浸在相守的想象里，仍未向她坦白用药与内心矛盾，也尚未作出承诺所需要的选择。\",\"turn\":\"亲密关系进一步发展，却没有解决身份隐瞒、责任与未来选择。\"},\"c434\":{\"key\":\"c434\",\"title\":\"去办事\",\"kind\":\"main\",\"start\":1695,\"end\":1698,\"summary\":\"老三在旧城区麦当劳后的小区等候天语遥，那里是她当年救他并请吃甜筒的地方。她交付证据，要求查明柳韵住址再伪装快递送达，并明确不再回归帮会。老三完成跟踪，确认柳家在五〇二室；想到帮会从五六十人散至约十人、自己多年忽略父母期待，他重新记起儿时做木匠的理想。\",\"turn\":\"证据送达前准备完成；老三在团体瓦解中开始思考退出混混生活。\"},\"c435\":{\"key\":\"c435\",\"title\":\"林欲静而风不止\",\"kind\":\"main\",\"start\":1699,\"end\":1702,\"summary\":\"初八上班时，思凡因返乡冲突和孙昊背叛的噩梦无心工作，身旁友善女同事替她完成文稿。下班后母亲来电话叮嘱加衣，未责怪她负气离家；她感受到父母牵挂，也为隐瞒身份内疚，原定暑假手术的决心再度摇摆。一路思绪纷乱走错楼，才暂时决定用游戏与电视转移注意。\",\"turn\":\"亲子电话修补春节冲突，却强化思凡对自我选择与父母期待的两难。\"},\"c436\":{\"key\":\"c436\",\"title\":\"神秘的信封\",\"kind\":\"main\",\"start\":1703,\"end\":1706,\"summary\":\"老三伪装快递将天语遥的匿名证据送给柳韵。柳逐一查看照片、药盒、针筒与录音，再对照网上信息及阿牛的身体变化，确认对方隐瞒了转变愿望。带有污名与猜测的信激起她愤怒，女装照尤其令她排斥；她想以向众人揭露来报复，隐住情绪发短信约阿牛次日见面。\",\"turn\":\"柳韵知道隐瞒真相却受恶意信件引导，报复链条开始扩散。\"},\"c437\":{\"key\":\"c437\",\"title\":\"我们去见你父母吧\",\"kind\":\"main\",\"start\":1707,\"end\":1710,\"summary\":\"柳韵在学校表现出班级大姐头的强势，与阿牛面前的温顺判若两人。校门口莫空劝阿牛立即离开恋人以避祸，阿牛不明所以仍等候。柳见到他的真诚后内心软化，开始承认自己真的爱他，又受到既有偏见牵制。她仍按预谋提出见阿牛父母，是否继续揭露却已犹疑。\",\"turn\":\"柳韵并非纯粹利用恋人，真情与偏见冲突，原定报复开始动摇。\"},\"c438\":{\"key\":\"c438\",\"title\":\"胡玉牛父母的款待\",\"kind\":\"main\",\"start\":1711,\"end\":1714,\"summary\":\"阿牛带柳韵坐公交回近郊村庄，父母惊喜迎接，生火取暖、加菜款待，关心这个十七岁的女孩。柳被他们的淳朴热情与阿牛的体贴打动，觉得揭露隐私拆散家庭过于残忍，最终没有实施计划。可她脱下外衣时，装有证据的信无意滑进灶旁柴堆，离开时也没有察觉。\",\"turn\":\"柳韵主动放弃报复，证据信件却意外留在胡家，危机仍在。\"},\"c439\":{\"key\":\"c439\",\"title\":\"坐看风起云涌\",\"kind\":\"main\",\"start\":1715,\"end\":1718,\"summary\":\"柳韵逃课来到湖心废弃公园，重访被阿牛拒绝后又因他留下外衣而重燃希望的地点。她想不清该如何面对恋人的转变与自己的感情，对阿牛的接人短信反复犹疑。一个似流浪汉的沧桑男子坐旁看云，给她香烟，离去前提醒互相坦白才能解决问题；她回头时对方已经不见。\",\"turn\":\"逃避未能理清情绪，陌生男子的劝告把解决方向指向双方坦白。\"},\"c440\":{\"key\":\"c440\",\"title\":\"被发现的信\",\"kind\":\"main\",\"start\":1719,\"end\":1722,\"summary\":\"胡父难得主动做饭，与妻子回忆旧情，也反思把振兴家族的理想强加给儿子。胡母在柴堆发现柳韵的信，胡父坚持不看别人隐私，暂放桌上待归还。另一边柳韵已想起遗失信件，担心阿牛误会，推测送信人是曾被阿牛打伤的混混，觉察自己被借来报复，决意向阿牛坦白寻求办法。\",\"turn\":\"父亲的隐私原则暂时保住秘密；柳韵立场转向保护阿牛并反思报复者。\"},\"c441\":{\"key\":\"c441\",\"title\":\"不孝之子\",\"kind\":\"main\",\"start\":1723,\"end\":1726,\"summary\":\"夜里胡母下楼喝水碰落桌上的信，收拾时发现阿牛的就诊与女装照片，惊慌带给丈夫。胡父起初仍反对窥私，最终为查明儿子的事读信，因用药转变而震怒，立刻电话勒令阿牛返家。阿牛在雨晴关心的目送下赶末班公交，忐忑猜测秘密是否暴露，穿过黑暗山路回到仍亮灯的家。\",\"turn\":\"意外落信打破此前的隐私保护，父母得知秘密并召回阿牛对质。\"},\"c442\":{\"key\":\"c442\",\"title\":\"回不去了\",\"kind\":\"main\",\"start\":1727,\"end\":1730,\"summary\":\"阿牛见到父母拿出的证据，推断天语遥搜集材料，却错误认定柳韵与其串通故意留信。面对追问，他首次向父亲说出振兴家族重担令自己窒息；父亲自责，答应不再要求传承事业，父母劝他恢复旧日生活。阿牛仍承认如今真想做女人，哭着道歉跑出村庄。父亲无力颓坐，他则在山路放声哭泣，感到内疚而无处安放自己。\",\"turn\":\"父亲撤去家族重担仍不能化解身份冲突，阿牛误认恋人合谋，家庭陷入裂痕。\"},\"c443\":{\"key\":\"c443\",\"title\":\"逃避再逃避\",\"kind\":\"main\",\"start\":1731,\"end\":1735,\"summary\":\"阿牛深夜回到公寓，得知天语遥已搬走；他未向莜莜说明遭遇，继续在误会与自责中辗转难眠。柳韵短信约次日下午河边谈话，他仍猜忌这是圈套。次日无心上班，父亲又来电劝他放弃转变，争执从撤去重担再滑向家族传承，最终以不再认他为儿子的气话挂断，令阿牛更加绝望。\",\"turn\":\"天语遥撤离现场，阿牛孤立加深，父子电话从劝返演变成断绝关系。\"},\"c444\":{\"key\":\"c444\",\"title\":\"恩怨情仇\",\"kind\":\"main\",\"start\":1736,\"end\":1739,\"summary\":\"河边会面时，柳韵解释曾想报复却已后悔，信只是意外遗失；阿牛不信，指责她与天语遥合谋，并用伤人的话否定两人的感情。柳批评他的隐瞒与迁怒，仍盼他听进解释，甚至想过若他确实认同女性可转为姐妹。阿牛没有叫住缓慢离开的她，只在愤恨中辱骂与哭泣，两人关系破裂。\",\"turn\":\"解释失败导致分手；柳韵留下关系修复的可能，阿牛未能回应。\"},\"c445\":{\"key\":\"c445\",\"title\":\"转交给胡玉牛\",\"kind\":\"main\",\"start\":1740,\"end\":1743,\"summary\":\"天语遥为保证报复奏效，另准备写明雌性激素的包裹来到超市后仓，将其交给爱传闲话的促销员，嘱转交阿牛。她算准同事好奇与偏见会扩大影响，满意离开。促销员向同伴打听药物用途，议论迅速从猜测发散成对阿牛身份、身体和手术的荒谣，令工作场所也成为公开羞辱的来源。\",\"turn\":\"第二条报复渠道发动，隐私被用于制造职场排斥且谣言失去事实边界。\"},\"c446\":{\"key\":\"c446\",\"title\":\"人言可畏\",\"kind\":\"main\",\"start\":1744,\"end\":1747,\"summary\":\"阿牛把饭桌普通谈笑感为嘲讽，突然摔碗回房。室友担心他与柳韵出事，决定次晨询问，却只得到没事的回答。上班时主管宽容地将前日缺勤改作调休，周围员工态度却因谣言改变。促销员当众递给他标着雌性激素的包裹，阿牛震惊，旁人进一步把他的反应当作证实，心理防线濒临崩溃。\",\"turn\":\"室友帮助未获回应，工作场所公开递包裹加剧羞辱与孤立。\"},\"c447\":{\"key\":\"c447\",\"title\":\"世界崩坏\",\"kind\":\"main\",\"start\":1748,\"end\":1751,\"summary\":\"阿牛试图保持冷静，却在议论中喊出否认，反而招来更多注视与传闻。他失控逃出超市，跑到山腰破亭独自发泄，双手受伤；回公寓时忘带钥匙，在门前站到思凡下班开门。众人被他痛苦而激动的状态吓住，虽不了解全貌，仍决定隔门劝慰，试着让他别再独自压住困境。\",\"turn\":\"公开羞辱引发急剧危机，阿牛受伤退回封闭房间，室友尚不知原因。\"},\"c448\":{\"key\":\"c448\",\"title\":\"好梦\",\"kind\":\"main\",\"start\":1752,\"end\":1755,\"summary\":\"莜莜、思凡和雨晴隔门劝阿牛说出难处，他始终不回应；她们只能暂停，夕晨画出月亮与奇异降雨后将画撕碎。阿牛独处时反省自己的隐瞒、误会与逃避，却认定已经太迟，向柳韵和父母发去语序混乱的致谢短信，随后严重自伤。他在意识模糊中曾后悔放弃希望，此时无人知道房内发生了什么。\",\"turn\":\"多重打击与孤立发展成自伤危机，含混短信成为外界得知危险的线索。\"},\"c449\":{\"key\":\"c449\",\"title\":\"不知道是谁的坟\",\"kind\":\"main\",\"start\":1756,\"end\":1759,\"summary\":\"雨晴不安入睡，梦中荒废公园进一步崩坏，小男孩坐秋千，出现无名坟与排列成鹰形的墓园；梦境带来死亡预感。次晨室友照常生活，以为阿牛早已出门，反复响起的房内电话也被当作忘带手机。直到中午，衣着匆忙的柳韵冲到公寓急问阿牛，拨号确认声音来自紧闭卧室。\",\"turn\":\"习惯性的缺席掩盖异常，柳韵赶来才打破室友对阿牛已外出的误判。\"},\"c450\":{\"key\":\"c450\",\"title\":\"永远的安眠\",\"kind\":\"main\",\"start\":1760,\"end\":1763,\"summary\":\"柳韵急催开门，莜莜找出备用钥匙后，众人发现阿牛倒在房内仍有微弱呼吸。雨晴拨急救电话，思凡说明情况，莜莜与柳韵随救护车送医，其余人赶往医院；最终抢救无效，医生宣布阿牛死亡。柳韵向大家说明匿名信与旧怨，她们才知道天语遥潜伏报复。众人通知父母并配合笔录，雨晴夕晨因证件与身份顾虑避开询问。\",\"turn\":\"胡玉牛抢救无效身亡，报复链条才为室友所知，幸存者进入悲痛与追问。\"},\"c451\":{\"key\":\"c451\",\"title\":\"白发人送黑发人（上）\",\"kind\":\"main\",\"start\":1764,\"end\":1767,\"summary\":\"柳韵把自己知道的原委告诉胡家父母后离去；胡父没有迁怒报复者，沉重自责，在死亡通知书签字，与妻子守灵一夜，次晨遗体火化。合租屋四人也通宵难眠，雨晴一度仿佛听见阿牛招呼声，对前途与家庭愈加悲观。思凡强作爽朗，提醒仍要生活，请大家出门吃丰盛早茶，暂时从屋内压抑走出来。\",\"turn\":\"父母自责守灵，室友遭受共同丧失；思凡以陪伴和日常活动稳定众人。\"},\"c452\":{\"key\":\"c452\",\"title\":\"白发人送黑发人（下）\",\"kind\":\"main\",\"start\":1768,\"end\":1771,\"summary\":\"数日后胡父尽力操办葬礼，对村人只称突发心脏病；他特选据说来世可做女人的墓地，迟来地尊重阿牛愿望，哭着焚纸。母亲抱墓碑痛哭至晕倒，柳韵和室友送别。雨晴上班后得知职场流言也是压力来源；她一度问死亡是否轻松，被莜莜认真劝回，转而数出继续读书、父母接纳、与夕晨相守等尚未完成的心愿。\",\"turn\":\"阿牛入葬，父亲出现迟到的接纳；雨晴从厌世感转向具体生命愿望。\"},\"c453\":{\"key\":\"c453\",\"title\":\"离开合租房\",\"kind\":\"main\",\"start\":1772,\"end\":1775,\"summary\":\"葬礼后四人回到公寓，阿牛遗物已由父母搬空，空房仍使大家触景伤情，终于同意另寻住处。莜莜宣布父母已去外地、自己在小城求职不顺，准备回乡，实际也想离开伤心城市。离别前四人挤在思凡床上笑闹，次晨莜莜做丰盛早餐，三人送她乘十点火车，在《明月几时有》的歌声中目送她离开。\",\"turn\":\"六人共同生活彻底结束：阿牛死亡、天语遥失联、莜莜返乡，只余三人。\"},\"c454\":{\"key\":\"c454\",\"title\":\"重新搬进集装箱房\",\"kind\":\"main\",\"start\":1776,\"end\":1779,\"summary\":\"送走莜莜后，思凡、雨晴与夕晨回公寓收拾行李，保留尚未取完的物品，暂待月底退租。她们选择重新住进郊外集装箱房，返程受到哈士奇与十多只土狗热闹迎接，发现院落已成部分流浪猫狗的栖处，菜地也在春天复苏。雨晴终于笑起来，向思凡明确承认已与夕晨确定恋爱关系。\",\"turn\":\"三人重返最初庇护所，动物与春日生长带来新的生活感，恋情公开给思凡。\"},\"c455\":{\"key\":\"c455\",\"title\":\"尘封的电瓶车\",\"kind\":\"main\",\"start\":1780,\"end\":1783,\"summary\":\"为解决郊外到市中心上班需一小时以上的交通，思凡取出搁置大半年的电瓶车，三人清洗检查，夕晨贴图遮住旧痕，思凡推去换电瓶维修。雨晴回忆最初面馆低薪生活、思凡接送与酒吧获救经历，也因超市议论动念随已递辞职报告的王海峰离开。思凡买菜归来，三人吃海鲜年糕，逐渐恢复胃口与欢笑。\",\"turn\":\"旧交通工具重新连接工作与家，三人恢复生活安排，雨晴开始考虑辞职。\"},\"c456\":{\"key\":\"c456\",\"title\":\"坐上电动车去吹风\",\"kind\":\"main\",\"start\":1784,\"end\":1787,\"summary\":\"搬回集装箱房后的周一，思凡为送雨晴上早班提早起床，夕晨亲昵唤醒赖床的恋人。雨晴不舍留下夕晨独处，仍坐电动车迎着寒风出发；路上买糯米饭，在车后座吃早餐，六点四十分抵超市没有迟到。思凡约好下班接她，雨晴带着重新获得的希望工作，与王海峰、陈淑艳恢复熟悉的玩笑。\",\"turn\":\"艰辛通勤由友情分担，雨晴在亲密关系和日常照顾中重新稳住生活。\"},\"c457\":{\"key\":\"c457\",\"title\":\"方莜莜一个人的家\",\"kind\":\"main\",\"start\":1788,\"end\":1791,\"summary\":\"莜莜回到武汉附近一个地级市的城中村旧家，父母不在，三层农房空荡冷清。她以自家土豆与咸肉果腹，在好友聊天窗反复输入又删除，安念发现后主动关心。她用反话表达寂寞，安念却只顾游戏，直到她直说才认真陪聊。两人再约六月见面，相互表达喜欢，同时各自担忧现实相见后的未来。\",\"turn\":\"远距离恋情继续，孤独使莜莜学着明确表达需求，现实见面尚待六月。\"},\"c458\":{\"key\":\"c458\",\"title\":\"到底什么样才能算是女孩子呢\",\"kind\":\"main\",\"start\":1792,\"end\":1795,\"summary\":\"天语遥亲见阿牛葬礼，认定报复完成，换电话卡和QQ断绝旧兄弟及夏归月联系。快意之后空虚涌来，她仍想活下去，暂缓自伤念头，把尝试接受女性生活称作挑战自己。她以软陶为新网名，照镜练微笑与撒娇；父母看到她久违的自然笑容十分欣慰，只盼她能快乐生活，而她仍思念被自己单方面割舍的归月。\",\"turn\":\"报复完成未带来充实，天语遥断联旧生活后转向试着接纳自身变化。\"},\"c459\":{\"key\":\"c459\",\"title\":\"躲不过\",\"kind\":\"main\",\"start\":1796,\"end\":1799,\"summary\":\"天语遥不敢再找大黑狗或夏归月，以免割舍失败；母亲为她报陶艺班，父亲送她、因她累而背到门口，这段确属现实。进教室后，她以为夏归月坐在前排、拉她一起学习，两人久别重逢。然而后文c463揭示从进教室起这些相逢只是天语遥的幻觉，真实的她坐在无人陪伴的后排。\",\"turn\":\"父亲送学真实，进班后的重逢被后文揭为幻觉，不能记录成实际复合。\"},\"c460\":{\"key\":\"c460\",\"title\":\"叔叔，我最喜欢小遥了\",\"kind\":\"main\",\"start\":1800,\"end\":1803,\"summary\":\"在后来被c463揭穿的幻境中，夏归月追问失联，索要天语遥新号码，坚持离开才会伤害自己；天语遥教她捏陶人，并以恋人为模特受老师表扬。下课后归月要求到天家，父亲似在书店研究儿女心思，归月向他表白最喜欢小遥。现实中老师表扬的是前排别的学生，归月并未出现，父亲实际买的是玄幻小说。\",\"turn\":\"借幻觉呈现被找回与被接纳的渴望；新号码交换和父亲见恋人均非事实。\"},\"c461\":{\"key\":\"c461\",\"title\":\"我是小遥的女朋友\",\"kind\":\"main\",\"start\":1804,\"end\":1807,\"summary\":\"幻觉中的夏归月当父亲面自称女朋友，三人随后到咖啡厅吃牛排喝咖啡。天语遥既珍惜与她相守，又担心耽误她，用筷子吃牛排来化解拘谨；父亲则想象这段爱情的困难。c463纠正实际只有父女两人午餐，第三份餐是为两人食量准备，筷子也是父亲主动要来，根本没有归月见家长。\",\"turn\":\"看似现实的细节均有另一解释，幸福见家长情节是心理愿望的投影。\"},\"c462\":{\"key\":\"c462\",\"title\":\"天语遥的陶人柜\",\"kind\":\"main\",\"start\":1808,\"end\":1812,\"summary\":\"天语遥以为把夏归月带进家，获她无条件支持，展示满柜归月陶人，又为她制作七个不同人生时期的自己，放进亚克力盒。两人似乎相拥而眠，母亲也看到她们；但c463揭示夏归月从未来访：陶人柜与她捏自己的动作真实，陪伴、赠礼和父母讨论恋情皆为幻觉，她实际抱着母亲买的玩具熊睡去。\",\"turn\":\"陶艺把缺失的相守化为可触物件，七个陶人并未真正交到夏归月手里。\"},\"c463\":{\"key\":\"c463\",\"title\":\"其实都错了\",\"kind\":\"main\",\"start\":1813,\"end\":1816,\"summary\":\"叙述明确纠正前几章：天语遥进陶艺班后把旁人的言行改造成与夏归月重逢。真实课堂上她独坐后排自语、捏出异形物，老师表扬的是别人；父亲在书店买《不死不灭》，父女两人吃三份午饭。回家后她独自捏自己的陶人配在归月像旁，抱着玩具熊入睡；母亲开门打断幻境，她才明白一切，仍喊月月流泪。\",\"turn\":\"揭示现实与幻觉的边界，重逢被撤销，天语遥孤独与心理危机显露。\"},\"c464\":{\"key\":\"c464\",\"title\":\"不想分清虚幻和现实\",\"kind\":\"main\",\"start\":1817,\"end\":1820,\"summary\":\"从幻境醒来的天语遥不愿面对现实，试着继续想象夏归月却无法保持清晰。她用新QQ加入无需审核的同类群，观望热闹话题，却难以融入，还把群内谈论误作女性身份模板。随后她再次与想象的归月交谈，幻想对方支持自己、陪她回忆学校生活，晚餐也心不在焉，渐渐不想区分想象与现实。\",\"turn\":\"虚构陪伴从无意识幻觉转为主动沉溺，真正的人际联系仍未重建。\"},\"c465\":{\"key\":\"c465\",\"title\":\"辞职后想去做什么\",\"kind\":\"main\",\"start\":1821,\"end\":1824,\"summary\":\"王海峰的辞职申请终于获批，待下月发薪离职，考虑回乡做主管或筹资开小超市。员工留恋他的宽厚，翁锡芽却只愿暂代、不愿长期接主管。雨晴也明确想辞职，既因为王离去，更因超市勾起阿牛之死；王替她领表。她仍以高三实习生说辞掩饰无证件状态，看见后仓已有新人，体会旧人逐渐被日常遗忘。\",\"turn\":\"王离职已批准，雨晴着手申请，超市工作阶段进入收束。\"},\"c466\":{\"key\":\"c466\",\"title\":\"孙昊又来了\",\"kind\":\"main\",\"start\":1825,\"end\":1828,\"summary\":\"思凡提前下班接雨晴，先开辞职玩笑，后因高速骑车耗尽电力改推车回家。她心情好是因孙昊将来小城，计划接站并在外相聚；考虑雨晴次日通勤，她把电动车留下自己坐公交。雨晴仍担心孙昊会伤害思凡，却只说路上小心。晚上她与夕晨吃家常饭，并把多做的饭分给院里的哺乳母狗、孕猫与流浪动物。\",\"turn\":\"孙昊再访令思凡兴奋，雨晴对他仍不安；暂时独立通勤成为新日常问题。\"},\"c467\":{\"key\":\"c467\",\"title\":\"天语遥和陌生的网友\",\"kind\":\"main\",\"start\":1829,\"end\":1832,\"summary\":\"雨天独处的天语遥制作猫耳猫尾女武神陶人，收到群友淡蓝色的忧郁的主动私聊。她自报十八岁、没有上学，对方询问身份和生活，她多半冷淡简答。后来蓝色赠《魔兽世界》限量测试激活码并邀同玩，她选亡灵战士，对方选亡灵牧师，约用YY交流；空荡的新QQ终于出现一个朋友。\",\"turn\":\"游戏成为断联后新社交入口，蓝色主动接近的动机尚待观察。\"},\"c468\":{\"key\":\"c468\",\"title\":\"你的声音还蛮好听的\",\"kind\":\"main\",\"start\":1833,\"end\":1836,\"summary\":\"蓝色在YY称赞天语遥声音，热心陪玩却话多得让她疲倦。夜里她仍依赖想象中的归月安慰孤独；接着叙述又呈现归月问到住址、清晨来家等她的幸福相逢。到卧室听见归月赞陶人时，她惊惧抱紧对方，随即醒来发现只有阴雨与怀中的玩具熊；这场上门寻找同样只是梦或幻觉。\",\"turn\":\"新朋友未消除孤独，第二次上门重逢再被否定为虚构陪伴。\"},\"c469\":{\"key\":\"c469\",\"title\":\"各自人各自的生活\",\"kind\":\"main\",\"start\":1837,\"end\":1840,\"summary\":\"思凡与孙昊在宾馆相聚，谈到毕业后搬去他的城市，孙答应接她；她睡着后，孙却对其外貌中男性化特征流露厌恶。莜莜已找到武汉市内工作，冒雨乘车首次上班，安念的早安短信稍解独居寂寞。雨晴则被莜莜自伤的噩梦惊醒，又找不到夕晨，惶恐独留房中；梦中莜莜之死并非现实。\",\"turn\":\"远近各自开始新生活；孙昊真实的外貌排斥与思凡相守愿望形成裂缝。\"},\"c470\":{\"key\":\"c470\",\"title\":\"扶住\",\"kind\":\"main\",\"start\":1841,\"end\":1844,\"summary\":\"曲奇露出夕晨留下的有事出去纸条，让雨晴稍安。午间夕晨从黑色奔驰下车，收下一沓钱，带名牌包疲惫返家；途中莫空扶住险跌的她，伞被吹走后她拒绝共伞或借伞，独自淋雨。莫空猜她渴望别人关心，留在附近河边烤鱼。回到集装箱房，雨晴忙为浑身湿透、咳嗽乏力的夕晨擦头发并扶入浴室。\",\"turn\":\"神秘外出与现金来源未明；夕晨淋雨病倒，雨晴成为照顾者。\"},\"c471\":{\"key\":\"c471\",\"title\":\"林夕晨发烧了\",\"kind\":\"main\",\"start\":1845,\"end\":1848,\"summary\":\"夕晨疲惫发热，雨晴帮她洗漱换衣、量体温，见三十九度后细心照料并喂姜汤。夕晨难得显露撒娇与依赖，紧握雨晴的手入睡。思凡晚八点返家，说明孙昊已走，关心夕晨若不退热须就医；三人相伴休息时，她试探自己离城后雨晴怎么办。雨晴明白她想去孙昊身边，答大概仍留小城，也意识到朋友各有生活。\",\"turn\":\"照顾强化晴夕亲密，思凡首次向雨晴探问自己离城后的安排。\"},\"c472\":{\"key\":\"c472\",\"title\":\"天语遥和奇怪的小电影\",\"kind\":\"main\",\"start\":1849,\"end\":1852,\"summary\":\"失眠无聊的天语遥主动找蓝色聊天，对方暂停游戏回应，让她感到被在意。聊天转向带有身体羞辱与支配意味的成人视频，蓝色以嘲弄她幼稚来激将；她原本排斥，却逐渐被痛感与自我贬低相连的内容牵动，带着混乱和不适入睡。章末带有侵害感的海滩场景是噩梦，她惊醒，不能视作真实遭遇。\",\"turn\":\"新网友的边界试探与激将加深她的心理混乱，关怀需求被引向危险互动。\"},\"c473\":{\"key\":\"c473\",\"title\":\"严重的高烧\",\"kind\":\"main\",\"start\":1853,\"end\":1856,\"summary\":\"次晨夕晨仍高烧，思凡认为自己请假方便，送雨晴上班后带夕晨就医。初诊处理后她依旧头痛腹痛、呕吐无力，思凡背她上楼重新挂专家号，陪着做尿检、血检并等待超声检查。化验报告的染色体栏写XX，令一直相信夕晨与自己经历相似的思凡震惊，怀疑结果出错。\",\"turn\":\"持续病情促成进一步检查，XX报告开启夕晨身体身世的新线索。\"},\"c474\":{\"key\":\"c474\",\"title\":\"女性染色体\",\"kind\":\"main\",\"start\":1857,\"end\":1860,\"summary\":\"思凡先质疑XX报告，随后超声结果又让医生确认夕晨具有先天性发育差异；这些均为小说的医学情节设定。医生建议复查并向省级医院咨询，说明重大手术应在慎重选择后进行。复查结果相同，思凡在惊讶与羡慕中把消息告诉苏醒的夕晨；夕晨瞪大眼睛，第一次得知自己与长期以来认定的身体身份并不相同。\",\"turn\":\"重复检查支持书中先天性发育差异设定，改变夕晨与室友对其身份经历的理解。\"},\"c475\":{\"key\":\"c475\",\"title\":\"忍不住笑\",\"kind\":\"main\",\"start\":1861,\"end\":1864,\"summary\":\"确认检查消息后，夕晨从难以置信转为无法掩饰的欢笑，想到可以向父母解释自己、与雨晴建立未来家庭；这些生育与婚姻构想尚是她的愿望。思凡真心祝贺，却也因比较自己的处境而羡慕失落。她把夕晨送到雨晴工作的超市后返回公司，把情绪投入文稿，一口气做完原本一周的任务。\",\"turn\":\"夕晨罕见敞开情绪，思凡同时经历祝福与羡慕，以工作消化落差。\"},\"c476\":{\"key\":\"c476\",\"title\":\"有林夕晨一起陪伴的工作\",\"kind\":\"main\",\"start\":1865,\"end\":1868,\"summary\":\"夕晨到酒柜陪雨晴工作，王海峰体谅让她们在较清闲处相伴，雨晴感到平常一天格外幸福。下班后夕晨终于分享检查确认先天性发育差异的消息，雨晴真心为她高兴；她计划先存钱、回去找父母，再考虑手术。夕晨也表现出流畅说话与主动亲昵，雨晴意识到她平日沉默背后有更多未表达的情绪。\",\"turn\":\"检查消息被恋人共享，晴夕开始期待更具体的将来，尚未回家或手术。\"},\"c477\":{\"key\":\"c477\",\"title\":\"初次尝试\",\"kind\":\"main\",\"start\":1869,\"end\":1872,\"summary\":\"天语遥仍与蓝色游戏，得知对方也在小城市，却出于警惕不透露自己所在地。她厌倦网络争吵，又被蓝色此前提供的成人影像牵引，在孤独中把身体体验错当成理解女性身份的途径。母亲送茶点时她慌忙遮掩，后来父母外出，她独自尝试身体探索；这些呈现她的困惑，不构成性别认同的判断标准。\",\"turn\":\"她对网友保留地理信息边界，却仍受错误身份脚本与影像引导。\"},\"c478\":{\"key\":\"c478\",\"title\":\"夏归月的寻找\",\"kind\":\"main\",\"start\":1873,\"end\":1876,\"summary\":\"断联近一个月后，夏归月确认天语遥不辞而别，替旧号码缴费仍只能听到关机，周末翘掉兴趣课四处寻找。天的帮会已经解散，地盘被瓜分；黄枸明知住址，却认定离别是替归月好而隐瞒。她回到旧日复合公园，向沧桑男子恳求只想见面问清；对方最终留下一张纸条离去，c479确认此人是莫空。\",\"turn\":\"真正的寻找开始，黄枸以替人决定的善意阻拦，莫空最终提供方向。\"},\"c479\":{\"key\":\"c479\",\"title\":\"意外的相见\",\"kind\":\"main\",\"start\":1877,\"end\":1880,\"summary\":\"夏归月循莫空纸条向右直走，终于真正找到天语遥。天先逃跑，随后错把她当幻觉，游玩时还对树木空气说话；归月心痛陪伴，最后提醒她面对现实。天确认眼前恋人真实，却坚持离开是承担责任、免她承受社会家庭压力。归月表示愿共患难，仍未说服她，天再次挣脱跑走，留下哭泣的归月。\",\"turn\":\"此番相见是真实；幻觉穿插其间，天语遥仍单方面拒绝共同承担困难。\"},\"c480\":{\"key\":\"c480\",\"title\":\"天语遥和苏雨晴\",\"kind\":\"main\",\"start\":1881,\"end\":1884,\"summary\":\"逃离归月后，天语遥反复失去现实感，路遇购物返家的雨晴竟错认成月月。雨晴本要为阿牛质问她，见她对空气自语、神志混乱，愤怒中又生怜悯。短暂清醒的天仍不后悔报复，拒绝同情；雨晴最终没有弃她于路边，把她扶到电话亭联系母亲接回，未向其母公开报复经过。两人望同一天空，感受却截然不同。\",\"turn\":\"雨晴在谴责报复后仍救助天语遥；本段以母亲接回和未解心理危机结束。\"},\"c481\":{\"key\":\"c481\",\"title\":\"和男人去看电影\",\"kind\":\"main\",\"start\":1885,\"end\":1888,\"summary\":\"天语遥复仇后的精神困扰并未消散，只靠游戏暂时转移注意。她发现网友蓝色也住在小城市，经软磨硬泡答应影院见面；三十岁左右的蓝色不断示好，她因被当成女孩而别扭。两人看《活死人之地》，她留意自己对甜食的新偏好，继续困惑于身体与自我认知的变化。\",\"turn\":\"天语遥与蓝色由网友变成线下玩伴，创伤与身份矛盾仍在。\"},\"c482\":{\"key\":\"c482\",\"title\":\"吃豆腐？\",\"kind\":\"main\",\"start\":1889,\"end\":1892,\"summary\":\"蓝色在影院不断试探身体接触，天语遥逐渐察觉被冒犯。两人又去网吧，她在旧日混混生活的回忆里睡着，做了关于被强迫改变人生的恶梦；读者可见蓝色趁她睡着越界，她醒后却未确认。天语遥独自回家，觉得对方令人不适，同时为自身复杂感受困惑。\",\"turn\":\"蓝色的越界行为已出现；梦境不能当作真实婚姻、生育事件。\"},\"c483\":{\"key\":\"c483\",\"title\":\"天语遥和情趣用品店\",\"kind\":\"main\",\"start\":1893,\"end\":1896,\"summary\":\"阴天傍晚，天语遥偶遇消瘦的大黑狗，买火腿肠和牛奶喂它，借它想到夏归月并落泪。失去复仇目标后，她轻生念头加重。返家途中她进入无人成人用品店，买下按摩器并藏在床下；大黑狗一路跟到小区，却被保安赶走，她未注意到这次告别。\",\"turn\":\"大黑狗仍在流浪；天语遥开始以强烈感官刺激暂避痛苦。\"},\"c484\":{\"key\":\"c484\",\"title\":\"天语遥和男性用品\",\"kind\":\"main\",\"start\":1897,\"end\":1900,\"summary\":\"天语遥对食物、论坛和聊天都失去兴致，蓝色的信息使她烦躁，捏软陶也泄露出心事。深夜她尝试新买的成人用品，过程令她疲惫却暂时卸下焦虑，罕见地无梦熟睡。次晨她把这份短暂舒缓看作生活中少有的美好，也开始把它误当作解决长期痛苦的办法。\",\"turn\":\"感官刺激被当作减压依靠，不能据此理解为心理问题得到治愈。\"},\"c485\":{\"key\":\"c485\",\"title\":\"天语遥的第一次（上）\",\"kind\":\"main\",\"start\":1901,\"end\":1904,\"summary\":\"长期闲居让天语遥更觉空虚；她靠成人用品排遣情绪，又继续与蓝色在影院、网吧和海边消磨时间，逐渐容忍其陪伴。某日她穿母亲买的保守长裙赴约，看恐怖片后接受蓝色去KTV的提议。两人独处包厢、喝鸡尾酒，她忍不了蓝色的跑调歌声而接过话筒。\",\"turn\":\"关系从公共场合玩伴转入私密包厢，蓝色的追求进入危险阶段。\"},\"c486\":{\"key\":\"c486\",\"title\":\"天语遥的第一次（下）\",\"kind\":\"main\",\"start\":1905,\"end\":1909,\"summary\":\"在KTV中，天语遥饮酒后意识与行动能力受影响，蓝色仍持续越界并与她发生性接触。醒后她记起经过，陷入羞耻、自我厌弃与身份困惑，却因长期绝望而选择继续靠短暂刺激度日。蓝色达成目的后话明显变少，两人默默离开；她并未因此获得被尊重的亲密关系。\",\"turn\":\"蓝色利用脆弱与失去清醒判断的状态越界；后续快感不能抹去当时同意问题。\"},\"c487\":{\"key\":\"c487\",\"title\":\"柳韵的报复\",\"kind\":\"main\",\"start\":1910,\"end\":1913,\"summary\":\"柳韵混迹于年长无业男子群体，听蓝色炫耀天语遥的照片后认出旧仇人，决定报复她对胡玉牛之死的推动。她暗中诱导蓝色召集更多人、升级伤害。蓝色先带人参与，随后以私密照片外传威胁；天语遥虽不在乎自己名声，却怕夏归月知道，因而被迫赴下一次约。\",\"turn\":\"柳韵由悲痛转向借刀报复，照片把脆弱关系变成胁迫。\"},\"c488\":{\"key\":\"c488\",\"title\":\"比死还痛苦\",\"kind\":\"main\",\"start\":1914,\"end\":1917,\"summary\":\"天语遥的幻觉、时间错位感和自我认知混乱加剧。两天后她在照片威胁下赴地下室，被十余名男子集体侵害与虐待，蓝色发现失控却被同伙打昏。天语遥失去意识，在与夏归月结婚又遭拒绝的反复幻梦里痛苦挣扎，直到外界传来夏归月敲门呼喊旧名的声音。\",\"turn\":\"侵害造成严重身体与心理创伤；婚礼、庄园及身体变化皆为幻梦。\"},\"c489\":{\"key\":\"c489\",\"title\":\"莫空指路\",\"kind\":\"main\",\"start\":1918,\"end\":1921,\"summary\":\"夏归月后悔此前未追上天语遥，认定即使没有可预知的结局，也愿意珍惜当下相伴。她在河边再次遇见莫空，经追问与坚定表态拿到双面地址纸条，得知可能来不及便急赶海天大酒店对面胖子酒吧。她最终在自行车地下库内找到铁门，敲门大喊天冲云。\",\"turn\":\"莫空再次提供精确线索，夏归月主动选择不计结局的守护。\"},\"c490\":{\"key\":\"c490\",\"title\":\"黄枸救场\",\"kind\":\"main\",\"start\":1922,\"end\":1925,\"summary\":\"夏归月找到天语遥却险被施害者拖入。接获某人指引的黄枸带四十余名小弟及时救场，制服十余男子并报警、叫救护车。天语遥短暂清醒，与夏归月重逢后再度昏迷，仍有微弱呼吸。黄枸陪赴医院、派人通知父母，强调救人优先于抢地盘。\",\"turn\":\"天语遥获救并未死亡；黄枸与昔日对手体现互助情义。\"},\"c491\":{\"key\":\"c491\",\"title\":\"脱离危险\",\"kind\":\"main\",\"start\":1926,\"end\":1929,\"summary\":\"天语遥父母赶到医院，医生称她脱水、精力耗尽，已脱险。夏归月承认女友身份，坚持整夜守候，直到次日下午才由其母送回。病房电视播报2005年4月2日大阪飞香港的JL6910航班失联。4月4日周一清晨夏归月醒来，仍惦念昏睡的天语遥。\",\"turn\":\"身体脱险而精神结局未定；航班失联进入正文另一条主线。\"},\"c492\":{\"key\":\"c492\",\"title\":\"醒不过来\",\"kind\":\"main\",\"start\":1930,\"end\":1933,\"summary\":\"天语遥长期昏迷，母亲搬电脑到病房工作，父亲与双方律师周旋追责。夏归月每天放学来写作业、讲见闻，父母虽担忧仍允许她守候。空难残骸被找到，书内认定无人幸存。夏归月向她描绘迪士尼、西湖、北京和台湾之旅，哭着自语时忽然被天语遥握住手。\",\"turn\":\"守候成为日常，空难确认悲剧，握手预示意识开始回返。\"},\"c493\":{\"key\":\"c493\",\"title\":\"天语遥的世界（一）\",\"kind\":\"main\",\"start\":1934,\"end\":1937,\"summary\":\"叙事转入天语遥的意识世界：她在少女房间醒来，用残缺记忆拼成自己自愿女性化、卧床三年的解释，并认定这是可自由控制的梦。年轻父母送她到文澜学院，她能用念头改变他人视线；夏归月在这里是青梅竹马、同桌与亲密闺蜜，日常校园生活暂时补偿了现实遗憾。\",\"turn\":\"自愿用药、先天女孩与青梅竹马设定是梦境记忆，非现实前史。\"},\"c494\":{\"key\":\"c494\",\"title\":\"天语遥的世界（二）\",\"kind\":\"main\",\"start\":1938,\"end\":1941,\"summary\":\"天语遥在梦里睡醒后仍留在同一世界，逐渐把它视为第二现实。她操控天气、时间与生活，帮助父母升职、让已逝外公重现，也每天给夏归月惊喜。虽享有造物主般能力，她仍珍惜等待周末的期待感，并刻意不改夏归月的容貌，只反复整理逐渐模糊的现实记忆。\",\"turn\":\"天语遥沉浸理想生活，现实记忆越发被重构。\"},\"c495\":{\"key\":\"c495\",\"title\":\"天语遥的世界（三）\",\"kind\":\"main\",\"start\":1942,\"end\":1945,\"summary\":\"天语遥为带夏归月去杭州，凭意念造出机场和小客机。飞行途中真实客机穿过黑洞闯入，她担心梦境被破坏，将其强推回去，引发雷击与爆炸。随后她抹除夏归月的见闻，把旅程改写成暑假乘火车游西湖。两人在酒店谈未来开杂货店，拉钩永不分离，天语遥继续满足于补偿式幸福。\",\"turn\":\"客机灾难与现实失联新闻相接；她的幸福以控制记忆维持。\"},\"c496\":{\"key\":\"c496\",\"title\":\"天语遥的世界（四）\",\"kind\":\"main\",\"start\":1946,\"end\":1949,\"summary\":\"野餐时无法驱散的暴雨打破天语遥的全能感，两道陌生声音称她把梦接入真实世界投影、提供了通道。外来者进入后，她失去操纵时间、空间和天气的能力，只余少量异能。两天后校园生活仿佛重播最初两日，她确认世界线被重置，意识到自己已不能决定这片世界。\",\"turn\":\"全能梦境转成有独立规则的投影，重复日常提示世界重置。\"},\"c497\":{\"key\":\"c497\",\"title\":\"天语遥的世界（五）\",\"kind\":\"main\",\"start\":1950,\"end\":1953,\"summary\":\"天语遥能力持续衰退，梦中的夏归月有了其他朋友与男友；她痛苦却仍肯定对方的幸福。学校跳蚤市场上，她以仅剩力量捏陶人，为小蓝和阳光少年注入身份顺遂、相伴的祝福。随后她感知到入侵者叶雯，对方与两名同伴要求捏真人陶像，她却无法直接质问来意。\",\"turn\":\"陶人连接其他人物命运；夏归月有男友仅发生于投影世界。\"},\"c498\":{\"key\":\"c498\",\"title\":\"天语遥的世界（六）\",\"kind\":\"main\",\"start\":1954,\"end\":1957,\"summary\":\"天语遥看出叶雯灵魂缺损，将柔软的少女灵魂能量注入陶人。梦内过年后她愈发衰弱，在山头潜入叶雯的梦，见巨人击败猛虎，再构造病房说明梦境将随自己死亡而消失。她留下“这不是梦”纸条，以为即将回光返照；意识返身时握住现实夏归月的手，却不愿再睁眼。\",\"turn\":\"陶人补魂与纸条回收跨线伏笔；将死亡视为将至是天语遥判断。\"},\"c499\":{\"key\":\"c499\",\"title\":\"无法治愈了的精神分裂\",\"kind\":\"main\",\"start\":1958,\"end\":1961,\"summary\":\"天语遥睁眼后意识、身份与记忆混乱，作品中的医生判断其精神疾病严重，父母多方求医后带她回家。司法支线以一名主谋无期、其余从犯十年以上收束；父亲为加重追责耗尽大量积蓄。她先暴躁后沉默，唯对夏归月保有信任。夏归月仍每日讲故事，等待恢复的可能。\",\"turn\":\"她活着但需持续照护；精神上“死亡”属修辞，不能写成肉体死亡。\"},\"c500\":{\"key\":\"c500\",\"title\":\"王海峰离职\",\"kind\":\"main\",\"start\":1962,\"end\":1965,\"summary\":\"王海峰辞职回乡前请01部门同事吃告别饭，苏雨晴的辞职也同日生效。他向她推荐近集装箱家的郊区加油站，约定三天内答复。平日互相挤兑的同事难得齐心留下陪晚班，打牌恶作剧送别；他在梯子和仓库写下名字，笑闹背后显出对下属的不舍与对上司的失望。\",\"turn\":\"超市工作正式结束，王海峰为苏雨晴留下下一份工作机会。\"},\"c501\":{\"key\":\"c501\",\"title\":\"买书\",\"kind\":\"main\",\"start\":1966,\"end\":1969,\"summary\":\"离职后苏雨晴白日在新华书店看书，夜晚与张思凡逛市集；林夕晨打扮后独自外出，使她隐隐不安。她照顾羞涩年轻书贩生意，尝试讨价还价买小说，发现摊上非卖陶人酷似海边别墅大小姐。对方称陶人来自远方老家；张思凡取来照片，也买下《小兵传奇》。\",\"turn\":\"陶人把陌生书贩与大小姐支线相连，林夕晨外出形成疑虑。\"},\"c502\":{\"key\":\"c502\",\"title\":\"我想来找你\",\"kind\":\"main\",\"start\":1970,\"end\":1973,\"summary\":\"五月，冉空城久违来电，提出六月放假到小城市见苏雨晴。她既担心身份变化被发现，也渴望旧友接纳，反思过去依赖与暗恋，认定如今更珍惜林夕晨。午后准备面试，林夕晨拿出名贵衣裙借她；她虽怕引起误会，仍为让对方开心而接受。\",\"turn\":\"冉空城六月来访确定，身份坦白成为待解问题。\"},\"c503\":{\"key\":\"c503\",\"title\":\"随意的面试\",\"kind\":\"main\",\"start\":1974,\"end\":1977,\"summary\":\"王海峰陪苏雨晴到郊区加油站，凭与经理的交情替她安排收银工作。她反驳“花瓶”评价，却因没有身份证只能签低保障临时合同，月薪2500元、每天十二小时且有通宵班。告别王海峰后，她感激对方教会工作也能快乐；回家换下借衣，发现林夕晨珍重地收起它。\",\"turn\":\"第三份工作落定，收入提高但劳动强度与保障不足并存。\"},\"c504\":{\"key\":\"c504\",\"title\":\"莫空的一天\",\"kind\":\"main\",\"start\":1978,\"end\":1981,\"summary\":\"莫空通宵写作后离开阁楼，看见隔壁新邻居像个男学生。他随意乘公交、按任意转向步行，刻意享受不知道下一刻的生活，在旧城区工地观察菜地、池塘与生命。带走几只蝌蚪后，他偶然走到苏雨晴住处，未打扰她，只把蝌蚪放入流动小河，寄望它们去更远地方。\",\"turn\":\"莫空寻找未知与流动生活，救蝌蚪具有拯救封闭世界生命的象征意味。\"},\"c505\":{\"key\":\"c505\",\"title\":\"加油站的晚班\",\"kind\":\"main\",\"start\":1982,\"end\":1985,\"summary\":\"苏雨晴第一次在加油站值通宵班，既怕郊外黑暗又困倦，凌晨趴台睡去。下班后她等天亮人多才回家，险些困得失足，被狗惊醒后又由张思凡骑车送回。林夕晨替她盖毯拉窗帘。她明白高收入以疲惫换来，却愿为攒手术钱把长远愿望拆成可完成的小目标。\",\"turn\":\"独立生活的代价具体化，朋友照料与阶段目标支撑她继续工作。\"},\"c506\":{\"key\":\"c506\",\"title\":\"电话联络感情\",\"kind\":\"main\",\"start\":1986,\"end\":1989,\"summary\":\"张思凡致电忙于武汉工作的方莜莜，两人从生疏重新聊回亲密，得知她六月将见网恋对象。她们谈感情面对家庭与社会压力能否坚持、离开与放手的难处，也承认自己无法预知选择。听着电话，苏雨晴思念父母，暂想两三年后回去，羡慕林夕晨看似更容易的未来。\",\"turn\":\"异地友情需要主动维系；张思凡毕业投奔孙昊、苏雨晴返家仍为计划。\"},\"c507\":{\"key\":\"c507\",\"title\":\"去给安念过生日（一）\",\"kind\":\"main\",\"start\":1990,\"end\":1993,\"summary\":\"方莜莜为安念六月十九日生日筹备见面，十七日周五下班后赶武汉火车站，却遇书内临时证件查验且找不到身份证。她回家翻找、赴已关门社区均失败，焦急中几次奔波。安念建议车站补临时证件，她又赶往车站，期待的旅程刚开始便受阻。\",\"turn\":\"身份证遗失拖延出发，焦虑使简单手续演变成反复奔波。\"},\"c508\":{\"key\":\"c508\",\"title\":\"去给安念过生日（二）\",\"kind\":\"main\",\"start\":1994,\"end\":1998,\"summary\":\"方莜莜到车站才知办临时证件人员已下班，只能翌日再走。安念用短信和玩笑安慰，旧日铁友杨豪伟也因群消息来电。回忆揭示他曾在得知她女性化选择后转为支持，关系一度暧昧，后来换工作分隔。她不由比较二人的关心，又试着把对杨豪伟的感情归为友情。\",\"turn\":\"杨豪伟重新进入感情线，方莜莜的情感判断出现摇摆。\"},\"c509\":{\"key\":\"c509\",\"title\":\"去给安念过生日（三）\",\"kind\":\"main\",\"start\":1999,\"end\":2002,\"summary\":\"十八日清晨方莜莜终于拿到临时身份证，却发现买票已不再查验，哭笑不得。杨豪伟细细叮嘱旅途与识人，安念则询问车次、定时叫醒她。她在列车上补眠后于下午到杭州城站，挤过人潮与一名乘客的地域歧视，联系安念寻找出口，紧张期待真正见面。\",\"turn\":\"旅程顺利抵达，两种不同的关心持续影响她的比较。\"},\"c510\":{\"key\":\"c510\",\"title\":\"去给安念过生日（四）\",\"kind\":\"main\",\"start\":2003,\"end\":2006,\"summary\":\"安念在杭州车站认出方莜莜，她见到的青年比想象胖，却坦言仍很高兴，两人很快自在地调笑。骑电瓶车回家途中她主动拥住他，他介绍母亲已知她身份并欢迎来访。方莜莜选择住他家省钱，在旧厂宿舍区见到亲切的母亲，进入杂乱却干净的房间，一起打开电脑。\",\"turn\":\"网恋由想象进入真实相处，母亲知身份但未明确知恋爱关系。\"},\"c511\":{\"key\":\"c511\",\"title\":\"去给安念过生日（五）\",\"kind\":\"main\",\"start\":2007,\"end\":2010,\"summary\":\"安念陪方莜莜玩拳皇后被母亲叫去煎牛排，母子相互打趣的自在家庭氛围让她羡慕，也反衬自己与严父、继母的距离。晚餐用现成酱料搭配牛排，安念吃掉焦的一份和剩菜，显出幽默与节俭。方莜莜逐渐放松，关心他别勉强吃太多，亲密感在家常晚餐中加深。\",\"turn\":\"温暖家常使方莜莜卸下拘谨，更愿与安念靠近。\"},\"c512\":{\"key\":\"c512\",\"title\":\"去给安念过生日（六）\",\"kind\":\"main\",\"start\":2011,\"end\":2015,\"summary\":\"方莜莜与安念同床，发现他紧张却克制，没有擅自越界。她主动开启关于恋爱经历的谈话并邀请亲近，二人慢慢放松、彼此试探，最后握手睡去。次晨在母亲忙早餐的声音中醒来，两人因昨夜的靠近而羞涩，网恋逐渐长成真实的信任与亲密。\",\"turn\":\"安念尊重界限，方莜莜在关系中较主动，二人未发生进一步性行为。\"},\"c513\":{\"key\":\"c513\",\"title\":\"去给安念过生日（七）\",\"kind\":\"main\",\"start\":2016,\"end\":2019,\"summary\":\"六月十九日生日当天，方莜莜吃过安家早餐，羡慕母子自在争论后随安念游西湖。她珍惜牵手相伴，二人为留下纪念拍了四张照片，各保留对方单照和合影。随后经吴山广场逛河坊街，安念为她买喜欢的小物，日常消费体现关心，也让节俭的她心疼。\",\"turn\":\"照片成为首次相聚的重要纪念，相伴比景点更吸引她。\"},\"c514\":{\"key\":\"c514\",\"title\":\"去给安念过生日（八）\",\"kind\":\"main\",\"start\":2020,\"end\":2023,\"summary\":\"游河坊街时杨豪伟来电关心，方莜莜担心他吃醋，又难拒其在杭州吃饭的邀约，带安念赴会。她要求在杨豪伟面前只称安念为普通朋友，暴露自己对旧友的依恋；安念察觉却配合、不追问。四人上车，杨豪伟现女友明显不悦，原本二人生日约会转为尴尬四人行。\",\"turn\":\"方莜莜对旧友与恋人的感情冲突显形，安念选择克制照顾。\"},\"c515\":{\"key\":\"c515\",\"title\":\"请出示本人身份证\",\"kind\":\"main\",\"start\":2024,\"end\":2027,\"summary\":\"杨豪伟带女友、方莜莜与安念吃西餐，熟记方莜莜口味的照顾加重女友不悦，安念努力保持礼貌。饭后又去高档网络会所，方莜莜愿意继续留下。办上网时收银员因证件男性照片与她外表不符拒绝，安念想解释却被拉住，身份暴露的困境打断游玩。\",\"turn\":\"证件与外貌差异造成现实障碍，四人关系仍紧绷。\"},\"c516\":{\"key\":\"c516\",\"title\":\"到底是什么感情\",\"kind\":\"main\",\"start\":2028,\"end\":2031,\"summary\":\"方莜莜首先求助杨豪伟，他向会所经理解释她身份后才获准上网，但旁人眼光仍刺痛人。四人沉默地玩魔兽争霸，安念看出她对旧友的依恋却不使其难堪。离开后雨中共伞步行，方莜莜开始坦白混乱感情，称彼此是情侣并要求真心回应，安念终于承认吃醋。\",\"turn\":\"情侣开始直接谈嫉妒与依赖，安念体谅不等于没有受伤。\"},\"c517\":{\"key\":\"c517\",\"title\":\"公交卡不见了\",\"kind\":\"main\",\"start\":2032,\"end\":2035,\"summary\":\"雨中安念表示若方莜莜更爱旧友便尊重选择，她却觉得这像放弃责任，要求坦诚。他们谈无法保证的未来，最终互说爱意。回家发现借母亲的公交卡丢失，两人下楼找回，紧张转为有惊无险。之后共享姨娘订的朴素水果蛋糕，方莜莜记起安念曾送自己的蛋糕。\",\"turn\":\"明确互诉爱意，生日在小波折与亲密交谈中完成。\"},\"c518\":{\"key\":\"c518\",\"title\":\"目送着离去\",\"kind\":\"main\",\"start\":2036,\"end\":2040,\"summary\":\"方莜莜为多陪安念一天请假，担心原声破坏形象，他表示接受完整的她。第二夜两人更加亲密仍保持克制。二十日一起在网吧度过，晚间安念送站时坦言自己也曾向往女性身份，后来选择现状。两人先走错东站，幸而提前出发赶到城站，依依目送告别。\",\"turn\":\"生日之旅结束，异地恋确认；安念过去身份探索被披露。\"},\"c519\":{\"key\":\"c519\",\"title\":\"官二代的骚扰\",\"kind\":\"main\",\"start\":2041,\"end\":2044,\"summary\":\"曲奇与咖啡偷偷跟苏雨晴到加油站，陪她在白班幻想自由与未来。一位被称二少的男子买烟、无视禁烟要求并纠缠邀约，经理认出他是挂名副经理后借喝酒解围。同事称其为市长次子，依靠家庭权势游荡享乐；苏雨晴厌恶其摆阔，新的职场骚扰隐患出现。\",\"turn\":\"二少对苏雨晴起意，经理暂时解围；家庭职位来自书内同事说法。\"},\"c520\":{\"key\":\"c520\",\"title\":\"一万块钱一个晚上\",\"kind\":\"main\",\"start\":2045,\"end\":2048,\"summary\":\"二少纠缠整日，经理帮腔迫使苏雨晴赴高档餐厅。她对豪车、排场和炫耀毫不心动，离开时二少以一万元换一夜，她把钱甩回去后独自离开。气愤之外，她担忧失去工作或遭报复。张思凡到车站接她，听完经过也只能先劝避开，生活安稳受到权势骚扰威胁。\",\"turn\":\"她坚决拒绝金钱侮辱，但暂无应对二少权势的办法。\"},\"c521\":{\"key\":\"c521\",\"title\":\"陪酒（上）\",\"kind\":\"main\",\"start\":2049,\"end\":2052,\"summary\":\"林夕晨第一人称揭示寡言无表情是遮掩痛苦、避免影响苏雨晴的方式。她虽珍惜恋人相伴，仍须精心打扮去见一位秃顶富商，谎称外出事务。原有积蓄本可做矫正手术，却因父亲患病另有用途；她乘上富商的奔驰，被迫承受越来越难忍的要求来维持收入。\",\"turn\":\"林夕晨外出真正原因揭晓，保护恋人的沉默与谋生困境相连。\"},\"c522\":{\"key\":\"c522\",\"title\":\"陪酒（下）\",\"kind\":\"main\",\"start\":2053,\"end\":2056,\"summary\":\"林夕晨被富商带到郊外别墅陪酒接待生意伙伴，承受被物化和性剥削，靠酒意熬过过程。她解释稿费不足同时负担父亲治疗与全家生活，姐妹因父亲长期偏心不愿照料，自己虽想退出仍无法断钱。醒后她收下款项，梦中与苏雨晴相拥却无法消除现实负担。\",\"turn\":\"金钱暂缓家病却深化剥削与自责；父亲疗养和家庭供养持续。\"},\"c523\":{\"key\":\"c523\",\"title\":\"林夕晨第一视角\",\"kind\":\"main\",\"start\":2057,\"end\":2060,\"summary\":\"回程中林夕晨反思自由、压抑与自身复杂动机：她既希望父亲康复，也盼停止汇款、尽早完成手术退出包养。回家苏雨晴因读悲伤小说而害怕别离，主动抱住她、问能否永远相伴。林夕晨给出安慰承诺，却因自己隐瞒的经历深觉不配；被问酒味时转移话题。\",\"turn\":\"两人的深爱与信息不对等并存，“永远”是安慰而非命运保证。\"},\"c524\":{\"key\":\"c524\",\"title\":\"平静的生活，是因为有人帮你挡住了风雨，定住了波澜\",\"kind\":\"main\",\"start\":2061,\"end\":2064,\"summary\":\"二少再次以权势威胁苏雨晴赴饭局，她勉强应下但坚持乘出租车保持距离。餐厅另一边，她多年未见的大舅苏书记（原章误称大伯，c573更正）与二少父亲王市长谈升迁，认出外甥女后暗示不得乱来。王市长立即承诺照顾，潜在风波在苏雨晴毫不知情中被长辈挡下，揭开她安稳背后的隐形保护。\",\"turn\":\"大舅暗中施压平息骚扰，苏雨晴仍以为无后台；旧称大伯已由作者更正。\"},\"c525\":{\"key\":\"c525\",\"title\":\"突然的到来\",\"kind\":\"main\",\"start\":2065,\"end\":2068,\"summary\":\"二少多日不再纠缠，苏雨晴不明缘故。六月将尽，冉空城上车后才告知下午抵达，她仓促请假，惊讶经理和在场二少都痛快放行。她回家换厚实中性衣物掩饰身体变化、调整声线后接站。长高的冉空城仍把她当旧日好友，用女孩玩笑迎接，她既激动又怕秘密暴露。\",\"turn\":\"朋友到来迫使身份问题进入现实，二少已明显忌惮她。\"},\"c526\":{\"key\":\"c526\",\"title\":\"你最近过的怎么样\",\"kind\":\"main\",\"start\":2069,\"end\":2073,\"summary\":\"冉空城询问苏雨晴近况，仍以为她转学到本地；她继续隐瞒离家打工。公园聊天渐恢复熟悉感，他带来全班同学录与一盒发卡，解释一些旧同学已道歉、仍记挂她，并提到跳级的班长金晶。苏雨晴读留言感动，熟练戴上胡萝卜发卡，让冉空城对她的女性气质愈发惊讶。\",\"turn\":\"同学录重建校园记忆；所谓善意戏弄属人物解释，不能否认既有伤害。\"},\"c527\":{\"key\":\"c527\",\"title\":\"软软的，凉凉的\",\"kind\":\"main\",\"start\":2074,\"end\":2077,\"summary\":\"旧友轻松互逗，冉空城注意到苏雨晴更开朗，也被她冰凉柔软的手与拥抱触动，却以“只是男孩好友”压下异样。两人在步行街给陶坯上色，她细描哆啦A梦，他把足球涂得五彩。傍晚替他找旅馆后约次日海边，苏雨晴在他向往独住的自由时想起自己对家的思念。\",\"turn\":\"冉空城有吸引与自我压抑，尚未承认恋爱感情。\"},\"c528\":{\"key\":\"c528\",\"title\":\"湿身\",\"kind\":\"main\",\"start\":2078,\"end\":2081,\"summary\":\"翌日苏雨晴费力叫醒冉空城，两人去海边堆沙堡和海龟。冉空城玩闹把她带进浅水、意外碰触身体，引发她不适与身份冲突。她终于坦白一直想作为女孩生活、正在服药，坚决不愿回头。冉空城先担忧身体与后悔，确认她决定后仍认她为最好的朋友，并祝她幸福。\",\"turn\":\"苏雨晴向圈外最重要旧友坦白身份，得到支持与接纳。\"},\"c529\":{\"key\":\"c529\",\"title\":\"打开天窗说亮话\",\"kind\":\"main\",\"start\":2082,\"end\":2085,\"summary\":\"坦白后的二人在海边笑开，苏雨晴进一步问冉空城是否曾有恋爱式喜欢，他认真答一直视她为好友，表明自己偏爱顺性别女性。她接受边界，也说自己爱人并不先看性别。她仍隐瞒离家事实，转谈金晶跳级、将来学业与旧事，最后为投其所好约去电玩城。\",\"turn\":\"旧暗恋获明确答复，身份被接受但并未建立情侣关系。\"},\"c530\":{\"key\":\"c530\",\"title\":\"张思凡毕业了\",\"kind\":\"main\",\"start\":2086,\"end\":2089,\"summary\":\"冉空城逗留数日离开，张思凡又宣布毕业后将去孙昊处，九月土地到期也无法续租，苏雨晴须另找住所。林夕晨画下夕阳道别的人群陪她感伤。加油站首月工资另附千元奖金，引发同事恶意猜测；苏雨晴却为手术基金接近目标而振作，同时注意林夕晨常寄大笔钱回家。\",\"turn\":\"张思凡即将离开、搬家将至；奖励暗含家族保护，来钱误解增多。\"},\"c531\":{\"key\":\"c531\",\"title\":\"林夕晨的家事（上）\",\"kind\":\"main\",\"start\":2090,\"end\":2093,\"summary\":\"林夕晨独自在家笨拙做蔬菜汤，照料聚来的猫狗，珍惜平淡生活。代收店通知家信已到，她担心父亲肿瘤恶化却仍去取信。途中她看见咖啡毛色变白、活动减少，预感宠物终将告别，并担心苏雨晴会受打击。她顺路买猫狗粮与玩具，慷慨照顾动物而自己节俭。\",\"turn\":\"家信与咖啡衰老同时预告生活负担和失去；并未在此死亡。\"},\"c532\":{\"key\":\"c532\",\"title\":\"林夕晨的家事（下）\",\"kind\":\"main\",\"start\":2094,\"end\":2097,\"summary\":\"大姐艰难写成的信说明父亲劳作后病情加重，母亲坚持住院，所需钱更多。林夕晨考虑手术与长期费用，回想曾拒绝更残忍的富商朋友，如今将其当作绝境备用，却仍盼先给父亲治疗。她到加油站探望苏雨晴，分巧克力、带曲奇咖啡玩，共挤一椅获得短暂慰藉。\",\"turn\":\"经济压力再升级，更危险的交易被提出但此时未接受。\"},\"c533\":{\"key\":\"c533\",\"title\":\"只剩下两个人\",\"kind\":\"main\",\"start\":2098,\"end\":2101,\"summary\":\"张思凡正式离开投奔孙昊，集装箱只余苏雨晴与林夕晨。苏雨晴看衰老咖啡想到离别，接报平安电话时仍压下挽留，也担心孙昊为人。空冰箱提醒她必须自己当家，她将找房等计划写进日记。张思凡留下游戏机与电动车，苏雨晴笨拙载恋人进城采购，孤单中又体会二人生活。\",\"turn\":\"同住群体缩为二人，照料责任正式转交，找新房提上日程。\"},\"c534\":{\"key\":\"c534\",\"title\":\"胸部的感觉\",\"kind\":\"main\",\"start\":2102,\"end\":2105,\"summary\":\"林夕晨视角写苏雨晴紧张学骑电动车载她赴世纪联华，两人在周年促销人潮中互相照顾。她想说鼓励的话却发现长期寡言已难表达，面具成了束缚。采购间苏雨晴为身体变化挑新内衣、羞涩征求意见，林夕晨耐心协助，二人亲近，也暴露她内心远比外表活跃。\",\"turn\":\"林夕晨情感丰富的内心与沉默外貌形成反差，同居互助加深。\"},\"c535\":{\"key\":\"c535\",\"title\":\"同居的感觉\",\"kind\":\"main\",\"start\":2106,\"end\":2109,\"summary\":\"两人买下衣物、食品、记事本等许多用品，才遇到电动车如何载货的问题，最终分配重量缓慢安全回家。林夕晨回忆父亲珍爱的凤凰自行车与童年偏爱；夜路相依、狗群迎接让她感到真正同居的甜蜜，也不舍将离开郊外。安顿采购后她继续赶画稿，期待与苏雨晴相伴。\",\"turn\":\"生活琐事成为亲密体验，搬家将同时失去自然环境与动物陪伴。\"},\"c536\":{\"key\":\"c536\",\"title\":\"以后每天都一起洗澡\",\"kind\":\"main\",\"start\":2110,\"end\":2113,\"summary\":\"共浴与同寝使苏雨晴、林夕晨的身体亲密进一步发展，两人互诉爱意，但苏也多次表达羞涩、犹豫及停止的要求。次晨苏明确提出希望不要再像昨夜那样，林答应；苏赶着上班，林扶稳她并提醒骑车、吃早饭。甜蜜和边界协商并存，不能把犹豫一律当作默认同意。\",\"turn\":\"亲密关系深化，苏提出边界，林作出回应。\"},\"c537\":{\"key\":\"c537\",\"title\":\"暂未同居\",\"kind\":\"main\",\"start\":2114,\"end\":2117,\"summary\":\"张思凡已搬到孙昊所在城市，却因孙以学生宿舍不便为由，仍独住狭小出租屋，暂未求职，动用原为手术积攒的钱。她看见孙在小说读者群中广泛调情而吃醋，又顾虑管束太多。孙强烈反对她穿男装约会，随后在熟悉的校园废弃迷宫与她亲近，并答应不再乱撩。\",\"turn\":\"“投奔恋人”尚未带来同居；群聊调情、男装禁忌和熟悉隐秘约会处埋下疑问。\"},\"c538\":{\"key\":\"c538\",\"title\":\"住在一起\",\"kind\":\"main\",\"start\":2118,\"end\":2122,\"summary\":\"2005年八月中旬，方莜莜辞去武汉工作，安念进入自主实习期，两人相约赴宁波共同生活。拖着行李探索炎热街道后，他们通过中介租下便宜单间，再买钢丝床与原有小床拼接。简陋拥挤的小家令两人充满期待；方主动讨论亲密关系，安则以婚姻和责任为由迟疑。\",\"turn\":\"武汉与杭州的异地恋转为宁波共同生活，爱情开始接受现实开销与责任考验。\"},\"c539\":{\"key\":\"c539\",\"title\":\"苏雨晴和林夕晨的小窝\",\"kind\":\"main\",\"start\":2123,\"end\":2125,\"summary\":\"九月将至，苏雨晴逐渐适应加油站工作，二少仍未再纠缠。集装箱租期结束，张思凡预先找好买家，连同家具处置所得留给两人。林找到月租八百元、两人平分的海景小房，留下空调、热水器和木桌；曲奇与咖啡随迁。新居有海景、阳台厨房和窄床，但失去原来的狗群与旷野生活。\",\"turn\":\"两人迁入海景房；住房为何便宜尚未揭开，积蓄仍受生活开销牵制。\"},\"c540\":{\"key\":\"c540\",\"title\":\"苏雨晴的小回忆\",\"kind\":\"main\",\"start\":2126,\"end\":2129,\"summary\":\"夜市书摊已换了中年摊主，苏雨晴因找不到原先普通却亲切的年轻人而失落。她回想张仍同住时与卖书少年讨价还价、一起收摊避开城管，并跳上他的三轮车逃离的偶遇；事后少年道谢独自离开，她自行返回，与带回肯德基的张会合。林将她从旧日幻想唤回，两人继续买灯。\",\"turn\":\"短暂相逢成为苏珍藏的幻想；少年身份和离开原因本章均未交代。\"},\"c541\":{\"key\":\"c541\",\"title\":\"安念和方莜莜的日常（一）\",\"kind\":\"main\",\"start\":2130,\"end\":2133,\"summary\":\"在宁波找工作之前，安念与方莜莜拿纸地图逐处游玩，用五角星标记去过的地方，只剩郊外未探索。方想开奶茶店，摆脱求职时证件和外貌不符的限制；安建议先在店中学习，自己去码头挣钱减重，再共同经营。两人讨论租金、独立和女装愿望，怀抱创业憧憬；回望式叙述却预示这份相伴可能变化。\",\"turn\":\"奶茶店成为共同未来方案，但资金、工作身份及长久相伴尚无保证。\"},\"c542\":{\"key\":\"c542\",\"title\":\"安念和方莜莜的日常（二）\",\"kind\":\"main\",\"start\":2134,\"end\":2137,\"summary\":\"方莜莜做简单早餐，两人带满零食和罐头到宁波郊外踏青，看田地、施工和山边住宅，畅想山居生活。他们谈到钱与女性身份何者更重要，显出侧重差异，又用树枝当手杖攀上陡坡。山顶分享食物时，方在树上刻下两人的名字、日期及永远在一起的愿望，把出游变成对未来的约定。\",\"turn\":\"刻字约定加强伴侣共同愿景，理想生活与现实劳动形成对照。\"},\"c543\":{\"key\":\"c543\",\"title\":\"安念和方莜莜的日常（三）\",\"kind\":\"main\",\"start\":2138,\"end\":2141,\"summary\":\"初秋，两人结束游城生活。方莜莜以男装进入奶茶店，从早九点做到晚九点；安念则从早六点在码头搬货，希望挣钱并减肥。工头带队承接船货，日常伙食粗劣、劳动沉重。李船长赶来催促，虽态度傲慢，却因报酬高让工人重新振作。安拼命完成工作，领钱买小摆件回家，方还未下班。\",\"turn\":\"爱情愿景转入长工时现实；两人时刻错开，安开始积累身体疲惫。\"},\"c544\":{\"key\":\"c544\",\"title\":\"安念和方莜莜的日常（四）\",\"kind\":\"main\",\"start\":2142,\"end\":2145,\"summary\":\"安念晚间疲惫早睡，方莜莜很晚才归，亲密相处被不同班次压缩。安因天气变化到码头才知停工，工头忘了通知，便带他出海钓鱼。两人钓到一面银色、一面虹彩的奇鱼；工头提起祖辈传说，许下与女儿有关但未被完整听见的愿望，安许愿与方永远相伴，然后将鱼放生。\",\"turn\":\"奇鱼与树上誓言呼应；愿望是否灵验及工头女儿具体处境均未交代。\"},\"c545\":{\"key\":\"c545\",\"title\":\"张思凡和孙昊的日常（上）\",\"kind\":\"main\",\"start\":2146,\"end\":2149,\"summary\":\"张思凡仍未求职，去瑜伽班练体态，并努力遮掩身体特征。女教师训练严厉，其他学员的好奇触碰使她窘迫，她也拒绝结伴吃饭以自认忠于孙昊。电话中的孙气息异常，解释正与朋友玩牌，末尾又似有女子声音；张压下疑心，约定傍晚看电影，仍盼他冬季毕业后正式同居。\",\"turn\":\"张的忠诚和期待与可疑电话形成信息差，尚不知道孙的另一段关系。\"},\"c546\":{\"key\":\"c546\",\"title\":\"张思凡和孙昊的日常（下）\",\"kind\":\"main\",\"start\":2150,\"end\":2153,\"summary\":\"孙昊迟到后用拥抱和恐怖片约会安抚张思凡。张闻到他身上的香水味，孙拿出小香水瓶称是给她试用的礼物，又安排烛光晚餐，随后借朋友打架需去派出所之名离开。叙述转向孙，明确揭示他当天与莉莉亲密来往，香味来自她；他接着给莉莉打电话，买花上门，重复同样的浪漫说辞。\",\"turn\":\"孙同时交往及撒谎获得叙事确认；张被礼物解释安抚，尚不知背叛。\"},\"c547\":{\"key\":\"c547\",\"title\":\"新房子感觉怎么样？\",\"kind\":\"main\",\"start\":2154,\"end\":2157,\"summary\":\"林夕晨回到供养她的富商别墅，忆及此前寄居与陪伴富商的生活。古筝断弦后，富商带她买新琴，谈话揭露海景房本是他的产业，林坚持交租以减少亏欠。她提手术，富商表明身体改变后将停止供养，又要她介绍漂亮男孩；她想到苏雨晴后立刻拒绝。在琴店，她挑中无名制作者寄售的素木古筝，弹《高山流水》，期待弹给苏听。\",\"turn\":\"住房与经济依赖真相揭开；林保护苏却继续隐瞒，手术愿望与供养条件发生冲突。\"},\"c548\":{\"key\":\"c548\",\"title\":\"讨好\",\"kind\":\"main\",\"start\":2158,\"end\":2161,\"summary\":\"二少向苏雨晴送高级午饭，经理也主动提出雨天送她回家，她仍疑惑、戒备。叙述明确父母早知其工作生活，并请苏书记照顾；二少已知她是省委书记疼爱的侄女，讨好出于惧怕影响父亲仕途。苏雨中似见林跟着别人，回家发现新古筝；林称是客户赠礼，掩下紧张。\",\"turn\":\"家人暗中保护得到明确确认，苏仍误以为可能被父母抛弃；林的隐瞒越来越贴近生活。\"},\"c549\":{\"key\":\"c549\",\"title\":\"五倍酬劳\",\"kind\":\"main\",\"start\":2162,\"end\":2165,\"summary\":\"码头接到要求一天完成数日货量、给五倍报酬的大单，安念从清晨搬到晚九点，累得近乎虚脱；工头怀疑该船走私并运送偷渡客，但未获证实。船长额外加钱，每人实领五百。方因他不接电话担心，回家后两人相依，商量奶茶学艺将成、再等一两个月寻店，并约次日共同休息。\",\"turn\":\"挣钱与身体代价同时显现，开店计划趋于具体；船的非法活动仍仅属猜测。\"},\"c550\":{\"key\":\"c550\",\"title\":\"安念暴走\",\"kind\":\"main\",\"start\":2166,\"end\":2169,\"summary\":\"难得共同休假，安念和女装的方莜莜乘拥挤公交去大卖场。陌生男子持续性骚扰方，反在她反击后公开羞辱其性别身份，乘客也转而歧视受害者。安念由克制转为暴怒，打伤对方并拖下车，直到方担心出人命才停手。两人离开，公交司机和围观者始终未有效制止侵害。\",\"turn\":\"安以暴力保护伴侣，方得以脱身但担心后果；后续追责本章未交代。\"},\"c551\":{\"key\":\"c551\",\"title\":\"颈环\",\"kind\":\"main\",\"start\":2170,\"end\":2173,\"summary\":\"事后安念恢复平静，向方莜莜表示不会认同他人的羞辱，她既受安慰又惊讶于他首次打架的激烈。为减轻外貌被指认的压力，安买黑纱蝴蝶结铃铛颈环，再搭配猫耳发箍与发卡；方回赠连衣裙，以未来能穿下它鼓励安减重。创伤后的陪伴很快转回嬉笑购物，但社会排斥并未消失。\",\"turn\":\"衣饰兼具保护与亲密信物作用；安的女装愿望成为两人的共同玩笑和目标。\"},\"c552\":{\"key\":\"c552\",\"title\":\"爱你永不变\",\"kind\":\"main\",\"start\":2174,\"end\":2177,\"summary\":\"三组伴侣围绕“永远”呈现不同状态：孙昊熟练向张思凡承诺永不变，她连别人留下的痕迹也误认作自己；海景房中林夕晨弹筝、画下苏雨晴，听她畅想未来领养女儿，只谨慎回答会在一起很久；影院里的安念则说爱会加深，可能逐渐成为亲情。并置使言辞、行动与未来的不确定性彼此映照。\",\"turn\":\"相同的永伴愿望背后，分别存在欺骗、隐忧和共同生活理想。\"},\"c553\":{\"key\":\"c553\",\"title\":\"重阳节\",\"kind\":\"main\",\"start\":2178,\"end\":2181,\"summary\":\"书内十月十一日重阳节，苏雨晴趁国庆后调休与林夕晨登一座荒凉无名山。途中蛇袭击苏，曲奇扑救，又保护在草丛探路的咖啡。山顶石头布满青苔，泥土与腐木渗出红液，令苏联想到血与万人坑，两人决定离开；叙述另提出矿物染色的可能，未证实鬼神或埋尸之说。\",\"turn\":\"宠物护主再次突出；红土荒山留下疑问，原因只给可能解释。\"},\"c554\":{\"key\":\"c554\",\"title\":\"猛烈的台风\",\"kind\":\"main\",\"start\":2182,\"end\":2185,\"summary\":\"台风袭击海景房，两人相拥避风，苏讲科幻小说中记忆上传和模拟世界的故事。梦里她重返破旧公园，穿裙子的小男孩展示“上帝的盒子”，从太阳系缩放至她与林睡着的房间。苏顺手拔起屋外模型树；次晨现实中的树竟处于相同位置，她震惊后以台风巧合自解，开始怀疑人生是否被无形力量推动。\",\"turn\":\"梦与现实出现可对应的物理痕迹，仍未确认盒子与世界的本体关系。\"},\"c555\":{\"key\":\"c555\",\"title\":\"去势手术（上）\",\"kind\":\"main\",\"start\":2186,\"end\":2189,\"summary\":\"十月底工资到账，苏雨晴攒够一万一千元，提出辞职便获迅速批准，经理另付补贴，她仍不知家族影响。回家见林异常疲倦，却尊重其沉默不再追问。次晨苏说明准备去孔雀处接受身体手术，按预计八千费用、三千生活预留安排积蓄；林答应照料，却因自己手术迟迟无法实现而走神。\",\"turn\":\"离家后首个重要身体目标资金到位；停止收入与林的隐性压力成为后续条件。\"},\"c556\":{\"key\":\"c556\",\"title\":\"去势手术（中）\",\"kind\":\"main\",\"start\":2190,\"end\":2193,\"summary\":\"手术前一天苏雨晴与林夕晨去游乐园尽情游玩，翌日到孔雀私人诊所。面对不可逆变化、与家庭关系及未来道路，她虽恐惧，仍确认自身决定；孔雀讲另一位患者后悔的经历再询问，随后实施手术。苏术后从昏沉中醒来感到疼痛。诊所过程含不当言行与医学叙述，不能将其当成规范医疗示范。\",\"turn\":\"苏自愿完成去势手术，进入康复阶段；她的认同和选择并未因此后悔。\"},\"c557\":{\"key\":\"c557\",\"title\":\"去势手术（下）\",\"kind\":\"main\",\"start\":2194,\"end\":2197,\"summary\":\"苏雨晴术后疼痛但明显感到卸下负担，在诊所多休息两天后由林陪同回家。富商开奔驰来接，林向苏称他是客户，又用阑尾手术说法遮掩；苏接受帮助仍感到疑惑。回家后林照顾饮食和日常。富商私下以高额报酬诱使林带苏参与其圈子的性交易，林再次明确拒绝，保护与隐瞒同时加深。\",\"turn\":\"手术完成并获得照护，苏首次直接接触富商而不知真相；林拒绝出卖伴侣。\"},\"c558\":{\"key\":\"c558\",\"title\":\"各自的家人\",\"kind\":\"main\",\"start\":2198,\"end\":2202,\"summary\":\"叙事转向各家父母：林父病重仍饮酒、拒医并想亲自收麦，责骂女儿、不愿接受女婿帮助，又盼儿子过年返乡；林母反驳他的重男轻女。张父母以大学毕业的孩子为荣，准备年终交创业款。另一组父亲和继母讨论生女儿及叫旧子回家。苏父母已知女儿近况，父亲愿支持她坚持的性别选择，却仍决定等三年期限届满再接回。\",\"turn\":\"苏的家庭已发生她未知的态度变化；林父的病、偏见和返乡要求持续施压。\"},\"c559\":{\"key\":\"c559\",\"title\":\"捉个正着\",\"kind\":\"main\",\"start\":2203,\"end\":2206,\"summary\":\"十一月，孙昊连续一周推说忙毕业不见面，张思凡借酒排遣，被搭讪时拒绝，翌日发热仍为约会细心打扮。孙让她到跃龙宾馆八〇六，她却误上六楼，听见六〇六中孙与另一女子谈论昨夜亲密。爱与愤怒使她无法离开；房门打开，孙当场见到她，长期疑点终于成为无法回避的事实。\",\"turn\":\"张亲自撞破背叛，约会转成对质；是否分手尚待下一章。\"},\"c560\":{\"key\":\"c560\",\"title\":\"玩玩而已\",\"kind\":\"main\",\"start\":2207,\"end\":2210,\"summary\":\"被撞破后，孙昊冷淡承认交往只是为猎奇，称已厌倦，拒绝张思凡提出的修复机会，还以钱和性别羞辱践踏其感情。张扇他耳光后离开，回家陷入悲痛、发热与自毁念头，随后重新审视身份与未来。苏雨晴来电问候时，张只在长久沉默后说“不做女人了”，没有解释背叛经过。\",\"turn\":\"恋爱正式结束；张在创伤下选择改变人生方向，苏仅知其决定。\"},\"c561\":{\"key\":\"c561\",\"title\":\"不做女人了\",\"kind\":\"main\",\"start\":2211,\"end\":2214,\"summary\":\"张思凡迅速处置女性化用品，剪成平头，将衣物、化妆品和药物埋在曾与孙约会的校园迷宫，当晚乘火车回南方家乡。他回想早先扮演理想女友、后来为孙投入女性身份的心路，认定现在更愿以男性生活。父母热情接纳，并告知已筹十几万元供年后创业。此为张个人自我理解，不能推广为其他人的性别经验。\",\"turn\":\"张以男性身份回归家庭并准备创业，退出原来的转变道路；孙线在本段结束。\"},\"c562\":{\"key\":\"c562\",\"title\":\"方莜莜和安念的奶茶店\",\"kind\":\"main\",\"start\":2215,\"end\":2218,\"summary\":\"安念通过半个多月联络超市管理者，与方莜莜租下废弃保安亭，办手续并刷成粉蓝色，改成小奶茶店。两人合并积蓄购设备，除奶茶还卖烤肠、炸鸡等小食。开业低调，客人不多，安坚持自己学习操作却屡次炸焦食物，方笑着帮助、阻止他硬吃。首日收入有限，两人仍相信生意会逐渐好转。\",\"turn\":\"奶茶店从愿望变为共同事业，初期盈利不足但合作关系稳定。\"},\"c563\":{\"key\":\"c563\",\"title\":\"古筝伴奏\",\"kind\":\"main\",\"start\":2219,\"end\":2221,\"summary\":\"十一月已过大半，苏雨晴术后获准适量活动，每日与林夕晨去海边晒太阳。林带古筝反复调试、谱成一支兼有忧伤与快乐的新曲，苏跟着轻哼，吸引路人倾听；林将它命名《鹰》，未解释缘由。苏打算年前找临时工作补充积蓄，考虑促销又担心口才，林表示有钱并以亲吻回应相伴。\",\"turn\":\"《鹰》成为两人共享的音乐记忆；苏希望恢复收入，林隐忧仍未说出。\"},\"c564\":{\"key\":\"c564\",\"title\":\"电瓶车相撞\",\"kind\":\"main\",\"start\":2222,\"end\":2225,\"summary\":\"奶茶店经营近一个月后客流渐旺，两人也遇到找错钱、收假钞的烦恼。方莜莜突然腹痛头晕，安念代做全部工作，让她先回家。她坚持省钱骑电动车，却在路口因卡车遮挡与另一电动车相撞，人未明显受伤，对方索赔不让走。接到电话的安立即关店奔赴现场，将伴侣安危放在营业之前。\",\"turn\":\"方身体不适与交通纠纷叠加，安暂停生意前去支持。\"},\"c565\":{\"key\":\"c565\",\"title\":\"气势压倒\",\"kind\":\"main\",\"start\":2226,\"end\":2229,\"summary\":\"交警录像确认碰撞双方都有责任，但中年车主仍向病中的方莜莜索要五千元。安先礼貌核实、劝和，对方持续辱骂并准备动手后，他以激烈言语和殴打逼退对方，带方回家。没有继续营业，他给方煮姜粥、加肉松并陪伴休息。方感到受保护，后续索赔或法律结果本段未出现。\",\"turn\":\"两人脱离现场并休息，安保护心与易升级冲突的处事方式同时显现。\"},\"c566\":{\"key\":\"c566\",\"title\":\"遍体凌伤\",\"kind\":\"main\",\"start\":2230,\"end\":2233,\"summary\":\"村长代写的家书说林父肿瘤恶变，需次年二月前手术，费用至少十万，林仅有两三万积蓄。秃顶富商要求她带苏换钱，也提出高息借款；林动摇一夜，见苏信任的笑容后放弃。她转而接受介绍，赴另一名施虐富商处承受高价侵害，计划三次凑足钱。第二次遭多人严重虐待后，她带晚餐回家，隐瞒伤势倒头睡去。\",\"turn\":\"林守住不牺牲苏的底线，却将自身置于更严重侵害中，救父与自我保存陷入困局。\"},\"c567\":{\"key\":\"c567\",\"title\":\"忧心忡忡\",\"kind\":\"main\",\"start\":2234,\"end\":2237,\"summary\":\"第二个小城市圣诞节到来，苏雨晴发现林夕晨蜷缩发冷、噩梦惊醒，袖口露出明显淤痕；林以摔跤解释，苏不信却暂不追问。两人带着不适去商场，林行走、手臂碰触都疼痛发颤，苏术后也不能久走。最终在路边买圣诞衣帽，气氛比昔日合租清冷，苏愈发珍惜身边最后的陪伴。\",\"turn\":\"林的受伤无法完全遮掩，苏担忧加深，却尚未知施虐与救父筹款真相。\"},\"c568\":{\"key\":\"c568\",\"title\":\"偷看林夕晨洗澡\",\"kind\":\"main\",\"start\":2238,\"end\":2241,\"summary\":\"圣诞夜，林夕晨反常拒绝共浴。苏雨晴因担心而偷看，发现她全身多处淤伤和伤口、清洗时痛苦难支；随后明确询问，希望共同承担困难。林先说摔跤，被指出背上也有伤后改称美容按摩，苏联想到母亲经历，终于半信半疑接受。窥见伤势并没有带来坦诚，反而形成新的善意却错误的解释。\",\"turn\":\"苏已见严重伤势却被按摩说辞安抚，林继续独自承受；“美容疗效”不能当医学结论。\"},\"c569\":{\"key\":\"c569\",\"title\":\"促销员的工作（上）\",\"kind\":\"main\",\"start\":2242,\"end\":2245,\"summary\":\"元旦后，苏雨晴为年关开销寻临时工作，在大润发门前应聘咖啡促销。招聘者简单面谈后录用，她以寒假高中生身份签约，工作至除夕，底薪八百加销量提成。重返超市，她遇到寒假兼职的周超、仍在工作的夏仕尼及主管张燕，熟人唤起旧日记忆；真正站上地堆时，她又为主动叫卖胆怯。\",\"turn\":\"苏获得独立临时收入机会，再次面对羞怯与离校身份隐瞒。\"},\"c570\":{\"key\":\"c570\",\"title\":\"促销员的日常（下）\",\"kind\":\"main\",\"start\":2246,\"end\":2249,\"summary\":\"促销地堆设在冷柜旁的僻处，苏雨晴最初只敢等人试饮，销量很低。海边别墅的美丽少女来买酸奶，她鼓勇推介咖啡，对方温和购买大盒，使她有信心向更多人开口。晚间周超请她吃烧烤，闲谈大学生活；苏羡慕求学机会，又用复读的谎言遮掩实际离校经历，友情使她轻松，也触动失学遗憾。\",\"turn\":\"第一次成功推销带来勇气；别墅少女支持与大学话题分别推动社交成长和内心遗憾。\"},\"c571\":{\"key\":\"c571\",\"title\":\"夕子姐姐，为什么要这么做？！\",\"kind\":\"main\",\"start\":2250,\"end\":2252,\"summary\":\"年前下班回家，苏雨晴亲眼看见林夕晨被臃肿富商带上车，对方公开提及金钱性交易并诱邀苏。苏震惊追问，林只劝她回去、请求不要伤害她。富商趁苏混乱将她推入车内，许诺只让她旁观并加钱；林因救父筹款无法离去，苏则执意留下，希望阻止伴侣继续。车辆抵达湖边别墅，隐瞒终于被撕开。\",\"turn\":\"苏被卷入危险并确认林受供养交易，却还不知道筹款救父的全部原因。\"},\"c572\":{\"key\":\"c572\",\"title\":\"我来代替\",\"kind\":\"main\",\"start\":2253,\"end\":2256,\"summary\":\"湖边别墅内，壮汉将苏雨晴束缚，迫她旁观林夕晨遭严重虐待。为阻止伤害，苏要求代替林，施虐者借“自愿”之名也侵害她，两人先后昏迷。秃顶富商带保镖与相机闯入，指责老李违背约定，对方反揭其意在竞争利益；对峙中武警冲入包围众人。苏的选择处于胁迫情境，不能当成自由同意。\",\"turn\":\"苏以保护林为由被迫卷入侵害；武警及时介入，救援来源待下一章揭明。\"},\"c573\":{\"key\":\"c573\",\"title\":\"苏雨晴大舅的震怒\",\"kind\":\"main\",\"start\":2257,\"end\":2260,\"summary\":\"武警抓走现场人员，将苏雨晴、林夕晨送医；救援来自大舅获报信，同行邋遢男子被称莫家家主，拒绝等苏醒来便离去。秃顶富商原本并非为警方取证，主要想谋商业利益。医院救治后两人无生命危险，大舅要求王副局长严办李任飞并通知苏父母，父母对接回女儿再起分歧。苏在昏沉梦中与林相伴，醒来庆幸彼此尚在。\",\"turn\":\"两人获救存活，家族保护从暗处走向苏的视野；李任飞被拘，具体刑期未交代。\"},\"c574\":{\"key\":\"c574\",\"title\":\"我……还不想回去\",\"kind\":\"main\",\"start\":2261,\"end\":2264,\"summary\":\"醒来后苏雨晴认出大舅，仍不愿返家；大舅谎称父母不知，尊重她表面的选择，给每月十万额度的卡及联系方式。叙述补出苏父母同姓、两支远房家族婚姻旧事。林终于坦白父亲癌症需钱，还差五万，苏毫不犹豫交卡帮她，并支持她带款回乡探望父母。受伤后的两人第一次共同面对救父压力，林却仍担心家人接受不了自己。\",\"turn\":\"资金困局获得帮助，林决定返乡；家人态度与苏期待之间仍有危险落差。\"},\"c575\":{\"key\":\"c575\",\"title\":\"暂时的分别\",\"kind\":\"main\",\"start\":2265,\"end\":2268,\"summary\":\"2006年1月20日，两人伤势恢复后，苏请假送林夕晨乘K1103返乡。林带着救父钱与年后回来的约定，漫长车程仍挡不住两人依依不舍。送别后苏不愿回空屋，走到公墓买纸花祭胡玉牛，为昔日疏远而愧疚，盼其不再受苦。章末说明公墓所立是衣冠冢，骨灰另葬村边。\",\"turn\":\"暂别实际上成为两人现实中的最后相见；此时双方仍真诚期待年后重聚。\"},\"c576\":{\"key\":\"c576\",\"title\":\"孔雀被抓\",\"kind\":\"main\",\"start\":2269,\"end\":2272,\"summary\":\"林离开后，苏雨晴独居思念，从手机新闻得知孔雀因无照手术及伤害案被捕。群聊称未成年小云术后后悔、父母起诉，并回忆孔雀资助小琳、免费帮助叶子；关于动机的说法来自群成员。其他私下手术者暂时停业。苏再联系张思凡，他明确已停止女性化并谈身体恢复，态度较从前疏淡。\",\"turn\":\"孔雀被捕改变社群支持条件，张的生活方向已经改变；苏身边旧联系进一步疏远。\"},\"c577\":{\"key\":\"c577\",\"title\":\"林夕晨的长途旅行\",\"kind\":\"main\",\"start\":2273,\"end\":2276,\"summary\":\"林夕晨在长途坐席列车上抱着苏准备的零食和礼物，短信因山区信号稀薄难以往返。近乡之际，她回想父亲曾单独带她乘绿皮车、托关系读好高中和粗糙手掌的疼爱，又想到这种照顾建立在“唯一儿子”的期待上。最小姐姐为求学被打、被断食的旧事，使她对以女性面貌返家越发不安。\",\"turn\":\"父爱的条件性与姐妹遭遇形成危险预示，林仍怀期待继续返乡。\"},\"c578\":{\"key\":\"c578\",\"title\":\"新年之前\",\"kind\":\"main\",\"start\":2277,\"end\":2281,\"summary\":\"除夕前奶茶店最后营业日，安念与方莜莜清理存货、相伴过夜，次日分别乘车回杭州和武汉。安回家与父母嬉笑，母亲关心瘦身和饮食，父亲把他的电脑弄乱，熟悉琐事让家显得温暖。方返家途中遇多年未见表哥，被唤旧名宇悠；表哥热情提行李、忆童年游戏，她把男友说成女友，仍被亲情触动。\",\"turn\":\"两对返乡路径对照：安拥有自然亲密的家庭，方仍隐藏身份与恋情。\"},\"c579\":{\"key\":\"c579\",\"title\":\"一个人的春节\",\"kind\":\"main\",\"start\":2282,\"end\":2285,\"summary\":\"苏雨晴首次独自过除夕，上午采购迟了，只买到零散蔬菜，再添肉、鱼和速冻食品。她给曲奇做鱼、陪咖啡吃饭，哼歌料理以缓解空虚，却不断想起父母、方莜莜传授厨艺、张思凡早年扶持及林的陪伴。烟花越热闹，屋内越显孤寂；她仍安慰自己林过几天就会回来。\",\"turn\":\"宠物成为仅有的现场陪伴，苏在未知死讯时继续等待与伴侣重聚。\"},\"c580\":{\"key\":\"c580\",\"title\":\"相亲\",\"kind\":\"main\",\"start\":2286,\"end\":2289,\"summary\":\"返乡后的张思凡在父母安排下与邻村董花火相亲。董比他至少大三岁，外地工作、爽朗主动，见他发冷便换有暖炉的座位，也支持其互联网创业设想。张仍为既往药物经历和身体状况担忧，未坦白过去，只想敷衍试见；董却直接表达好感，提出交往培养感情，挽他下楼，两人的新关系开始。\",\"turn\":\"张获得新恋爱机会，但身体与旧情经历仍未说明，关系只是开始试交往。\"},\"c581\":{\"key\":\"c581\",\"title\":\"不接受\",\"kind\":\"main\",\"start\":2290,\"end\":2293,\"summary\":\"林夕晨抵达雪封山村，旧路唤起最小姐姐被剥夺求学、十七岁被安排出嫁的记忆。母亲见她女性装扮十分惊讶，要求赶在父亲醒来前换男装；林解释身体检查与女性认同，母亲仍不接受，称作男人才有地位。父亲下楼认出她后脸色剧变，返家带来的希望迅速被家庭旧观念压迫。\",\"turn\":\"生理说明与情感诉求均未得到母亲理解，父亲的暴力冲突即将爆发。\"},\"c582\":{\"key\":\"c582\",\"title\":\"死吧死吧死吧！\",\"kind\":\"main\",\"start\":2294,\"end\":2297,\"summary\":\"林坚持自己的女性身份，父亲殴打她并锁入柴房，逼她改口；母亲试图阻止却被推开，随后整日无人送食水。林在旧伤、饥寒、绝望中精神崩溃，留下扭曲画痕，夜间逃出后杀害父母，再自杀。临终恢复片刻清醒，后悔无法挽回，并向苏告别。正文明确林与双亲死亡，这一结局不能理解为解脱或团聚的实现。\",\"turn\":\"筹款救父返乡以家庭暴力、杀亲和自杀告终；林与苏的重聚愿望彻底破灭。\"},\"c583\":{\"key\":\"c583\",\"title\":\"林夕晨的画\",\"kind\":\"main\",\"start\":2298,\"end\":2301,\"summary\":\"大年初一，苏雨晴仍收不到林的回复，翻看留家的画稿以解思念。她发现《家》雪村图，以及与温暖油画对应的扭曲抽象画，父亲骑车、城市、海滩人物在另一个版本中都显得可怖；她疑惑后仍归作涂鸦。孔雀案已有十年刑期并赔尽积蓄的结果，群内关注渐散。苏再发短信无回音，只好独自出门。\",\"turn\":\"读者已知林死亡而苏仍等待；画作成为复杂内心的残留证据，孔雀案获得刑罚结局。\"},\"c584\":{\"key\":\"c584\",\"title\":\"死讯\",\"kind\":\"main\",\"start\":2302,\"end\":2305,\"summary\":\"空城步行街上，苏雨晴接到显示“夕子姐姐”的电话，本以为等来重聚消息，警方却通知林杀害父母后自杀，死亡已超过三天。她无法接受，回忆初见、取暖、上一年初一相恋和海景房生活，在悲恸中昏倒。邋遢男子抱她离开长椅的场景由此展开，后两章将揭示为梦境叙事。\",\"turn\":\"警方正式将死讯带给苏；爱人死亡成为现实认知，梦中告别即将展开。\"},\"c585\":{\"key\":\"c585\",\"title\":\"去面对（上）\",\"kind\":\"main\",\"start\":2306,\"end\":2309,\"summary\":\"梦境延续：莫空守在河堤，等苏雨晴醒后递八宝粥，听她表达想再见爱人的悲痛。苏质疑陌生人擅自带走自己，也担忧无证件不能远行；他未承诺复活，只问是否想见最后一面，她哭着肯定后被邀出发。c586末揭示全段为长椅梦中告别，苏未实际赴山村，林未复活。\",\"turn\":\"c586末揭为长椅梦中告别：苏未实际赴山村，林未复活；莫空提供梦中引导。\"},\"c586\":{\"key\":\"c586\",\"title\":\"去面对（下）\",\"kind\":\"main\",\"start\":2310,\"end\":2313,\"summary\":\"梦中莫空称大舅早备机票，带无证件的苏顺利乘专机般航班、出租车与摩托抵达林家。她抱住遗体哭泣，莫空以蓝光使林短暂回应；林诉说爱意，劝苏即使失去自己也继续经历生活。林化作星光、世界崩塌，苏醒来仍在原长椅，已是月夜。整个赴乡及“复活”是梦中告别，现实里没有成行或复生。\",\"turn\":\"c586末揭示长椅梦中告别，苏未实际赴山村、林未复活；莫空是否干预梦境仍是疑问。\"},\"c587\":{\"key\":\"c587\",\"title\":\"替她好好活下去\",\"kind\":\"main\",\"start\":2314,\"end\":2317,\"summary\":\"苏回家仍在梦与现实间挣扎，翌晨幻见林在床边，电话却已关机。论坛转载新闻的地点、细节与照片确认死者就是夕子，且与她梦中场景相同。她一度考虑追随爱人死亡，却因自身想活、尚有愿望，以及梦中林的劝慰而停下。保存林的记忆、代她体验余下人生，成为继续生活的支点。\",\"turn\":\"苏确认死讯后经历自杀危机但未实施，选择活下去并记住林。\"},\"c588\":{\"key\":\"c588\",\"title\":\"莫空和秋易\",\"kind\":\"main\",\"start\":2318,\"end\":2321,\"summary\":\"莫空在雪后天台堆雪人，遇高中生邻居秋易，以笔名莫成自我介绍。秋父母已去世，靠遗产并赚生活费独居，两人结伴扫墓。莫空到胡玉牛衣冠冢点庙中蜡烛，感叹自己警示未被听取，并谈一条未实现的幸福可能。柳韵带白花来，嘴上责骂、称最后一次探望，离开时却落泪，悲伤并未因报复消失。\",\"turn\":\"莫空与秋易建立邻里联系；胡的另一种未来仅为莫空所述可能，柳韵仍受失落牵动。\"},\"c589\":{\"key\":\"c589\",\"title\":\"大黑狗\",\"kind\":\"main\",\"start\":2322,\"end\":2325,\"summary\":\"扫墓归来，莫空向秋易编讲朋友故事，并未真实说明胡玉牛。小区楼下两人发现瘦弱受伤的大黑狗，莫空认出它是天语遥旧日喂养的狗，因主人出事、旧团伙散去而失去照料。秋坚持尽力帮助，触动原本淡漠的莫空，两人回屋找香肠、小鱼干等食物，再到楼下喂它，新的陪伴开始萌芽。\",\"turn\":\"秋的善意推动莫空实际援助，失主动物线与新人物线在此交会。\"},\"c590\":{\"key\":\"c590\",\"title\":\"黑皇\",\"kind\":\"main\",\"start\":2326,\"end\":2329,\"summary\":\"吃过食物的大黑狗跟上天台，秋易决定收养，以缓解彼此孤独；莫空为它取名黑皇，狗从流浪得到稳定住处。莫空回房删除刚写的万余字章节，凝望窗外许久，动机未明。夜深曲奇像老友一样来访，接受小鱼干，莫空向它问“她”近况，暗示他与宠物及苏的生活有未明联系。\",\"turn\":\"黑皇正式获收养；删稿和曲奇夜访加深莫空作为观察、干预者的谜团。\"},\"c591\":{\"key\":\"c591\",\"title\":\"颓废\",\"kind\":\"main\",\"start\":2330,\"end\":2333,\"summary\":\"苏抱着林留下的等身毛绒熊长久失眠、少进食，连宠物也挨饿；曲奇带咖啡外出觅食，还给她带鱼回来。两只动物的亲昵唤起她的责任感，她想到父母、表哥和未完成愿望，决心继续活着。睡过一整天后她艰难下楼吃早餐，钱不够添食时莫空再次出现，替她点嵌糕豆浆并温和相陪。\",\"turn\":\"求生决定仍需落实到吃饭睡眠；宠物和现实中的莫空帮助苏恢复基本生活。\"},\"c592\":{\"key\":\"c592\",\"title\":\"树苗\",\"kind\":\"main\",\"start\":2334,\"end\":2337,\"summary\":\"早餐后莫空点明苏曾想离开世界，又否认受她父母雇派，竟复述梦中林的告别话，使她怀疑他能进入梦境。他带苏看水泥缝中屡被踩踏仍存活的小树苗，安静听她从离家讲到身份困境与失去林的经历。苏把羞耻、自卑说出口，莫空鼓励坦诚面对内心，为她提供不带排斥的倾听。\",\"turn\":\"梦中信息与现实人物对应，超自然关联加强；苏找到讲述经历与重建信心的出口。\"},\"c593\":{\"key\":\"c593\",\"title\":\"当知道真正的我的时候，你还会用司空见惯的笑脸和我说话吗？\",\"kind\":\"main\",\"start\":2338,\"end\":2341,\"summary\":\"河边长谈后莫空告诉苏，她的前方比想象中光明。两人即兴合唱，苏想到冉空城虽曾承诺不变、后来联系渐少，问出得知真实自己后是否仍会被温柔相待的疑虑。莫空坚定回应，鼓励她保持内心坦诚。她感谢后离开，重新感受春日生机；莫空独自回味歌词，态度温柔，关系意义仍未完全揭开。\",\"turn\":\"苏在被理解的对话中暂时恢复希望；冉的疏远与莫空的接纳形成对照。\"},\"c594\":{\"key\":\"c594\",\"title\":\"恢复平静了的日子\",\"kind\":\"main\",\"start\":2342,\"end\":2345,\"summary\":\"苏重新做饭照顾宠物、清理屋子，把林的遗物珍重装进上锁行李箱，继续怀念但开始恢复日常。翌日出门仍习惯向林告别，随后意识到只剩自己。为充实生活她寻找安静且适合的工作，避开需证件的中介，看到宠物店招人便进去；面对十八岁以上要求，她再次谎称成年，实际只有虚岁十七。\",\"turn\":\"苏把纪念和生活区分开，主动寻找有兴趣的新工作。\"},\"c595\":{\"key\":\"c595\",\"title\":\"宠物店（上）\",\"kind\":\"main\",\"start\":2346,\"end\":2349,\"summary\":\"店主风音喜欢苏照料的曲奇、罕见紫色咖啡，热情录用她，首月两千、之后两千五，并包两餐及宠物口粮。签合同时风音突然询问性别，苏紧张后仍填女；风音道歉不再追问。苏第一天逗奶猫、观察喂食，得知风音原是白领、父母在国外，与妹妹同住。工作带来真实兴趣，也埋下身份被识出的不安。\",\"turn\":\"苏找到愿意接纳其宠物的雇主，兴趣与收入结合；风音已对其经历有所猜测。\"},\"c596\":{\"key\":\"c596\",\"title\":\"宠物店（下）\",\"kind\":\"main\",\"start\":2350,\"end\":2353,\"summary\":\"宠物店首日忙碌中，苏雨晴感到照顾动物的满足。傍晚风音妹妹风羽蓝从补习班来送饭，姐妹嬉笑，她与苏礼貌结识；随后男友辉来接她约会。风音虽开玩笑吃醋，仍大方放行。苏羡慕这份家人与恋人同在的温暖，也想起林，萌生留长发、扎双马尾的念头。\",\"turn\":\"苏接触新的温暖关系网，思念转为可延续的生活细节。\"},\"c597\":{\"key\":\"c597\",\"title\":\"遛狗的工作\",\"kind\":\"main\",\"start\":2354,\"end\":2357,\"summary\":\"入职第三天，苏学习剪爪、打理宠物，曲奇抗拒剪爪便作罢；风音负责为顾客的贵宾犬豆豆洗澡。郑太太来电请人遛萨摩耶大白，风音把原由小蓝做的任务交给苏，画路线、让她自留五十元酬劳。苏到清河小区别墅接狗，看到郑太太将大白视为家人，对方温顺回应，新任务开始。\",\"turn\":\"苏得到独立遛狗责任及额外收入，宠物与家人的主题延伸到新顾客。\"},\"c598\":{\"key\":\"c598\",\"title\":\"解开束缚后的奔跑\",\"kind\":\"main\",\"start\":2358,\"end\":2361,\"summary\":\"曲奇、咖啡与大白相处友好，苏误以为大白会听话，解开牵引后它立刻奔跑，她担心丢狗赔钱拼命追赶，累得心肺不适。三只动物见她倒在草地便回头关心，大白随后放慢脚步领路，最终到河边找到熟悉的风羽蓝。一次过度追逐暴露苏的体弱，也让自由与照护责任发生具体冲突。\",\"turn\":\"大白没有失踪，苏恢复后继续同行；解绳导致的失控不可当养宠操作建议。\"},\"c599\":{\"key\":\"c599\",\"title\":\"逃课的少男少女\",\"kind\":\"main\",\"start\":2362,\"end\":2365,\"summary\":\"河边风羽蓝其实逃补习课与金家辉约会，苏识趣带大白走远，却因眼前情侣重新思念林并强烈想回学校。她翻看旧手机仅存的五十张照片，林弹筝、旧合租伙伴与房内景物唤回两年得失。到点她重新系好狗绳送回大白，郑太太满意，付一百元含额外小费，遛狗任务顺利完成。\",\"turn\":\"新工作带来肯定，校园与亲密关系的遗憾继续存在，旧照片成为重要记忆载体。\"},\"c600\":{\"key\":\"c600\",\"title\":\"你果然是男孩子\",\"kind\":\"main\",\"start\":2366,\"end\":2369,\"summary\":\"晚间风音与苏共餐，询问离家和求学经历，苏含糊应对。风音随后越界触碰其私密部位，使她恐惧身份暴露；得知苏想做女孩并使用药物后，风音表示接受，承认举动突然并鼓励她。她还说明妹妹风羽蓝具有双性发育特征，已做手术，男友知情。苏既羡慕又感激被接纳，但接纳不能抵消身体边界被侵犯。\",\"turn\":\"苏向新雇主坦白身份后继续获支持；小蓝身份与既有陶人祝福线形成重要可核对联系。\"},\"c601\":{\"key\":\"c601\",\"title\":\"夏日炎炎\",\"kind\":\"main\",\"start\":2371,\"end\":2374,\"summary\":\"2006年初夏，雨晴在宠物店逐渐恢复平静，风音给予理解和帮助。她带大白在河边树下避暑，读高中语文书，重新怀念求学生活；曲奇陪着已经衰老的咖啡。午睡又进入公园梦，试图带少年离开却不断绕回秋千，并经历梦中醒来，暴露出仍未摆脱的内在束缚。\",\"turn\":\"重返校园的愿望萌生，咖啡衰老与公园牢笼持续铺垫。\"},\"c602\":{\"key\":\"c602\",\"title\":\"2006 年的台风\",\"kind\":\"main\",\"start\":2375,\"end\":2378,\"summary\":\"台风将至，风音让雨晴提前下班。她收起阳台物品，独自面对第三个夏天的风雨，回忆第一年合租伙伴及第二年夕晨相伴的温暖。她已逐渐走出夕晨去世后的失控悲痛，并蓄发寄托怀念；咖啡对爱吃的食物也提不起精神，衰老征兆更加明显。\",\"turn\":\"独居的清冷与咖啡的衰弱并置，下一次失去即将到来。\"},\"c603\":{\"key\":\"c603\",\"title\":\"咖啡死了（上）\",\"kind\":\"main\",\"start\":2379,\"end\":2382,\"summary\":\"台风夜雨晴早睡，再梦见雪中的公园与篝火旁的少年；少年说等天亮自然能离开。曲奇焦急叫醒她，带她发现咖啡已失去呼吸与心跳。她无法接受又一位家人离去，致电仍在店里的风音，抱着纸盒冲入暴雨，希望获得最后一次挽救的机会。\",\"turn\":\"咖啡已死亡；雨晴仍把赴宠物店求救当作最后希望。\"},\"c604\":{\"key\":\"c604\",\"title\":\"咖啡死了（下）\",\"kind\":\"main\",\"start\":2383,\"end\":2386,\"summary\":\"雨晴在台风中奔跑跌倒，纸盒脱手，咖啡遗体落入排水道被冲走；她又被风卷起的铁桶击昏。莫空、邻居秋易和黑狗黑皇发现并救她到秋易家。醒来后她拒绝留宿，借伞返回寻找无果，接受咖啡自然死亡却遗憾无法安葬，最后穿湿衣疲惫地睡倒在地。\",\"turn\":\"咖啡遗体遗失；莫空的救助重新进入雨晴生活，受寒引发后续病情。\"},\"c605\":{\"key\":\"c605\",\"title\":\"发烧\",\"kind\":\"main\",\"start\":2387,\"end\":2390,\"summary\":\"雨晴在湿衣与地板上睡了一夜，醒来身体极度不适。风音电话询问并准假，她坚持自行去医院，艰难乘车后险些摔倒。莫空及时扶住她，陪她挂专家号、填写病历。孤身生病的无助被实际照料打破，她在牵手同行中感到意外的安心。\",\"turn\":\"疾病使雨晴接受莫空帮助，二人的信任开始迅速加深。\"},\"c606\":{\"key\":\"c606\",\"title\":\"贫血低烧\",\"kind\":\"main\",\"start\":2391,\"end\":2394,\"summary\":\"候诊时雨晴出现强烈既视感，仿佛预见旁人摔倒和医生叫号；她还因莫空帮助别人而失落。小说中的中医诊断贫血、着凉并提示其他健康问题。莫空付款取药，承诺代煎，并解释自己受她大舅安排照顾她。雨晴既感动又介意这是否只是工作，回家途中已期待被他特别对待。\",\"turn\":\"莫空受大舅委托的说法解除警惕，也让雨晴纠结照顾是否出于感情。\"},\"c607\":{\"key\":\"c607\",\"title\":\"中药的香味\",\"kind\":\"main\",\"start\":2395,\"end\":2398,\"summary\":\"莫空在雨晴家煎药、煮粥、清扫并照顾她休息。雨晴由此想起亲人的保护，萌生回家的念头，也越来越希望他长久留下。莫空外出采购至傍晚归来，带回食品、猫罐头和进口药物，又泡出与她童年相似的蜂蜜果茶；钥匙的变化预示他已经准备持续来照料。\",\"turn\":\"照料唤醒家庭记忆，雨晴在依赖中对莫空萌生感情。\"},\"c608\":{\"key\":\"c608\",\"title\":\"无微不至的照顾\",\"kind\":\"main\",\"start\":2399,\"end\":2402,\"summary\":\"莫空的果茶和饮食照顾让雨晴想起母亲为她学习营养知识的往事。翌晨他用配好的钥匙再次送来早餐，病情好转的雨晴穿上夕晨送的校服去上班，莫空一路护送。她主动问晚上是否还来，随后因喜欢莫空而对夕晨心生愧疚；风音则鼓励她面对新的感情。\",\"turn\":\"新的依恋与对亡者忠诚之间形成雨晴的心理冲突。\"},\"c609\":{\"key\":\"c609\",\"title\":\"曲奇的世界\",\"kind\":\"main\",\"start\":2403,\"end\":2406,\"summary\":\"本章以拟人化的曲奇视角重述咖啡死亡：它先察觉老友衰弱，最终唤醒雨晴求助。咖啡离去使它更珍惜朋友，它把莫空视作可靠的人，并希望两人相伴，以免雨晴孤独。曲奇与黑皇交流时听说另一只黄白猫异常聪明，留下跨故事的动物线索。\",\"turn\":\"咖啡与曲奇的深厚情谊得到补叙；曲奇希望保护雨晴，却未料她会先离世。\"},\"c610\":{\"key\":\"c610\",\"title\":\"田螺先生？\",\"kind\":\"main\",\"start\":2407,\"end\":2410,\"summary\":\"雨晴下班失望地没见到莫空，却在家发现他早已备好晚餐。莫空连曲奇喜欢干燥猫粮都清楚，像田螺先生般自然地进入生活。他答应照顾到她回家，雨晴反而把归期推迟到头发能扎双马尾时。夜里她重新感到独居空旷，翌晨又迎来他准备的早餐。\",\"turn\":\"雨晴开始期待持续陪伴，对回家与分离产生新的矛盾。\"},\"c611\":{\"key\":\"c611\",\"title\":\"夜晚的楼顶天台\",\"kind\":\"main\",\"start\":2411,\"end\":2414,\"summary\":\"莫空逐渐每天接雨晴下班，风音时常打趣两人的关系。雨晴既享受照顾又害怕将来失去，主动提出去他的天台住处看看。途中疲惫又扭脚，莫空背她上楼并处理伤处；她在安全感、羞怯与对夕晨的愧疚间摇摆，随后期待一起露天烧烤。\",\"turn\":\"主动探访使关系更亲密，莫空通过实际行动回应她的脆弱。\"},\"c612\":{\"key\":\"c612\",\"title\":\"铁桶烧烤\",\"kind\":\"main\",\"start\":2415,\"end\":2418,\"summary\":\"雨晴在莫空天台吃铁桶烧烤，发现他独居时常吃方便面，却为她准备细致丰盛的食物。她把简陋天台感受为城市里的桃源，幸福更多来自陪伴。暴雨突然来临，莫空收拾并坚持送她回家；雨晴没说出口想留宿，却主动让他靠近伞下，两人的身体与感情距离进一步缩短。\",\"turn\":\"雨中共伞让含蓄依恋转为双方可以感知的亲近。\"},\"c613\":{\"key\":\"c613\",\"title\":\"和风羽蓝一起看店\",\"kind\":\"main\",\"start\":2419,\"end\":2422,\"summary\":\"2006年7月2日，风音出门约会，风羽蓝代为开宠物店。雨晴熟练承担清洁和照顾动物的工作，从羽蓝的生疏看到自己过去的模样，也为店里淘汰成年花枝鼠的做法难过。两人忙完后准备吃金家辉送来的披萨，在阅读、猫陪伴和阳光中分享平淡午后。\",\"turn\":\"雨晴已从初入社会的怯弱者成长为能独当一面的店员。\"},\"c614\":{\"key\":\"c614\",\"title\":\"星探\",\"kind\":\"main\",\"start\":2423,\"end\":2426,\"summary\":\"金家辉送披萨来，与风羽蓝谈到高中毕业及和朋友同读大学的约定，触动雨晴重返学校的愿望。自称深井娱乐公司星探的男子邀两位女孩演戏，两人均拒绝，身份真伪未证实。风音狼狈归店，称因约会对象拒绝她而打了对方，令在场三人错愕，也表现她冲动强势的一面。\",\"turn\":\"拒绝出名守住普通生活，校园话题再次加深雨晴的归家愿望。\"},\"c615\":{\"key\":\"c615\",\"title\":\"扎一个双马尾\",\"kind\":\"main\",\"start\":2427,\"end\":2430,\"summary\":\"头发终于长过肩，雨晴用黑檀木梳、黑发绳和小花发卡扎起双马尾，既兴奋又怀念曾替夕晨梳发的亲密。早餐间莫空承认自己留在小城市是因为她，并补充不是工作缘故；随后告知7月15日是生日，邀请她晚间去游乐园。一个多月相伴已成为她生活中不可缺的一部分。\",\"turn\":\"双马尾成为怀念与新生活的共同标志，莫空首次明确排除纯工作动机。\"},\"c616\":{\"key\":\"c616\",\"title\":\"莫空的生日\",\"kind\":\"main\",\"start\":2431,\"end\":2434,\"summary\":\"莫空生日当晚，两人到郊区游乐园乘摩天轮、吃简单小食。雨晴期待告白却又害羞；游玩后仍执意给他寻找生日蛋糕，终于买到剩下的小奶油蛋糕并插上蜡烛。莫空表示有她便足够，她也坦承相伴让自己开心，含蓄完成心意确认。\",\"turn\":\"双方以生日陪伴和简短话语确认恋爱心意。\"},\"c617\":{\"key\":\"c617\",\"title\":\"我……想回家\",\"kind\":\"main\",\"start\":2435,\"end\":2438,\"summary\":\"莫空送雨晴一条红色猫眼石银手链作护身符，她回赠珍爱的泰国佛珠。得到无条件接纳及归家后仍会相伴的保证，雨晴下定决心回父母家。翌晨她辞去宠物店工作，与莫空亲昵称呼彼此，带上夕晨遗物和曲奇出发，也在心里承诺携夕晨的那份继续快乐生活。\",\"turn\":\"互换信物确立关系，回家决定终结三年漂泊。\"},\"c618\":{\"key\":\"c618\",\"title\":\"杭州\",\"kind\":\"main\",\"start\":2439,\"end\":2442,\"summary\":\"归途上曲奇随两人同行，莫空证实三年前列车上那位邻座就是自己，只称最初是偶遇。雨晴梦到能够生育并给孩子取名语默，醒后莫空知道此名，解释她说了梦话。抵达杭州，她拿出保留三年、已经生锈的家门钥匙；同一条铁路从逃离路线变成带着爱与希望的回家路。\",\"turn\":\"首程列车伏笔回收，语默之名首次在梦中埋下收养女儿的线索。\"},\"c619\":{\"key\":\"c619\",\"title\":\"车祸？\",\"kind\":\"main\",\"start\":2443,\"end\":2446,\"summary\":\"两人乘公交返回杭州家中，莫空突然带雨晴和行李跳车，随后轿车撞上公交并引发爆炸。他称是自己家族的人追杀自己。车内乘客却在第二次爆炸前全部逃出，无人员伤亡；雨晴怀疑他有超常力量，他仅以运气解释。惊险过后两人步行继续归家。\",\"turn\":\"莫家威胁首次正面暴露；莫空超常能力仅有暗示，身份尚待说明。\"},\"c620\":{\"key\":\"c620\",\"title\":\"回家\",\"kind\":\"main\",\"start\":2447,\"end\":2450,\"summary\":\"雨晴用旧钥匙打开家门，发现母亲正照顾新生的弟弟苏冬凌。母亲激动拥抱她，以女儿相称并表达无论怎样都是自己的孩子。莫空自称未来女婿并送自制香水。母亲说明父母早知她的住处，为避免强制带回激化矛盾才暗中照看，原准备接她回来，三年的家庭隔阂开始解除。\",\"turn\":\"母亲公开接纳女儿身份，雨晴从惧怕被拒绝转为获接纳的感动。\"},\"c621\":{\"key\":\"c621\",\"title\":\"爸爸妈妈\",\"kind\":\"main\",\"start\":2451,\"end\":2455,\"summary\":\"母亲介绍冬凌与姐姐相认，化解雨晴担心自己被取代的心结。父亲赶回家后温柔拥抱她，接纳莫空的陪伴。晚餐中父母了解莫空写小说、认识女儿三年等情况，欣赏他的谈吐与见识，逐渐认可这段关系。莫空仍选择自行租屋，约好翌日再来，雨晴感到亲情与爱情同时归位。\",\"turn\":\"父亲接纳完成家庭和解，父母基本认可莫空为未来女婿。\"},\"c622\":{\"key\":\"c622\",\"title\":\"做好准备了吗？\",\"kind\":\"main\",\"start\":2456,\"end\":2459,\"summary\":\"雨晴洗浴后发现母亲准备了与当年被父亲烧毁的第一套女装近乎相同的白裙，房间也早增添女装与玩偶，意识到父母长期的歉意和准备。父亲主动敲门询问她是否已决定以女性身份生活，继而告知手术、身份变更、迁往台湾及重新上学均已筹划，全家将陪她开始新生活。\",\"turn\":\"烧裙创伤以补买同款回收；父母由阻止者转为转变与迁居的支持者。\"},\"c623\":{\"key\":\"c623\",\"title\":\"南屏山\",\"kind\":\"main\",\"start\":2460,\"end\":2463,\"summary\":\"雨晴带莫空游西湖、南屏山净慈寺，并抽得上上签，期待手术及台湾新生活。莫空承诺同行，透露自己曾是莫家家主，因厌倦争斗离开，族人因忌惮他才追杀。两人在清静处坦诚交谈，雨晴愈加自在；父母的安排与莫空的陪伴让未来看似顺遂。\",\"turn\":\"莫空家主身份揭晓，并将迁台与躲开家族争斗联系起来。\"},\"c624\":{\"key\":\"c624\",\"title\":\"心理测试\",\"kind\":\"main\",\"start\":2464,\"end\":2467,\"summary\":\"回家后的雨晴安睡到中午，与依恋自己的弟弟逐渐亲近。父亲带她到同学开设的心理诊所做手术前评估，医生通过轻松交谈了解她长期的女性认同，并同意开具相关证明。父亲再问是否准备好，她承认变化来得突然，却充满幸福与期待。\",\"turn\":\"手术所需评估在小说情节中通过，家庭支持转入实际办理阶段。\"},\"c625\":{\"key\":\"c625\",\"title\":\"最终的一步（上）\",\"kind\":\"main\",\"start\":2468,\"end\":2471,\"summary\":\"父亲花半个月完备手续并调整证件年龄，最终选择带全家赴芝加哥接受手术。莫空因未办签证留在国内，送她到机场并等待归来。飞行途中雨晴反思三年漂泊，也看见父母为自己劳心而衰老。她对身份转换保持坚定，同时带着手术前的紧张和期待。\",\"turn\":\"漫长愿望进入实施阶段，雨晴暂别莫空接受家人陪护。\"},\"c626\":{\"key\":\"c626\",\"title\":\"最终的一步（下）\",\"kind\":\"main\",\"start\":2472,\"end\":2475,\"summary\":\"全家抵达芝加哥并适应时差，父亲奔走办理医院手续，母亲协助沟通。小说将手术医院设为西北纪念医院。雨晴确认只接受与性别转换有关的手术，拒绝额外丰胸等项目；各项检查与准备完成后，她在父母鼓励下进入手术室，等待已久的改变正式开始。\",\"turn\":\"手术开始；原文医疗程序只按情节记录，不作为现实指南。\"},\"c627\":{\"key\":\"c627\",\"title\":\"破蛹成蝶（上）\",\"kind\":\"main\",\"start\":2476,\"end\":2479,\"");
